import type { Cefr, NativoCard } from "@/lib/types";

/** tarjetas Nativo de cada idioma, con la lección que las trae y su nivel */
export const nativoByLang: Record<string, { card: NativoCard; lessonId: string; level: Cefr }[]> = {
  "de": [{"card":{"id":"nat-f0-1","book":"Hallo!","real":"Na?","meaning":"Hola, ¿qué tal? — todo en una sílaba","when":"Entre amigos y gente que ya se conoce. A un desconocido, en una tienda o a tu jefa: Hallo o Guten Tag.","register":"amigos","note":"El saludo que ningún libro enseña: cortísimo y con tono de pregunta. A menudo va doblado: «Na, alles gut?».","sound":"¿naa? — alargada y con entonación de pregunta","level":"a1"},"lessonId":"f0l1","level":"a1"},{"card":{"id":"nat-f0-2","book":"Wo wohnst du?","real":"Wo wohnste?","meaning":"¿Dónde vives?","when":"Con amigos, hablando rápido. Con Sie no existe — y al escribir van siempre las dos palabras.","register":"amigos","note":"El verbo en -st y el du se funden al hablar: wohnst du → wohnste, hast du → haste, bist du → biste, kannst du → kannste.","sound":"vo VOONS-te","level":"a1"},"lessonId":"f0l2","level":"a1"},{"card":{"id":"nat-f2-1","book":"Auf Wiedersehen!","real":"Mach's gut!","meaning":"¡Cuídate! / ¡Que te vaya bien! — despedida entre amigos","when":"Al despedirte de amigos y compañeros. En el banco, con tu jefa o con desconocidos: Auf Wiedersehen o Tschüss.","register":"amigos","note":"Literal: «hazlo bien». La respuesta clásica entre colegas: «Mach's besser!» — «¡hazlo tú mejor!».","sound":"majs guut","level":"a1"},"lessonId":"f2l2b","level":"a1"},{"card":{"id":"nat-f2-2","book":"Ich stehe um sieben Uhr auf.","real":"Ich steh' um sieben Uhr auf.","meaning":"Me levanto a las siete.","when":"Al hablar, casi siempre: ich steh', ich geh', ich hab'. Al escribir (fuera de mensajes entre amigos), la -e completa.","register":"neutral","note":"La -e de la forma de ich se come al hablar: stehe → steh', gehe → geh', habe → hab'. También en el infinitivo: gehen → geh'n.","sound":"ij shtee um ZII-ben úa auf","level":"a1"},"lessonId":"f2l3","level":"a1"},{"card":{"id":"nat-f3-1","book":"Ich hätte gern einen Kaffee.","real":"Ich krieg' 'nen Kaffee, bitte.","meaning":"Me pones un café, por favor. (kriegen = recibir, el verbo coloquial de pedir)","when":"En un café informal o un puesto de comida, entre habituales. Tú pide con la fórmula del libro: siempre queda bien.","register":"amigos","note":"Los artículos se comen al hablar: einen → 'nen, eine → 'ne, ein → 'n. «'nen Kaffee» es lo que oirás en la barra.","sound":"ij criik nen KA-fee BÍ-te","level":"a1"},"lessonId":"f3l1","level":"a1"},{"card":{"id":"nat-f3-2","book":"Gibt es Äpfel?","real":"Gibt's Äpfel?","meaning":"¿Hay manzanas?","when":"En todas partes al hablar — hasta en la tele. Solo al escribir formal se separa: gibt es.","register":"neutral","note":"El es se funde con el verbo: gibt es → gibt's. La oirás también como saludo entre amigos: «Was gibt's?» (¿qué hay?, ¿qué pasa?).","sound":"guipts ÉP-fel","level":"a1"},"lessonId":"f3l5","level":"a1"},{"card":{"id":"nat-f4-1","book":"Das ist meine Küche.","real":"Guck mal, meine Küche!","meaning":"¡Mira, mi cocina! — enseñando la casa","when":"Enseñando algo a amigos o familia. En contextos formales se presenta sin «guck mal», como el libro.","register":"amigos","note":"guck = mira; el «mal» no significa nada solo — suaviza la orden y la vuelve amable. Lo oirás pegado a muchos imperativos: «Komm mal her».","sound":"guk mal, MÁI-ne KÜ-je","level":"a1"},"lessonId":"f4l1","level":"a1"},{"card":{"id":"nat-f5-1","book":"Das ist okay.","real":"Passt schon.","meaning":"Está bien así / me vale / no pasa nada","when":"Cerrando una quedada («¿a las 7?» — «Passt schon») o quitando importancia a algo pequeño. En un email formal: escribe la frase completa.","register":"neutral","note":"passen = encajar: «ya encaja». Su primo para confirmar planes es «Geht klar!» (vale, hecho).","sound":"past shoon","level":"a1"},"lessonId":"f5l5","level":"a1"},{"card":{"id":"nat-f7-1","book":"Die Jacke ist schön, nicht wahr?","real":"Die Jacke ist schön, oder?","meaning":"La chaqueta es bonita, ¿verdad?","when":"Al final de casi cualquier frase para buscar acuerdo, con todo el mundo. «ne?» es aún más informal — solo con amigos.","register":"neutral","note":"El «nicht wahr?» de los libros casi no se oye: la calle remata con «oder?» o con un mínimo «ne?».","sound":"di YÁ-ke ist shöön, ó-da","level":"a1"},"lessonId":"f7l3","level":"a1"},{"card":{"id":"nat-f8-1","book":"Es tut weh!","real":"Doch!","meaning":"¡Que sí! / ¡Sí que duele! — le da la vuelta a un «no»","when":"Cuando alguien afirma algo en negativo y tú lo desmientes: «Das tut nicht weh.» — «Doch!». Por ahora solo reconócelo.","register":"neutral","note":"Una sílaba que contradice la frase negativa entera. Es la partícula estrella del alemán hablado — producirla bien llega en niveles siguientes.","sound":"doj (o corta y seca)","level":"a1"},"lessonId":"f8l2","level":"a1"},{"card":{"id":"nat-a2m1-1","book":"Ich habe viel gemacht.","real":"Ich hab' viel gemacht.","meaning":"He hecho mucho / hice mucho","when":"Al hablar, casi siempre: el «habe» entero suena a lectura en voz alta. Al escribir (correo, examen): habe, con su -e.","register":"neutral","note":"La -e final de habe se cae en el habla rápida: hab'. La pinza no cambia — solo el auxiliar viaja más ligero.","sound":"ij JAB fiil gue-MAJT","level":"a2","itemId":"a2m1natvhab"},"lessonId":"a2m1l3","level":"a2"},{"card":{"id":"nat-a2m2-1","book":"Hast du das gesehen?","real":"Haste das gesehen?","meaning":"¿Has visto eso? / ¿Viste eso?","when":"Entre amigos, en pleno viaje o contándolo. En una ventanilla o con desconocidos: la del libro (Hast du / Haben Sie).","register":"amigos","note":"hast + du se funden en el habla rápida: haste. Igual bist du → biste. Es tu Perfekt del módulo, a velocidad real.","sound":"JAS-te das gue-ZEE-en","level":"a2"},"lessonId":"a2m2l5","level":"a2"},{"card":{"id":"nat-a2m3-1","book":"Es war okay.","real":"Na ja, es war okay.","meaning":"Bueno... estuvo bien (con matiz de «más o menos»)","when":"Al abrir una respuesta sincera pero tibia: «Wie waren deine Noten?» — «Na ja...». En un correo formal no se escribe.","register":"neutral","note":"Na ja gana medio segundo y avisa: viene una respuesta con matices. La oirás en cada entrevista de calle.","sound":"na YAA — es vaa o-KEE","level":"a2"},"lessonId":"a2m3l3","level":"a2"},{"card":{"id":"nat-a2m4-1","book":"Ja, das mache ich.","real":"Mach ich!","meaning":"¡Yo me encargo! / ¡Hecho!","when":"Respuesta a un favor o encargo entre conocidos: «Kannst du mir helfen?» — «Mach ich!». En un correo formal, la del libro.","register":"neutral","note":"El «das» se cae y el verbo salta delante: Mach ich. Dos sílabas que prometen ayuda — las oirás a diario.","sound":"MAJ ij","level":"a2"},"lessonId":"a2m4l7","level":"a2"},{"card":{"id":"nat-a2m5-1","book":"Ich weiß es nicht.","real":"Keine Ahnung.","meaning":"Ni idea / no lo sé","when":"Respuesta rápida entre conocidos: «Wo ist mein Handy?» — «Keine Ahnung». Con tu jefa o en el examen: Ich weiß es nicht.","register":"neutral","note":"die Ahnung = la sospecha, la noción. Keine Ahnung es LA respuesta alemana cuando no se sabe algo — dos palabras y ya.","sound":"KAI-ne AA-nung","level":"a2","itemId":"a2m5natvkeineahnung"},"lessonId":"a2m5l1","level":"a2"},{"card":{"id":"nat-a2m6-1","book":"Ah, ich verstehe.","real":"Ach so!","meaning":"¡Ah, claro! / ahora lo entiendo (el clic al oír la razón)","when":"Cuando una explicación te hace clic: «Warum? — Weil...» → «Ach so!». Vale con cualquiera; en un texto escrito no pinta nada.","register":"neutral","note":"El sonido oficial del entendimiento alemán. Lo oirás decenas de veces al día — y responde solo, sin gramática.","sound":"aj ZOO","level":"a2"},"lessonId":"a2m6l1","level":"a2"},{"card":{"id":"nat-a2m6-2","book":"Das ist so.","real":"Ist halt so.","meaning":"Es lo que hay / las cosas son así (resignación tranquila)","when":"Solo para reconocerla: cierra charlas entre amigos cuando ya no quedan razones que dar. No la digas tú aún — sin el tono justo suena cortante.","register":"amigos","note":"halt (y su gemela eben) no traducen nada: son partículas que tiñen la frase de «no hay vuelta que darle».","sound":"ist jalt zo","level":"a2"},"lessonId":"a2m6l6","level":"a2"},{"card":{"id":"nat-a2m7-1","book":"Das ist in Ordnung.","real":"Passt schon.","meaning":"Está bien así / no pasa nada / vale","when":"El comodín amable de cada día: en el probador («¿Te queda bien?» — «Passt schon»), al dejar el cambio, al quitar hierro. En un correo formal: la del libro.","register":"neutral","note":"Fórmula segura — esta sí puedes decirla. passen (quedar bien de talla) + schon: literalmente «ya encaja».","sound":"past shoon","level":"a2","produce":true,"itemId":"a2m7natvpasstschon"},"lessonId":"a2m7l4","level":"a2"},{"card":{"id":"nat-a2m7-2","book":"Das stimmt nicht.","real":"Quatsch!","meaning":"¡Qué va! / ¡tonterías!","when":"Entre amigos, para tumbar una exageración: «Teurer ist immer besser!» — «Quatsch!». Con desconocidos o en el trabajo: la del libro.","register":"amigos","note":"der Quatsch = la tontería. También en «So ein Quatsch!». Cariñoso dentro de la confianza, brusco fuera de ella.","sound":"KVACH (la ch como en «chico»)","level":"a2"},"lessonId":"a2m7l6","level":"a2"},{"card":{"id":"nat-a2m8-1","book":"Wirklich?","real":"Echt?","meaning":"¿En serio? / ¿de verdad?","when":"Reacción a cualquier noticia: «Ich fühle mich schlecht» — «Echt?». Universal al hablar; en un texto formal, wirklich.","register":"neutral","note":"echt = auténtico. Sola y con tono de pregunta, es LA reacción alemana — muestra que escuchas y pide más detalles.","sound":"¿ejt? (ch suave de «ich»)","level":"a2"},"lessonId":"a2m8l1","level":"a2"},{"card":{"id":"nat-a2m9-1","book":"Auf Wiedersehen!","real":"Bis dann!","meaning":"¡Hasta luego! (nos vemos pronto, sin fecha exacta)","when":"Para colgar una llamada o cerrar un chat con gente que verás pronto. En una ventanilla o con clientes: Auf Wiedersehen.","register":"neutral","note":"Fórmula segura — dila sin miedo. Toda la familia funciona igual: bis dann, bis später, bis morgen.","sound":"bis DAN","level":"a2","produce":true,"itemId":"a2m9natvbisdann"},"lessonId":"a2m9l5","level":"a2"},{"card":{"id":"nat-a2m10-1","book":"In Ordnung, das mache ich.","real":"Geht klar!","meaning":"¡Hecho! / cuenta con ello (confirmación rápida)","when":"Entre colegas y conocidos, para confirmar un Termin o un encargo. En un correo al jefe o a un cliente: la del libro.","register":"neutral","note":"Fórmula segura — puedes decirla. Hermana de Alles klar: klar (claro) es el sí relajado del alemán hablado.","sound":"gueet KLAA","level":"a2","produce":true},"lessonId":"a2m10l5","level":"a2"},{"card":{"id":"nat-b1m1-1","book":"Ich habe eine Wohnung gefunden.","real":"Ich hab' 'ne Wohnung gefunden.","meaning":"He encontrado piso","when":"Con amigos y hablando: así suena de verdad. Lo que no se hace nunca es ESCRIBIRLO — ni en un correo a la casera ni en el Schreiben: allí «eine» va entera y sin apóstrofo.","register":"amigos","exam":"Ich möchte Ihnen mitteilen, dass ich eine Wohnung gefunden habe.","note":"«'ne» es «eine» comida por el habla rápida; también verás 'nen (einen) y 'nem (einem). Reconocerlo te ahorra media conversación.","sound":"ij jab ne VOO-nung gue-FUN-den","level":"b1","produce":true,"itemId":"b1m1natnewohnung"},"lessonId":"b1m1l1","level":"b1"},{"card":{"id":"nat-b1m1-2","book":"Die Wohnung ist sehr teuer.","real":"Die Wohnung ist voll teuer.","meaning":"El piso es carísimo","when":"Entre amigos y sobre todo entre menores de 35. Con la casera, en un correo o en el examen, «voll» te tira el registro abajo: allí, sehr / ziemlich / extrem — o directamente una fórmula de opinión.","register":"jerga","exam":"Die Wohnung ist meiner Meinung nach viel zu teuer.","note":"«voll» sustituye a «sehr» en el habla juvenil: voll gut, voll nett, voll teuer. Lo oirás cien veces en cualquier WG.","sound":"dii VOO-nung ist fol TOI-a","level":"b1","produce":true,"itemId":"b1m1natvollteuer"},"lessonId":"b1m1l4","level":"b1"},{"card":{"id":"nat-b1m1-3","book":"Das ist mir egal.","real":"Das ist mir wurscht.","meaning":"Me da igual","when":"Con amigos, y sobre todo en el sur de Alemania y en Austria. Con la casera, con el jefe o en el examen, no. Y ojo: cambiarlo por «Das ist mir egal» tampoco basta — no es incorrecto, pero suena seco y en el Sprechen se lee como desinterés.","register":"regional","exam":"Das spielt für mich keine große Rolle.","note":"También se oye «Das ist mir wurst». Literalmente «eso me es salchicha»: la comida como medida de la indiferencia.","sound":"das ist mia vursht","level":"b1","produce":true,"itemId":"b1m1natwurst"},"lessonId":"b1m1l7","level":"b1"},{"card":{"id":"nat-b1m1-4","book":"Melde dich bitte, wenn du Zeit hast.","real":"Meld dich mal!","meaning":"¡Da señales de vida! / ¡Escríbeme!","when":"Al despedirte de un amigo, en persona o por WhatsApp. En un correo formal o en la Aufgabe 3 del Schreiben no cabe: allí el cierre es una fórmula de cortesía entera.","register":"amigos","exam":"Ich würde mich freuen, bald von Ihnen zu hören.","note":"La -e de «melde» se cae, y «mal» quita toda presión: no es una orden, es un «a ver si hablamos». Cierra el 80% de los WhatsApp alemanes.","sound":"melt dij mal","level":"b1","produce":true,"itemId":"b1m1natmelddich"},"lessonId":"b1m1l8","level":"b1"},{"card":{"id":"nat-b1m2-1","book":"Ich habe im Moment sehr viel zu tun.","real":"Ich hab' voll den Stress.","meaning":"Estoy hasta arriba de estrés","when":"Con compañeros de confianza y con amigos. Con el jefe, con un cliente o en cualquier cosa escrita, no: «voll den Stress» suena a patio de instituto.","register":"amigos","exam":"Zurzeit stehe ich unter großem Zeitdruck.","note":"«voll den Stress haben» es coloquial hasta en la gramática (den Stress en acusativo tras «voll»). Se oye en cualquier oficina alemana un lunes.","sound":"ij jab fol deen shtres","level":"b1","produce":true,"itemId":"b1m2natvollstress"},"lessonId":"b1m2l1","level":"b1"},{"card":{"id":"nat-b1m2-2","book":"Kannst du mir kurz helfen?","real":"Kannste mir kurz helfen?","meaning":"¿Me echas una mano un momento?","when":"Entre compañeros de confianza y solo hablando: no se escribe, ni siquiera en un chat de trabajo. Con el jefe, con un cliente o en la Aufgabe 3 del Schreiben, Sie y Konjunktiv II.","register":"amigos","exam":"Könnten Sie mir bitte kurz helfen?","note":"«kannst du» se funde en «kannste»; igual pasa con «haste» (hast du) y «willste» (willst du). Se oye constantemente y no se escribe nunca.","sound":"KANS-te mia kurts JEL-fen","level":"b1","produce":true,"itemId":"b1m2natkannste"},"lessonId":"b1m2l4","level":"b1"},{"card":{"id":"nat-b1m2-3","book":"Das kann ich noch nicht genau sagen.","real":"Kommt drauf an.","meaning":"Depende","when":"En conversación informal, todo el rato. En una entrevista o por escrito no vale así: además de comerse el «Es» y de recortar «darauf», dejar la respuesta ahí suena a que esquivas la pregunta — en el examen se completa con la subordinada.","register":"amigos","exam":"Das kommt ganz darauf an, wie viel Zeit ich habe.","note":"«Es kommt darauf an» pierde el «Es» y el «darauf» se come a «drauf». Es la respuesta más útil del alemán cuando necesitas un segundo para pensar.","sound":"komt drauf an","level":"b1","produce":true,"itemId":"b1m2natkommtdraufan"},"lessonId":"b1m2l7","level":"b1"},{"card":{"id":"nat-b1m2-4","book":"Ich mache das sofort.","real":"Mach ich gleich.","meaning":"Ahora mismo lo hago","when":"Respondiendo de viva voz a un compañero o a un amigo. En un correo de trabajo no: ni la frase recortada ni el «gleich» — allí se escribe entera y con un verbo que comprometa.","register":"amigos","exam":"Ich kümmere mich sofort darum.","note":"Lo que se cae no es el sujeto: es el «Das» de delante. «Das mache ich gleich» → «Mach ich gleich», con el verbo abriendo la frase y la -e de «mache» comida. Es el alemán hablado en su forma más económica: dos palabras y un compromiso.","sound":"maj ij glaij","level":"b1","produce":true,"itemId":"b1m2natmachichgleich"},"lessonId":"b1m2l8","level":"b1"},{"card":{"id":"nat-b1m3-1","book":"Ich habe keine Lust, Sport zu machen.","real":"Ich hab keinen Bock auf Sport.","meaning":"No me apetece nada hacer deporte","when":"Entre amigos y en familia, constantemente. Con el médico, con el jefe o en cualquier texto de examen, jamás: «Bock» es de la calle y en el Schreiben cuenta como registro roto.","register":"amigos","exam":"Ich habe im Moment wenig Motivation, Sport zu treiben.","note":"«Bock haben auf + Akkusativ» es el «apetecer» de la calle. Con keinen suena a queja simpática, no a grosería.","sound":"ij jap KAI-nen bok auf shport","level":"b1","produce":true,"itemId":"b1m3natkeinenbock"},"lessonId":"b1m3l1","level":"b1"},{"card":{"id":"nat-b1m3-2","book":"Ich bin sehr müde und erschöpft.","real":"Ich bin fix und fertig.","meaning":"Estoy hecho polvo / reventado","when":"Con amigos y compañeros, tras un día largo o después del deporte. Con el médico no: es una frase hecha coloquial y él espera que describas el síntoma. En un texto de examen, tampoco.","register":"amigos","exam":"Ich fühle mich völlig erschöpft.","note":"«fix und fertig» es un par fijo: fix ya no significa aquí «rápido». Suena cansado, no dramático.","sound":"ij bin fiks unt FEA-tij","level":"b1","produce":true,"itemId":"b1m3natfixundfertig"},"lessonId":"b1m3l4","level":"b1"},{"card":{"id":"nat-b1m3-3","book":"Ich muss ins Krankenhaus.","real":"Ich muss ins Spital.","meaning":"Tengo que ir al hospital","when":"En Austria y en Suiza, siempre: allí «Krankenhaus» se entiende pero suena a alemán de Alemania. En Alemania, al revés: Spital suena antiguo o regional. En tu examen, siempre Krankenhaus — Spital hay que entenderlo, no producirlo.","register":"regional","exam":"Leider muss ich ins Krankenhaus und kann deshalb nicht kommen.","note":"El examen es plurizéntrico: te pueden poner un texto austriaco con Spital, Stiege o Jänner (=Januar), y siempre con nota al pie.","sound":"ij mus ins shpi-TAAL","level":"b1","itemId":"b1m3natspital"},"lessonId":"b1m3l7","level":"b1"},{"card":{"id":"nat-b1m3-4","book":"Ich finde diesen Vorschlag nicht gut.","real":"Das find ich echt Quatsch.","meaning":"Eso me parece una tontería","when":"En un foro entre iguales o hablando con amigos. En el comentario del examen, no: «Quatsch» y la -e comida de «find» te bajan el registro justo en la frase que abre tu postura, que es la que más se lee.","register":"amigos","exam":"Ich halte diesen Vorschlag für keine gute Idee.","note":"«Quatsch» es «tontería, chorrada» y se oye a todas horas; «ich find» es «ich finde» con la -e comida al hablar. Para el Schreiben, «Ich halte … für …» suena a opinión argumentada y no a rechazo seco.","sound":"das fint ij ejt kvach","level":"b1"},"lessonId":"b1m3l8","level":"b1"},{"card":{"id":"nat-b1m4-1","book":"Ich beschäftige mich kurz mit dem Handy.","real":"Ich daddel nur kurz.","meaning":"Solo juego / trasteo un ratito con el móvil","when":"Entre amigos y en familia. En un texto de examen o con el jefe, jamás: «daddeln» solo vive en la calle y además suena a que estás matando el rato.","register":"amigos","exam":"Ich schaue nur kurz auf mein Handy.","note":"«daddeln» es trastear sin objetivo, casi siempre con el móvil en la mano. Suena a autoironía, no a orgullo.","sound":"ij DA-del nua kurts","level":"b1","produce":true,"itemId":"b1m4natdaddeln"},"lessonId":"b1m4l1","level":"b1"},{"card":{"id":"nat-b1m4-2","book":"Ich spiele gerade ein Videospiel.","real":"Ich zocke gerade.","meaning":"Estoy jugando (a videojuegos) ahora mismo","when":"Entre gente joven y en chats, todo el rato. En un texto de examen, jamás: «zocken» es jerga pura y no sirve para contarle a un examinador qué haces en tu tiempo libre.","register":"jerga","exam":"In meiner Freizeit spiele ich gern Computerspiele.","note":"«zocken» era jugar con dinero (apostar); hoy es el verbo normal del videojuego entre amigos. También existe «der Zocker».","sound":"ij TSO-ke GUE-raa-de","level":"b1","produce":true,"itemId":"b1m4natzocken"},"lessonId":"b1m4l6","level":"b1"},{"card":{"id":"nat-b1m4-3","book":"Hast du dein Handy dabei?","real":"Hast du dein Natel dabei?","meaning":"¿Llevas el móvil encima?","when":"Solo en Suiza. Ojo al matiz: fue LA palabra durante décadas y sigue viva sobre todo entre gente mayor y en el suizo alemán hablado, pero los jóvenes usan Handy con toda normalidad. En Austria y Alemania, siempre Handy — y en el examen también, con Sie si no es un amigo.","register":"regional","exam":"Haben Sie Ihr Handy dabei?","note":"«Natel» viene de Nationales Autotelefon y era la marca de la red suiza. Es el ejemplo perfecto de que el examen es plurizéntrico: puede caerte en un texto suizo, con nota al pie. Entenderla es obligatorio; usarla, opcional.","sound":"jast du dain NA-tel da-BAI","level":"b1","itemId":"b1m4natnatel"},"lessonId":"b1m4l7","level":"b1"},{"card":{"id":"nat-b1m4-4","book":"Ich habe deine Nachricht erst jetzt gesehen.","real":"Sorry, hab's grad erst gesehen.","meaning":"Perdona, lo acabo de ver","when":"En un chat o en un mensaje a un amigo. En un correo formal —o en la Aufgabe 3 del Schreiben— no: ni «sorry», ni el apóstrofo, ni «grad»; allí se pide disculpas con Sie y con las palabras enteras.","register":"amigos","exam":"Entschuldigen Sie bitte die späte Antwort.","note":"«hab's» es «habe es» y «grad» es «gerade»: en cuanto la frase corre, el alemán hablado se come sílabas. En el examen escrito no se apostrofa nada.","sound":"SO-ri, japs graat east gue-ZEE-en","level":"b1"},"lessonId":"b1m4l8","level":"b1"},{"card":{"id":"nat-b1m5-1","book":"Das ist Unsinn.","real":"So ein Quatsch!","meaning":"¡Qué tontería! / ¡Menuda tontería!","when":"Entre amigos y en un chat de grupo, para tumbar un argumento — no a la persona. Con el jefe, con el casero o por escrito, jamás; y dicho seco a alguien que acaba de hablar, suena a corte.","register":"amigos","exam":"Das sehe ich anders: Dieses Argument überzeugt mich nicht.","note":"Quatsch desmonta el argumento sin insultar a nadie. La fila de examen hace lo mismo, pero además obliga a decir POR QUÉ — que es lo que puntúa en el Sprechen Teil 3.","sound":"zo ain kvatsh","level":"b1","produce":true,"itemId":"b1m5natsoeinquatsch"},"lessonId":"b1m5l2","level":"b1"},{"card":{"id":"nat-b1m5-2","book":"Es gibt viele Argumente dafür.","real":"Da spricht viel dafür.","meaning":"Hay mucho a favor de eso / Eso tiene mucho sentido","when":"Hablando: en un debate, en el Sprechen, con compañeros. Escribiéndolo NO: en el Schreiben el da-Wort abre la frase y el «Da…» de relleno desaparece. Su gemelo en contra: «Dagegen spricht vieles».","register":"neutral","exam":"Dafür spricht vieles.","note":"dafür/dagegen son los da-Komposita que el español resuelve con «a favor de ello». El «Da…» inicial del habla no significa nada: es la muleta que da medio segundo para pensar.","sound":"da shprijt fiil da-FÜA","level":"b1","produce":true,"itemId":"b1m5natdafuersprichtviel"},"lessonId":"b1m5l4","level":"b1"},{"card":{"id":"nat-b1m5-3","book":"Das funktioniert nicht.","real":"Das kannst du knicken.","meaning":"Eso no va a funcionar / eso lo puedes ir olvidando","when":"Entre amigos y en casa, para tumbar un plan que no ves viable. En una reunión, con un profesor o en el examen, jamás: suena a portazo y encima no argumenta nada.","register":"amigos","exam":"Ich halte diesen Vorschlag nicht für sinnvoll.","note":"Literalmente «eso lo puedes doblar», como quien dobla un papel para tirarlo. Fíjate en que la fila de examen no cambia solo de palabras: cambia de estrategia — halten für + adjetivo, y detrás el motivo.","sound":"das kanst du KNI-ken","level":"b1","produce":true},"lessonId":"b1m5l7","level":"b1"},{"card":{"id":"nat-b1m5-4","book":"Das ist mir egal.","real":"Ist mir wurscht.","meaning":"Me da igual","when":"Entre amigos, perfecto. Es la pronunciación del sur (Baviera, Austria, Suabia); en el norte se dice «Das ist mir Wurst», sin la -sch. Con el casero, en un mail o en el examen, nunca: ahí suena a que pasas de quien te habla.","register":"regional","exam":"Das spielt für mich keine große Rolle.","note":"Wurscht es Wurst (salchicha) con la vocal del sur. La lógica alemana: si todo da igual, es todo salchicha. Ojo, «egal» tampoco es tan inocente: dicho a alguien que te está pidiendo algo, también suena a desprecio.","sound":"ist mia vursht","level":"b1"},"lessonId":"b1m5l9","level":"b1"},{"card":{"id":"nat-b1m6-1","book":"Du schaffst das!","real":"Das packst du!","meaning":"¡Tú puedes con eso!","when":"Antes de un examen, una entrevista o el primer día de curso, con amigos y compañeros de curso. Con el profesor, con el jefe o en un mail, no: ahí la fila de examen, y con Sie.","register":"amigos","exam":"Ich bin sicher, dass Sie das schaffen.","note":"packen = agarrar. La imagen alemana del ánimo es física: agarrar el problema con la mano.","sound":"das PAKST du","level":"b1","produce":true,"itemId":"b1m6natpackstdu"},"lessonId":"b1m6l2","level":"b1"},{"card":{"id":"nat-b1m6-4","book":"Ich komme nicht, weil ich keine Zeit habe.","real":"Ich komm nicht — weil, ich hab keine Zeit.","meaning":"No voy, es que no tengo tiempo","when":"Se oye a diario en toda Alemania, con esa pausa antes de la explicación. Hablando con amigos pasa desapercibido; por escrito, nunca: un «weil» con el verbo en segunda posición se corrige como error de orden y te baja la banda en el Schreiben. Si lo que quieres es ese orden, el conector es denn: «Ich komme nicht, denn ich habe keine Zeit».","register":"amigos","exam":"Ich kann leider nicht kommen, weil ich keine Zeit habe.","note":"Con la pausa el hablante deja de subordinar y arranca una frase nueva: ahí «weil» funciona como el «es que» español. Los mismos alemanes que lo dicen te lo marcan en rojo si lo escribes — por eso esta tarjeta es solo para reconocerla, no para copiarla.","sound":"ij kom nijt — vail, ij hab KAI-ne tsait","level":"b1"},"lessonId":"b1m6l5","level":"b1"},{"card":{"id":"nat-b1m6-2","book":"Viel Glück bei der Prüfung!","real":"Ich drücke dir die Daumen!","meaning":"¡Te deseo suerte! (lit. te aprieto los pulgares)","when":"Antes de un examen, una entrevista o una consulta importante, con gente a la que tuteas. Con usted existe «Ich drücke Ihnen die Daumen» y se oye mucho, pero en un mail formal el examinador espera el deseo neutro de la fila de examen. Es el gesto alemán equivalente a cruzar los dedos.","register":"neutral","exam":"Ich wünsche Ihnen viel Erfolg bei der Prüfung.","note":"El pulgar va DENTRO del puño, no cruzado. Si cruzas los dedos ante un alemán, entenderá que estás mintiendo.","sound":"ij DRÜ-ke dia di DAU-men","level":"b1","produce":true,"itemId":"b1m6natdaumendruecken"},"lessonId":"b1m6l7","level":"b1"},{"card":{"id":"nat-b1m6-3","book":"Ich habe es geschafft.","real":"Ich hab's gepackt!","meaning":"¡Lo he conseguido!","when":"Al salir del examen, con amigos y compañeros de curso. En un mail al trabajo, a la Volkshochschule o al Amt, la fila de examen: «bestehen» es el verbo técnico de aprobar, y es el que entiende un tribunal.","register":"amigos","exam":"Ich habe die Prüfung bestanden.","note":"packen otra vez: agarrar el problema. Y el habe se come su -e en el habla: hab's.","sound":"ij japs gue-PAKT","level":"b1","produce":true},"lessonId":"b1m6l9","level":"b1"},{"card":{"id":"nat-b1m7-1","book":"Guten Tag!","real":"Griaß di!","meaning":"¡Hola! (saludo del sur de Alemania y de Austria)","when":"En Baviera, Austria y el Tirol, y solo con gente a la que tuteas. En Hamburgo o Berlín sonaría a disfraz: allí es «Moin» o «Hallo». Y en el examen, ningún saludo regional: el Goethe se hace en Standarddeutsch.","register":"regional","exam":"Guten Tag! (im Brief: Sehr geehrte Damen und Herren,)","note":"Viene de «Grüß dich», por eso solo vale con quien tuteas; para el resto, «Grüß Gott!», que de religioso no tiene nada — es el «buenos días» de Baviera y Austria, y también se lo dicen entre amigos.","sound":"GRIAS di","level":"b1","produce":true},"lessonId":"b1m7l2","level":"b1"},{"card":{"id":"nat-b1m7-2","book":"Das ist ein schönes Fest, nicht wahr?","real":"Schönes Fest, gell?","meaning":"Bonita fiesta, ¿verdad?","when":"Baden-Wurtemberg, Baviera, Austria y Suiza (allí más bien «gäll/gäu»), en conversación relajada. En el norte la muletilla es «ne?» o «oder?»; «gell» te sitúa geográficamente en cuanto lo dices. En el examen, ni una ni otra: para pedir confirmación, la fila de examen o «nicht wahr?».","register":"regional","exam":"Ein schönes Fest, finden Sie nicht auch?","note":"«gell/gelt» viene de «es gelte» — «que valga lo dicho». Es la coletilla que pide confirmación, exactamente como el «¿no?» español.","sound":"SHÖÖ-nes fest, guel","level":"b1","produce":true,"itemId":"b1m7fetradition"},"lessonId":"b1m7l4","level":"b1"},{"card":{"id":"nat-b1m7-3","book":"Ich wünsche dir ein gutes neues Jahr!","real":"Guten Rutsch!","meaning":"¡Feliz año nuevo! (dicho ANTES de Nochevieja)","when":"Del 27 de diciembre al 31, al despedirte de alguien a quien no verás hasta enero. El 1 de enero ya NO vale: entonces se dice «Frohes neues Jahr!». Confundirlos es el error clásico. Se lo puedes soltar al vecino y al jefe; en un mail formal, lo que se escribe es la frase entera de la fila de examen, no el «Guten Rutsch!» a secas.","register":"neutral","exam":"Ich wünsche Ihnen einen guten Rutsch ins neue Jahr!","note":"Se suele explicar como «buen resbalón» hacia el año nuevo, aunque hay quien lo hace venir del yidis rosch, «comienzo». Es de las pocas fórmulas que cruzan registros: lo que cambia no es la palabra, es la frase que la envuelve.","sound":"GUU-ten ruch","level":"b1","produce":true,"itemId":"b1m7fesilvester"},"lessonId":"b1m7l7","level":"b1"},{"card":{"id":"nat-b1m7-4","book":"Das Fass ist angezapft, das Fest beginnt!","real":"O'zapft is!","meaning":"«¡Está pinchado!» — el barril está abierto: empieza el Oktoberfest","when":"Lo grita el alcalde de Múnich el primer sábado de la Wiesn, al mediodía, cuando abre el primer barril. Fuera de ese contexto se usa en broma, para decir «ya empezamos». En un examen alemán no se escribe bávaro: ahí va la fila de examen, que es la de la prensa.","register":"regional","exam":"Mit dem Anstich des ersten Fasses ist das Oktoberfest eröffnet.","note":"Bávaro puro: «angezapft ist» comido hasta quedar en tres sílabas. No hace falta producirlo, pero sí reconocerlo: sale en todos los telediarios de septiembre.","sound":"O-tsapft is","level":"b1","itemId":"b1m7feoktoberfest"},"lessonId":"b1m7l9","level":"b1"},{"card":{"id":"nat-b1m8-1","book":"Das war sehr günstig.","real":"Das war ein Schnäppchen!","meaning":"¡Fue un chollo!","when":"Entre amigos y en la publicidad, cuando algo salió mucho más barato de lo esperado. En un mail al vendedor o en una reclamación, no: ahí «günstig» o «preiswert» a secas.","register":"amigos","exam":"Das war ein sehr günstiges Angebot.","note":"«schnappen» es «atrapar de un mordisco»: un Schnäppchen es literalmente una gangolita que pillaste al vuelo.","sound":"das var ain SHNEP-jen","level":"b1","produce":true,"itemId":"b1m8geware"},"lessonId":"b1m8l1","level":"b1"},{"card":{"id":"nat-b1m8-2","book":"Ich habe kein Geld mehr.","real":"Ich bin blank.","meaning":"Estoy sin blanca / estoy pelado.","when":"Entre amigos, para decir que no llegas a fin de mes; «Ich bin pleite» es lo mismo. En el banco, con el casero o por escrito, jamás: la fila de examen no confiesa nada, solo aplaza.","register":"jerga","exam":"Ich kann den Betrag im Moment leider nicht bezahlen.","note":"«blank» es «liso, vacío»: el bolsillo sin nada. Se oye constantemente al final de mes y no tiene ninguna carga dramática.","sound":"ij bin blank","level":"b1","produce":true,"itemId":"b1m8gebetrag"},"lessonId":"b1m8l4","level":"b1"},{"card":{"id":"nat-b1m8-3","book":"Ich möchte mich beschweren.","real":"Ich hätte da eine Reklamation.","meaning":"Vengo a poner una reclamación.","when":"En el mostrador o al teléfono, cuando quieres reclamar sin sonar agresivo: el Konjunktiv II y ese «da» que no significa nada amortiguan el golpe. Por escrito no vale: en la Beschwerde-Mail el examinador espera «hiermit» y el verbo declarado.","register":"neutral","exam":"Hiermit möchte ich mich über die verspätete Lieferung beschweren.","note":"El alemán comercial esquiva el verbo «beschweren» en la primera frase: suena a conflicto. «Reklamation» es la palabra técnica y neutra que abre la puerta.","sound":"ij HE-te da AI-ne re-kla-ma-TSIÓN","level":"b1","produce":true,"itemId":"b1m8gebeschwerde"},"lessonId":"b1m8l7","level":"b1"},{"card":{"id":"nat-b1m8-4","book":"Ich bezahle für alle.","real":"Das geht auf mich.","meaning":"Invito yo. / Va de mi cuenta.","when":"En el bar o el restaurante, entre amigos o compañeros, cuando pagas tú la ronda. Ojo: en Alemania lo normal es «getrennt» (cada uno lo suyo), así que decirlo es un gesto que se nota. Si a quien invitas lo tratas de usted — un cliente, un profesor —, la fila de examen.","register":"amigos","exam":"Die Rechnung übernehme ich.","note":"Literalmente «eso va sobre mí». La respuesta esperada es «Danke, das nächste Mal ich!» — porque el gesto se devuelve.","sound":"das guet auf mij","level":"b1","produce":true,"itemId":"b1m8gebezahlung"},"lessonId":"b1m8l9","level":"b1"},{"card":{"id":"nat-b1m9-1","book":"Ich muss jetzt gehen.","real":"Ich muss los!","meaning":"Me tengo que ir ya (a coger el tren, al andén…)","when":"Con amigos y compañeros, en cuanto miras el reloj. Con un cliente, con tu jefa o por escrito, nunca: suena a que sales corriendo sin despedirte.","register":"amigos","exam":"Ich muss mich leider schon verabschieden.","note":"«los» convierte cualquier verbo en salida inminente: Ich muss los · Wir müssen los · Los geht's!","sound":"ij mus loos","level":"b1","produce":true,"itemId":"b1m9natvichmusslos"},"lessonId":"b1m9l2","level":"b1"},{"card":{"id":"nat-b1m9-2","book":"Guten Tag!","real":"Grüezi! / Grüezi mitenand!","meaning":"Hola (Suiza; «mitenand» = a todos ustedes)","when":"En toda la Suiza alemana, de usted, al entrar en una tienda, un hotel o un vagón. En Alemania y en Austria suena a imitación, y en el examen no cuenta como saludo: allí se saluda en estándar.","register":"regional","exam":"Guten Tag! Im Brief schreibt man: Sehr geehrte Damen und Herren.","note":"Viene de «Gott grüez i» (que Dios le salude). En Suiza la respuesta también es Grüezi — nunca Hallo con desconocidos.","sound":"GRÜÜ-e-tsi mit-e-NAND","level":"b1","produce":true,"itemId":"b1m9natvgrueezi"},"lessonId":"b1m9l3","level":"b1"},{"card":{"id":"nat-b1m9-3","book":"Guten Tag! / Auf Wiedersehen!","real":"Servus!","meaning":"Hola y también adiós (Austria y Baviera)","when":"Entre conocidos, en Austria y el sur de Alemania, tanto al llegar como al despedirse. Con un desconocido de usted en Viena, mejor «Grüß Gott»; en el norte y en el examen, ninguno de los dos.","register":"regional","exam":"Guten Tag! Und beim Abschied: Auf Wiedersehen!","note":"Del latín «servus» (siervo): «a su servicio». Sirve para saludar Y despedirse, como el «ciao» italiano.","sound":"ZEA-vus","level":"b1","produce":true,"itemId":"b1m9natvservus"},"lessonId":"b1m9l6","level":"b1"},{"card":{"id":"nat-b1m9-4","book":"Weißt du, wann der nächste Zug kommt?","real":"Weißte, wann der nächste kommt?","meaning":"¿Sabes cuándo viene el próximo (tren)?","when":"En el andén, con gente de confianza. A un desconocido, al revisor o en la ventanilla, nunca: «weißte» y comerse el sustantivo suenan a mala educación.","register":"amigos","exam":"Könnten Sie mir bitte sagen, wann der nächste Zug fährt?","note":"«weißt du» se funde en «weißte», y «der nächste» se queda solo porque el tren ya está en el aire. En el examen no se recorta nada: se pregunta con el Konjunktiv II de cortesía de la lección 4.","sound":"VAIS-te, van dea NEEJS-te komt","level":"b1","produce":false},"lessonId":"b1m9l7","level":"b1"},{"card":{"id":"nat-b1m10-1","book":"Das ist nicht so schlimm.","real":"Passt schon.","meaning":"No pasa nada / déjalo, está bien","when":"Entre amigos y compañeros, cuando el otro se disculpa por algo pequeño. A un cliente, a tu casera o por escrito, jamás: suena a que despachas el asunto.","register":"amigos","exam":"Das ist kein Problem, machen Sie sich bitte keine Sorgen.","note":"Con dos palabras cierras el tema y quitas hierro. Si aún estás molesto, no lo digas: «Passt schon» significa que ya está olvidado.","sound":"past shon","level":"b1","produce":true,"itemId":"a2m7natvpasstschon"},"lessonId":"b1m10l2","level":"b1"},{"card":{"id":"nat-b1m10-2","book":"Das ist nicht weiter schlimm.","real":"Halb so wild!","meaning":"No es para tanto","when":"Al quitar importancia a algo que el otro teme haber estropeado. Solo entre amigos y compañeros: dicho de usted suena a palmadita en la espalda.","register":"amigos","exam":"Das kann jedem passieren, machen Sie sich deswegen bitte keine Gedanken.","note":"Literalmente «la mitad de salvaje». Se dice con la mano en alto, y cierra el asunto sin humillar a nadie.","sound":"jalp zoo vilt","level":"b1","produce":true,"itemId":"b1m10natvhalbsowild"},"lessonId":"b1m10l4","level":"b1"},{"card":{"id":"nat-b1m10-3","book":"Es tut mir leid, das war mein Fehler.","real":"Sorry, mein Fehler.","meaning":"Perdona, culpa mía","when":"Entre compañeros de piso, de trabajo o amigos, para cosas pequeñas y del día. Para algo que ha dolido de verdad, no basta: ahí hace falta la frase completa con «dass».","register":"amigos","exam":"Entschuldigen Sie bitte, das war mein Fehler.","note":"«Sorry» está totalmente integrado en el alemán joven y urbano — pero en la Schreiben Aufgabe 3 (correo formal) es justo lo que baja la banda de registro.","sound":"SO-ri, main FEE-la","level":"b1","produce":true,"itemId":"b1m10natvmeinfehler"},"lessonId":"b1m10l7","level":"b1"},{"card":{"id":"nat-b1m10-4","book":"Jetzt ist es genug für mich.","real":"Jetzt reicht's mir!","meaning":"¡Ya está bien! / ¡Hasta aquí hemos llegado!","when":"Cuando de verdad se te ha acabado la paciencia — con un compañero de piso, no con tu jefa. Es el final de una discusión, no su principio: quien lo dice ya no negocia.","register":"amigos","exam":"So kann es aus meiner Sicht nicht weitergehen.","note":"De «reichen» (bastar) + dativo: «mir reicht es». Reconócelo al oírlo: es la señal de que hay que bajar el tono o dejar la conversación.","sound":"yetst raijts mia","level":"b1","produce":false,"itemId":"b1m10natvjetztreichts"},"lessonId":"b1m10l9","level":"b1"},{"card":{"id":"nat-b1m11-1","book":"Wir werden sehen, was passiert.","real":"Mal sehen.","meaning":"Ya veremos. / A ver qué pasa.","when":"Con amigos y compañeros, para aplazar una decisión sin cerrarla. En un correo de trabajo o a una institución, no: deja al otro sin fecha y suena a que te da igual.","register":"amigos","exam":"Ich melde mich, sobald ich mehr weiß.","note":"«Mal» es la partícula que quita hierro: convierte una frase en un gesto de hombros.","sound":"mal ZEE-en","level":"b1","produce":true,"itemId":"b1m11zkmalsehen"},"lessonId":"b1m11l3","level":"b1"},{"card":{"id":"nat-b1m11-2","book":"Ich bin sicher, dass alles gut wird.","real":"Das wird schon!","meaning":"¡Ya verás como sale bien!","when":"Para animar a alguien que duda, entre amigos o compañeros. De usted no se dice: dar ánimos a un superior con esta fórmula suena a paternalismo.","register":"amigos","exam":"Ich bin zuversichtlich, dass es klappt.","note":"Ese «schon» no significa «ya»: es la partícula de la confianza tranquila.","sound":"das virt shoon","level":"b1","produce":true,"itemId":"b1m11zkdaswirdschon"},"lessonId":"b1m11l5","level":"b1"},{"card":{"id":"nat-b1m11-3","book":"Ich habe mir das fest vorgenommen.","real":"Diesmal zieh ich das durch.","meaning":"Esta vez lo llevo hasta el final.","when":"Entre amigos, hablando de propósitos. En el Schreiben y en el Sprechen no: «durchziehen» es de vestuario, no de examen.","register":"amigos","exam":"Diesmal werde ich wirklich durchhalten.","note":"durchziehen es más callejero y más decidido que durchhalten: no es aguantar, es rematar.","sound":"DIIS-mal tsii ij das durj","level":"b1","produce":false},"lessonId":"b1m11l7","level":"b1"},{"card":{"id":"nat-b1m11-4","book":"Ich habe mich entschieden zu gehen.","real":"Ich bin raus.","meaning":"Yo me bajo / lo dejo, y ya está decidido.","when":"Entre amigos, cuando te sales de algo —un plan, un piso, un trabajo— y no piensas discutirlo más. Con un superior, en una negociación o por escrito, nunca: cierra la puerta de golpe.","register":"jerga","exam":"Ich möchte da nicht mehr mitmachen.","note":"Literalmente «estoy fuera», como el «yo me bajo» español. Es una salida, no una explicación: quien lo dice ya no negocia.","sound":"ij bin raus","level":"b1","produce":false},"lessonId":"b1m11l9","level":"b1"},{"card":{"id":"nat-b1m12-1","book":"Da bin ich anderer Meinung.","real":"Seh ich anders.","meaning":"Yo lo veo de otra forma.","when":"Entre compañeros y en debates informales. Delante de los examinadores no: sin «das» y sin la -e, la frase suena a corte seco y pierde el «yo lo veo» que el criterio de Interaktion quiere oír.","register":"amigos","exam":"Das sehe ich anders.","note":"El alemán hablado se come el sujeto («das») cuando el contexto ya lo da, y de paso la -e de «sehe». En el examen se recupera todo: dos palabras más y cambia la banda de registro.","sound":"zee ij AN-das","level":"b1","produce":false},"lessonId":"b1m12l6","level":"b1"},{"card":{"id":"nat-b1m12-4","book":"Ich kann leider nicht kommen.","real":"Ich schaff's leider nicht.","meaning":"No voy a poder / no llego.","when":"En un mensaje o un audio a un compañero de clase. En la Aufgabe 3 —el correo formal a Frau Schuster— jamás: el apóstrofo y el «schaffen» hunden el registro justo en la tarea más corta, donde cada línea pesa el doble.","register":"amigos","exam":"Leider kann ich am Freitag nicht am Test teilnehmen.","note":"«Ich schaff's» = ich schaffe es: en el habla caen la -e y el pronombre entero. Reconocerlo te sirve en el Hören; escribirlo, para nada bueno.","sound":"ij shafs LAI-da nijt","level":"b1","produce":false},"lessonId":"b1m12l7","level":"b1"},{"card":{"id":"nat-b1m12-2","book":"Wir sind uns einig. Wir machen es so.","real":"Abgemacht!","meaning":"¡Trato hecho!","when":"Para cerrar un acuerdo entre iguales: amigos, compañeros y —sí— tu pareja del Sprechen Teil 1, que se trata de tú. Con un superior o en la Schreiben Aufgabe 3 no vale: por escrito y de usted suena a apretón de manos en un bar.","register":"amigos","exam":"Einverstanden, dann machen wir das so.","note":"Una palabra sola que cierra la negociación y ahorra tiempo en el oral. Su gemelo escrito es «verbleiben», el verbo con el que se cierran los correos formales.","sound":"AP-gue-majt","level":"b1","produce":true,"itemId":"b1m12gzabgemacht"},"lessonId":"b1m12l8","level":"b1"},{"card":{"id":"nat-b1m12-3","book":"Ich bin sehr nervös vor der Prüfung.","real":"Ich bin voll aufgeregt.","meaning":"Estoy de los nervios.","when":"Con compañeros de clase, en el pasillo, antes de entrar. Lo que no cabe en el examen es el «voll»: en el Sprechen y en un correo a Frau Schuster, el intensificador es «ziemlich», «sehr» o «etwas».","register":"jerga","exam":"Ehrlich gesagt bin ich ziemlich aufgeregt.","note":"«voll» delante de un adjetivo es el intensificador de la lengua juvenil: voll gut, voll müde, voll aufgeregt. El adjetivo «aufgeregt» sí es neutro y vale para nervios buenos y malos — el que delata el registro es el «voll».","sound":"ij bin fol AUF-gue-reekt","level":"b1","produce":false},"lessonId":"b1m12l9","level":"b1"},{"card":{"id":"nat-b2m1-1","book":"Er hat gesagt, dass er krank ist.","real":"Er meinte, er ist krank.","meaning":"Dijo que está enfermo","when":"Con amigos, al contar lo que te han dicho. El indicativo y «meinen» son la calle. En el Schreiben y en un resumen de prensa, el examinador espera Konjunktiv I: «Er sagte, er sei krank». Mezclar los dos registros baja la banda de Strukturen.","register":"amigos","exam":"Er sagte, er sei krank.","note":"«meinen» aquí no es «opinar»: es «decir» recortado. Y el indicativo no es un error de calle, es la norma hablada.","sound":"ea MAIN-te, ea ist krank","level":"b2","produce":true,"itemId":"b2m1natmeinte"},"lessonId":"b2m1l1","level":"b2"},{"card":{"id":"nat-b2m1-2","book":"Man sagt, dass die Firma pleite ist.","real":"Es heißt, die Firma ist pleite.","meaning":"Se dice que la empresa está en quiebra","when":"Al pasar un rumor, sin fuente. «Es heißt» es la calle y el pasillo. En el examen, o pones la fuente (laut, zufolge) o usas sollen/angeblich: «Die Firma soll pleite sein». Sin fuente y con indicativo, el texto parece tuyo.","register":"neutral","exam":"Die Firma soll pleite sein.","note":"«Es heißt» traga el «man sagt, dass». El verbo de la cita, en la calle, vuelve al indicativo.","sound":"es haist, dii FIR-ma ist PLAI-te","level":"b2","produce":true,"itemId":"b2m1natesheisst"},"lessonId":"b2m1l3","level":"b2"},{"card":{"id":"nat-b2m1-3","book":"Das ist nicht wahr.","real":"Das ist doch Quatsch.","meaning":"Eso no es verdad / eso es una tontería","when":"Con amigos, para tumbar un rumor. «doch» no se traduce: marca que contradices lo que se acaba de oír. En el examen no cabe: allí se desmiente con hechos, no con insultos. La versión que puntúa nombra la prueba.","register":"amigos","exam":"Das lässt sich so nicht belegen.","note":"Quatsch es más seco que «Blödsinn» y menos grosero que «Scheiße». Sigue siendo calle.","sound":"das ist doj kvatsh","level":"b2","produce":true,"itemId":"b2m1natquatsch"},"lessonId":"b2m1l5","level":"b2"},{"card":{"id":"nat-b2m1-4","book":"Ich habe es in der Zeitung gelesen.","real":"Stand in der Zeitung.","meaning":"Lo he leído en el periódico / salió en el periódico","when":"Al pasar una noticia en el pasillo, sin sujeto y sin auxiliar. En el Schreiben no cabe: allí la fuente se nombra entera y, si puedes, con Konjunktiv I. «Stand in der Zeitung» es un encogimiento de hombros, no una cita.","register":"neutral","exam":"Einem Bericht zufolge …","note":"El alemán hablado se come el es y el artículo: «Stand in der Zeitung» = «Es stand in der Zeitung». Reconocerlo evita buscar un sujeto que no está.","sound":"shtant in dea TSAI-tung","level":"b2","produce":true,"itemId":"b2m1natstand"},"lessonId":"b2m1l8","level":"b2"},{"card":{"id":"nat-b2m2-1","book":"Man macht das so.","real":"Das macht man halt so.","meaning":"Así se hace (y no se discute)","when":"En el pasillo, cuando una norma no se explica, se encoge de hombros. «halt» no se traduce: marca que no hay alternativa a la vista. En un correo a un superior o en el Schreiben, eso suena a desgana. Allí se describe el procedimiento.","register":"amigos","exam":"So wird das gehandhabt.","note":"halt es la partícula del «qué le vamos a hacer». Quita presión y quita debate. Por escrito, desaparece.","sound":"das majt man halt zoo","level":"b2","produce":true,"itemId":"b2m2nathaltso"},"lessonId":"b2m2l1","level":"b2"},{"card":{"id":"nat-b2m2-2","book":"Das kann man machen.","real":"Das geht.","meaning":"Eso se puede hacer / vale","when":"En la cocina, en el pasillo, por WhatsApp. Dos sílabas y se acabó la negociación. En un correo a Herr Brandt o en el examen, «Das geht» suena a encogimiento de hombros. Allí: Das lässt sich machen.","register":"amigos","exam":"Das lässt sich machen.","note":"gehen de posibilidad («eso cuela») no tiene nada que ver con ir. Lo oirás cien veces; no lo escribas en Sie.","sound":"das gaat","level":"b2","produce":true,"itemId":"b2m2natdasgeht"},"lessonId":"b2m2l4","level":"b2"},{"card":{"id":"nat-b2m2-3","book":"Ich wurde entlassen.","real":"Ich bin rausgeflogen.","meaning":"Me echaron","when":"Con amigos, después de un despido. rausfliegen no se conjuga en un expediente. En el Schreiben y ante el comité: Mir wurde zum 30. Juni gekündigt — dativo, fecha, sin metáfora.","register":"jerga","exam":"Mir wurde zum 30. Juni gekündigt.","note":"rausgeflogen lleva sein, como todo movimiento. El echar es un vuelo, no una pasiva.","sound":"ij bin RAUS-gue-floo-guen","level":"b2","produce":true,"itemId":"b2m2natrausgeflogen"},"lessonId":"b2m2l5","level":"b2"},{"card":{"id":"nat-b2m2-4","book":"Hier arbeitet man viel.","real":"Hier ist echt viel los.","meaning":"Aquí se trabaja un montón / hay muchísimo jaleo","when":"Al describir un servicio, un turno, una cocina a tope. «los» no es «suelto»: es movimiento, ajetreo. En el informe o en el examen se describe el proceso, no el jaleo.","register":"amigos","exam":"Es wird hier unter hohem Zeitdruck gearbeitet.","note":"echt sube el volumen sin ser grosero. Por escrito, desaparece con el halt.","sound":"hia ist ejt fiil loos","level":"b2","produce":true,"itemId":"b2m2natvielos"},"lessonId":"b2m2l8","level":"b2"},{"card":{"id":"nat-b2m3-1","book":"Weil das Wetter schlecht war, …","real":"Das Wetter war mies, deshalb …","meaning":"Como el tiempo era malo, … / el tiempo era horrible, por eso …","when":"Con amigos. mies y deshalb (inversión) son la calle. En el Schreiben, la misma causa se empaqueta: Aufgrund des schlechten Wetters. Si escribes mies en un Forumsbeitrag de examen, el registro se cae.","register":"amigos","exam":"Aufgrund des schlechten Wetters …","note":"mies es más sucio que schlecht y más joven. deshalb abre y manda el verbo al segundo puesto: por eso la calle no usa weil.","sound":"das VE-ta vaa miis, DES-jalp","level":"b2","produce":true,"itemId":"b2m3natmies"},"lessonId":"b2m3l1","level":"b2"},{"card":{"id":"nat-b2m3-2","book":"Wir haben darüber gesprochen.","real":"Wir haben's angesprochen.","meaning":"Lo hemos hablado / lo sacamos","when":"En el pasillo, cuando un tema se ha tocado sin reunión. El 's se come el es. En el informe: Wir haben das Thema zur Sprache gebracht. Ahí el bloque vale puntos; aquí, sobraría.","register":"amigos","exam":"Wir haben das Thema zur Sprache gebracht.","note":"ansprechen es «sacar». zur Sprache bringen es el mismo gesto con traje.","sound":"via HAA-bens AN-gue-shpro-jen","level":"b2","produce":true,"itemId":"b2m3natangesprochen"},"lessonId":"b2m3l3","level":"b2"},{"card":{"id":"nat-b2m3-3","book":"Das ist wichtig.","real":"Das ist echt wichtig.","meaning":"Eso es importante / de verdad importante","when":"Con amigos, para subir el volumen sin adjetivo culto. En el examen, el mismo gesto se hace con un FVG: Das spielt eine entscheidende Rolle. echt en un Nachricht an den Vorgesetzten es fuga de registro.","register":"amigos","exam":"Das spielt eine entscheidende Rolle.","note":"echt es el voll del B1, un peldaño más adulto. Sigue siendo calle.","sound":"das ist ejt VIJ-tij","level":"b2","produce":true,"itemId":"b2m3natechtwichtig"},"lessonId":"b2m3l5","level":"b2"},{"card":{"id":"nat-b2m3-4","book":"Man hat das untersucht.","real":"Das haben die untersucht.","meaning":"Eso lo han investigado","when":"Al pasar un hallazgo, sin nombrar el laboratorio. die = «esa gente». En el examen, el hallazgo tiene dueño y verbo nominal: Die Untersuchung ergab, dass … Ahí puntúa; aquí, informa.","register":"neutral","exam":"Die Untersuchung ergab, dass …","note":"El sujeto die al final del campo es de habla. Por escrito, el sujeto abre o el sustantivo de proceso (die Untersuchung) hace de autor.","sound":"das HAA-ben dii un-ta-ZUKT","level":"b2","produce":true,"itemId":"b2m3natdieuntersucht"},"lessonId":"b2m3l8","level":"b2"},{"card":{"id":"nat-b2m4-1","book":"Das Problem, das wir lösen müssen.","real":"Das Problem, das noch ansteht.","meaning":"El problema que hay que resolver / que aún está pendiente","when":"En el pasillo del seminario. anstehen es «estar pendiente». En el Schreiben y en una Hausarbeit, el Gerundivum es el traje: das zu lösende Problem. La relativa de obligación también vale; el Gerundivum sube Strukturen.","register":"neutral","exam":"Das zu lösende Problem.","note":"anstehen no es anstehen de cola: es el asunto que aún no se ha ido.","sound":"das pro-BLEEM, das noj AN-shteet","level":"b2","produce":true,"itemId":"b2m4natansteht"},"lessonId":"b2m4l1","level":"b2"},{"card":{"id":"nat-b2m4-2","book":"Die Reform, die das Parlament gestern beschlossen hat.","real":"Die neue Reform von gestern.","meaning":"La reforma que el parlamento aprobó ayer","when":"En el café, nadie despliega el atributo. von gestern basta. En la Hausarbeit y en el examen, el atributo es el criterio Strukturen: die gestern vom Parlament beschlossene Reform.","register":"amigos","exam":"Die gestern vom Parlament beschlossene Reform.","note":"von gestern en la calle es el tiempo. En el atributo, gestern va delante y von marca al agente.","sound":"dii NOI-e re-FORM fon GES-tan","level":"b2","produce":true,"itemId":"b2m4natreformgestern"},"lessonId":"b2m4l3","level":"b2"},{"card":{"id":"nat-b2m4-3","book":"Der Kollege, mit dem ich arbeite.","real":"Mein Kollege halt.","meaning":"El compañero con el que trabajo / mi compañero, ya me entiendes","when":"En el pasillo, halt sustituye a toda la relativa. En la Hausarbeit y en el Sprechen del examen, la relativa con preposición es de banda alta: der Kollege, mit dem ich zusammenarbeite.","register":"amigos","exam":"Der Kollege, mit dem ich zusammenarbeite.","note":"halt otra vez: no se traduce, se encoge de hombros. Junto al nombre, apunta a alguien que el otro ya conoce.","sound":"main ko-LEE-gue halt","level":"b2","produce":true,"itemId":"b2m4natkollegehalt"},"lessonId":"b2m4l5","level":"b2"},{"card":{"id":"nat-b2m4-4","book":"Das, was mich stört, ist …","real":"Was mich stört: …","meaning":"Lo que me molesta es …","when":"Al empezar una queja entre amigos: dos puntos, sin das. En el examen, la frase entera y, si puedes, el foco: Was mich daran stört, ist vor allem … Ahí puntúa Kohärenz.","register":"amigos","exam":"Was mich daran stört, ist vor allem …","note":"El das de «das, was» se come en el habla. Por escrito, o lo dejas o cambias el foco a daran.","sound":"vas mij SHTOAT","level":"b2","produce":true,"itemId":"b2m4natwasmichstort"},"lessonId":"b2m4l8","level":"b2"},{"card":{"id":"nat-b2m5-1","book":"Ich bin dafür.","real":"Bin ich voll dafür.","meaning":"Estoy totalmente a favor / yo encantado.","when":"Entre amigos y en una asamblea de barrio, para marcar postura sin discurso. En el Schreiben y en el Sprechen del examen, jamás: suena a chat y no argumenta.","register":"amigos","exam":"Ich spreche mich dafür aus.","note":"El sujeto se cae y voll intensifica. La fila de examen no es la misma frase con corbata: cambia el verbo (sich aussprechen) y ya no necesita voll.","sound":"bin ij fol da-FÜA","level":"b2","produce":true,"itemId":"b2m5natbinichvolldafuer"},"lessonId":"b2m5l1","level":"b2"},{"card":{"id":"nat-b2m5-2","book":"Er ist Arzt und auch Musiker.","real":"Der ist Arzt, und Musik macht er auch noch.","meaning":"Es médico, y encima hace música.","when":"Para sumar un dato con sorpresa, entre amigos. Por escrito y en el examen, la pareja nicht nur… sondern auch es la que puntúa.","register":"amigos","exam":"Er ist nicht nur Arzt, sondern auch Musiker.","note":"La calle suma con «und … auch noch» y un der que señala. El examen exige la pareja de dos piezas: si suena la primera, tiene que estar la segunda.","sound":"dea ist artst, unt mu-ZIIK majt ea auj noj","level":"b2","produce":true,"itemId":"b2m5natderistarzt"},"lessonId":"b2m5l2","level":"b2"},{"card":{"id":"nat-b2m5-3","book":"Ich sehe das anders.","real":"Seh ich anders.","meaning":"Yo lo veo de otra manera.","when":"Réplica rápida entre conocidos. En asamblea con micrófono y en el Sprechen, la fórmula de examen no suelta el sujeto y cambia el verbo.","register":"amigos","exam":"Dem kann ich mich nicht anschließen.","note":"La calle tira el ich y deja el verbo en posición 1. El examen no es la misma frase más educada: se apunta al contenido (dem) y se niega la adhesión (anschließen).","sound":"zee ij AN-das","level":"b2","produce":true,"itemId":"b2m5natsehichanders"},"lessonId":"b2m5l4","level":"b2"},{"card":{"id":"nat-b2m5-4","book":"Das stimmt, aber …","real":"Ja schon, aber …","meaning":"Ya, vale, pero … (concedes y dejas caer lo que de verdad piensas).","when":"En una discusión hablada, para no empezar con un no. Por escrito y en el examen, la concesión culta no usa schon: usa mag zutreffen y dennoch.","register":"amigos","exam":"Das mag zutreffen; dennoch …","note":"Ja schon no afirma: aparca. Lo que puntúa es lo que viene detrás, igual que tras aber. El examen cambia de estrategia, no de cortesía.","sound":"ya shoon, A-ba","level":"b2","produce":true,"itemId":"b2m5natjaschonaber"},"lessonId":"b2m5l5","level":"b2"},{"card":{"id":"nat-b2m6-1","book":"Ich hätte früher zum Arzt gehen sollen.","real":"Ich hätt eher hingehen sollen.","meaning":"Tendría que haber ido antes al médico.","when":"Entre amigos y en el pasillo de la consulta, para lamentar sin discurso. En el Schreiben, la forma llena y, si puedes, sin eher coloquial: no so lange aufschieben.","register":"amigos","exam":"Ich hätte den Arztbesuch nicht so lange aufschieben sollen.","note":"hätt pierde la e; eher y hingehen son de habla. El examen no es la misma frase más educada: nominaliza (der Arztbesuch) y usa aufschieben.","sound":"ij het EE-a HIN-gee-en ZOL-len","level":"b2","produce":true,"itemId":"b2m6nathaettehingehen"},"lessonId":"b2m6l2","level":"b2"},{"card":{"id":"nat-b2m6-3","book":"Er tut so, als ob er nichts weiß.","real":"Der tut so, als ob nix wär.","meaning":"Hace como si no pasara nada / como si no supiera nada.","when":"Queja entre colegas, nunca delante del paciente. En el examen, K II y la forma con als + V1.","register":"amigos","exam":"Er tut so, als wüsste er von nichts.","note":"nix y wär son de calle; el libro con weiß es el calco que el alumno trae. El examen corrige las dos cosas: el indicativo y el ob.","sound":"dea tut zo, als op niks vea","level":"b2","produce":true,"itemId":"b2m6natalsoobnixwaer"},"lessonId":"b2m6l3","level":"b2"},{"card":{"id":"nat-b2m6-2","book":"Vielleicht ist es anders.","real":"Kann auch sein, dass …","meaning":"También puede que … / no lo descartaría.","when":"Para no cerrar una hipótesis en una conversación. En el Schreiben, Es wäre denkbar, dass… es la que puntúa: K II a la vista.","register":"amigos","exam":"Es wäre denkbar, dass …","note":"Kann auch sein no conjuga K II y por eso suena a habla. El examen enseña el atenuador como forma, no como encogimiento de hombros.","sound":"kan auj zain, das","level":"b2","produce":true,"itemId":"b2m6natkannauchsein"},"lessonId":"b2m6l4","level":"b2"},{"card":{"id":"nat-b2m6-4","book":"Man kann dagegen sagen, dass …","real":"Da könnte man aber sagen …","meaning":"Aunque también se podría decir …","when":"Para meter una objeción en una conversación sin cortar. Por escrito, la forma con ließe sich es la que el examinador subraya.","register":"amigos","exam":"Dagegen ließe sich einwenden, dass …","note":"könnte ya es K II; aber marca el giro. El examen nominaliza la objeción (einwenden) y pone sich lassen en K II (ließe sich).","sound":"da KÖN-te man A-ba ZAA-guen","level":"b2","produce":true,"itemId":"b2m6natdakoennteman"},"lessonId":"b2m6l8","level":"b2"},{"card":{"id":"nat-b2m7-1","book":"Das ist sicher teuer.","real":"Das muss ja teuer gewesen sein.","meaning":"Eso tuvo que salir caro, ¿no?","when":"Entre amigos, al ver una factura. ja marca que lo das por sabido. En el Schreiben, dürfte + kostspielig.","register":"amigos","exam":"Das dürfte recht kostspielig gewesen sein.","note":"La calle junta muss (deducción), ja (sabido) y gewesen sein (pasado). El examen cambia el modal (dürfte) y el adjetivo (kostspielig).","sound":"das mus ya TOI-a gue-VEE-zen zain","level":"b2","produce":true,"itemId":"b2m7natmussjateuer"},"lessonId":"b2m7l2","level":"b2"},{"card":{"id":"nat-b2m7-2","book":"Sag es mir.","real":"Sag mal …","meaning":"Oye… / a ver… (abre una petición, no una orden).","when":"Entre amigos. En el examen y con desconocidos, Könnten Sie mir bitte sagen…","register":"amigos","exam":"Könnten Sie mir bitte sagen, …","note":"mal se pega al imperativo y le quita el filo. El examen no suaviza el imperativo: lo sustituye por K II + Sie.","sound":"zaak mal","level":"b2","produce":true,"itemId":"b2m7sagmal"},"lessonId":"b2m7l3","level":"b2"},{"card":{"id":"nat-b2m7-3","book":"Warum sagst du das?","real":"Warum sagst du das denn?","meaning":"¿Y eso por qué lo dices? (quiero la razón, no te ataco).","when":"Pregunta entre conocidos. En el Sprechen de examen, la pregunta culta no usa denn: pregunta por el fundamento.","register":"amigos","exam":"Worauf stützt sich diese Aussage?","note":"denn en pregunta es interés, no enfado. El examen cambia de estrategia: de por qué lo dices a en qué te apoyas.","sound":"va-RUM zaakst du das den","level":"b2","produce":true,"itemId":"b2m7warumdenn"},"lessonId":"b2m7l4","level":"b2"},{"card":{"id":"nat-b2m7-4","book":"Es ist zu teuer.","real":"Das ist mir zu happig.","meaning":"Me parece una pasta / demasiado (precio).","when":"Queja entre amigos por un cobro. En la reclamación escrita, happig es fuga de registro.","register":"amigos","exam":"Der Preis erscheint mir nicht angemessen.","note":"happig es de habla y de precio. El examen no traduce teuer: cambia de verbo (erscheinen) y de adjetivo (angemessen).","sound":"das ist mia tsu HA-pij","level":"b2","produce":true,"itemId":"b2m7nathappig"},"lessonId":"b2m7l5","level":"b2"},{"card":{"id":"nat-b2m8-1","book":"Wegen des Lärms","real":"Wegen dem Lärm","meaning":"Por el ruido.","when":"El dativo se oye en toda Alemania, también entre hablantes cultos. En el Schreiben de examen, es fuga: quieren genitivo o, mejor, aufgrund.","register":"amigos","exam":"Aufgrund der anhaltenden Lärmbelästigung","note":"El real no es el libro con menos cortesía: es otra norma. El examen no arbitra la calle; cambia de preposición y nominaliza.","sound":"VEE-guen deem leam","level":"b2","produce":true,"itemId":"b2m8natwegendem"},"lessonId":"b2m8l3","level":"b2"},{"card":{"id":"nat-b2m8-2","book":"Ich beschwere mich.","real":"Da mach ich Stress.","meaning":"Por eso armo jaleo / no me quedo quieto.","when":"Entre vecinos, para anunciar que no vas a tragar. En el Widerspruch, jamás: ahí se interpone, no se arma estrés.","register":"amigos","exam":"Hiermit lege ich Widerspruch ein.","note":"Stress machen es de rellano. El examen no suaviza la queja: la convierte en un acto jurídico (Widerspruch einlegen) con hiermit.","sound":"da maj ij shtres","level":"b2","produce":true,"itemId":"b2m8natstress"},"lessonId":"b2m8l7","level":"b2"},{"card":{"id":"nat-b2m8-4","book":"Er hat keine Papiere.","real":"Der hat nix in der Hand.","meaning":"No tiene nada (ningún papel, ninguna prueba).","when":"En el rellano, para decir que el otro va de farol. En el escrito, mangels gültiger Dokumente.","register":"amigos","exam":"Mangels gültiger Dokumente …","note":"nix y in der Hand son de habla. El examen borra la mano y deja el genitivo de la falta.","sound":"dea hat niks in dea hant","level":"b2","produce":true,"itemId":"b2m8natnixinderhand"},"lessonId":"b2m8l9","level":"b2"},{"card":{"id":"nat-b2m9-1","book":"Ich denke, dass…","real":"Ich geh mal davon aus, dass…","meaning":"Parto de que… / Doy por hecho que…","when":"Para marcar una hipótesis de trabajo, no una ocurrencia. Con amigos vale la forma reducida («geh mal davon aus»). En el Schreiben y en el Vortrag, la forma completa. Nunca para una opinión moral: para eso está «meiner Meinung nach».","register":"neutral","exam":"Ich gehe davon aus, dass…","note":"El da-Komposita «davon» anticipa la oración de dass. Sin él (*Ich gehe aus, dass…) la frase se cae: es exactamente el error de la clínica de este módulo.","sound":"ij gee mal da-FON aus, das","level":"b2","produce":true,"itemId":"b2m9natdavonaus"},"lessonId":"b2m9l1","level":"b2"},{"card":{"id":"nat-b2m9-2","book":"Das hängt von vielen Dingen ab.","real":"Kommt drauf an.","meaning":"Depende.","when":"Respuesta corta entre amigos cuando no quieres cerrar. En el examen no: una palabra sola no argumenta. Ahí se espera el complemento o la frase de ob.","register":"amigos","exam":"Das ist von zahlreichen Faktoren abhängig.","note":"drauf = darauf, fundido. El examen no quiere el fundido: quiere el adjetivo abhängig von, que es exactamente la rección de L2 dicha en registro escrito.","sound":"komt DRAUF an","level":"b2","produce":true,"itemId":"b1m2natkommtdraufan"},"lessonId":"b2m9l3","level":"b2"},{"card":{"id":"nat-b2m9-3","book":"Der Grund dafür ist…","real":"Das liegt daran, dass…","meaning":"Eso se debe a que…","when":"Para dar la causa cuando ya está sobre la mesa el «eso». En un gráfico, detrás de un dato. En el Schreiben, la fila de examen nombra el fenómeno: «Der Grund für diese Entwicklung liegt in…».","register":"neutral","exam":"Der Grund für diese Entwicklung liegt in…","note":"daran = da + an, porque liegen rige an. El libro nombra el Grund; la calle señala con da-. El examen recupera el sustantivo y su rección (Grund für).","sound":"das leekt da-RAN, das","level":"b2","produce":true,"itemId":"b2m9natliegtdaran"},"lessonId":"b2m9l4","level":"b2"},{"card":{"id":"nat-b2m9-4","book":"Ich bin stolz darauf.","real":"Da bin ich schon stolz drauf.","meaning":"De eso sí que estoy orgulloso.","when":"Para marcar que el orgullo no es general: es de ESA cosa. El «da» inicial y el «schon» ponen el foco. En el Vortrag se recupera el darauf delante: «Darauf bin ich durchaus stolz».","register":"amigos","exam":"Darauf bin ich durchaus stolz.","note":"drauf = darauf fundido, igual que drauf an. El examen no funde: pone darauf en el Vorfeld y suena a frase hecha de oral culto.","sound":"da bin ij shoon shtolts DRAUF","level":"b2","produce":true,"itemId":"b2m9natstolzdrauf"},"lessonId":"b2m9l5","level":"b2"},{"card":{"id":"nat-b2m10-1","book":"der Januar","real":"der Jänner","meaning":"enero — en Austria (y en el examen: Januar)","when":"Lo lees en un texto austriaco, a menudo con glosa al pie. Lo escribes en el Goethe como Januar. Producir Jänner en un Forumsbeitrag no demuestra que sepas austriaco: demuestra que no has leído la consigna de norma.","register":"regional","exam":"der Januar","note":"No es dialecto: es estándar austriaco. Por eso el libro y el examen coinciden en Januar — la norma que puntúa este curso — y el real enseña lo que vas a reconocer.","sound":"dea YE-na","level":"b2","produce":false,"itemId":"b1m7fejaenner"},"lessonId":"b2m10l1","level":"b2"},{"card":{"id":"nat-b2m10-2","book":"die Treppe","real":"die Stiege","meaning":"la escalera — Austria y el sur de Alemania (en Suiza: Treppe)","when":"La lees en Viena y en Múnich. En Berna no: allí es Treppe. En el Goethe escribes Treppe siempre. Stiege no es «el austriaco de postal»: es estándar austriaco, y aun así no es tu producción.","register":"regional","exam":"die Treppe","note":"CANON lo deja escrito: Stiege no es solo Austria y Suiza. El sur de Alemania la usa. La producción de este curso, aun así, es Treppe.","sound":"di SHTII-gue","level":"b2","produce":false,"itemId":"b1m7festiege"},"lessonId":"b2m10l4","level":"b2"},{"card":{"id":"nat-b2m10-3","book":"die Straße","real":"die Strasse","meaning":"la calle — en Suiza no hay ß","when":"Lo lees en cualquier texto suizo (cartel, prensa, web federal). Lo escribes en el Goethe con ß: Straße. Copiar Strasse en el Forumsbeitrag no te hace «más suizo»: te hace descuidado con la norma que has firmado al matricularte.","register":"regional","exam":"die Straße","note":"CANON: en Suiza no existe la ß (Ermässigung, Strasse, gross). Los jóvenes suizos no son un museo: escriben así en su norma, y Handy les sale tan natural como Natel a su madre.","sound":"di SHTRAA-se","level":"b2","produce":false,"itemId":"b2m10strassech"},"lessonId":"b2m10l6","level":"b2"},{"card":{"id":"nat-b2m10-4","book":"Das ist sehr gut.","real":"Das ist echt stark.","meaning":"Eso está de verdad muy bien.","when":"Elogio entre amigos, en el grupo del curso, después de un Vortrag de alguien que te cae bien. En el examen y en la Nachricht: la fila culta. «Stark» aquí no es «fuerte»: es el intensificador de la calle.","register":"amigos","exam":"Das halte ich für ausgesprochen gelungen.","note":"echt + adjetivo es la marca. El examen no la borra por moralina: la cambia de traje. gelungen es el participio que puntúa.","sound":"das ist ejt shtark","level":"b2","produce":true,"itemId":"b2m10natechtstark"},"lessonId":"b2m10l9","level":"b2"},{"card":{"id":"nat-b2m11-1","book":"Kurz gesagt…","real":"Also im Endeffekt…","meaning":"Así que, al final / en resumidas cuentas…","when":"Para cerrar de palabra, con amigos o en el pasillo después de la reunión. En el protocolo y en el Vortrag, la fila de examen. Endeffekt en un escrito de Sie suena a barra.","register":"amigos","exam":"Zusammenfassend lässt sich sagen, dass…","note":"Endeffekt es el balance de la calle. El examen quiere el se impersonal del resumen: lässt sich sagen. Misma operación, otro traje — el m10 no se ha ido.","sound":"AL-zo im ENT-ef-ekt","level":"b2","produce":true,"itemId":"b2m11natendeffekt"},"lessonId":"b2m11l1","level":"b2"},{"card":{"id":"nat-b2m11-2","book":"In dem Text steht, dass…","real":"Da steht halt, dass…","meaning":"En el texto dice que…","when":"halt es la partícula de «ya se sabe». Con amigos, para señalar el contenido sin citar. En el protocolo y en el Schreiben, zufolge / laut. Da steht halt en un Vortrag suena a que no te has leído el original.","register":"amigos","exam":"Dem Artikel zufolge…","note":"La calle señala con da. El examen nombra la fuente. Resumir es, entre otras cosas, elegir esa fila.","sound":"da shteet halt, das","level":"b2","produce":true,"itemId":"b2m11natzufolge"},"lessonId":"b2m11l2","level":"b2"},{"card":{"id":"nat-b2m11-3","book":"Anders gesagt","real":"Also quasi…","meaning":"O sea / como…","when":"Muleta para reformular de palabra, cuando aún estás buscando la frase. En el escrito y en el Vortrag: mit anderen Worten. Quasi en un protocolo queda de pasillo.","register":"amigos","exam":"Mit anderen Worten","note":"quasi no añade información: gana medio segundo. El examen no paga ese segundo; paga la reformulación limpia.","sound":"AL-zo KVAA-zi","level":"b2","produce":true,"itemId":"b2m11natalsoquasi"},"lessonId":"b2m11l4","level":"b2"},{"card":{"id":"nat-b2m11-4","book":"Ich erkläre es dir.","real":"Ich sag's dir mal ganz einfach.","meaning":"Te lo digo en plata / te lo dejo fácil.","when":"Para bajar el registro con un igual, cuando el original era denso. En el Vortrag y en el protocolo: Ich fasse den wesentlichen Inhalt kurz zusammen. «Ganz einfach» delante de un examinador suena a que le hablas como a un niño.","register":"amigos","exam":"Ich fasse den wesentlichen Inhalt kurz zusammen.","note":"Reformular hacia abajo (calle) y reformular hacia el Lesen o el Schreiben son la misma operación en dos trajes. El Goethe B2 de 2019 no tiene Sprachmittlung; cobra esta operación en esas dos pruebas. El m10 te enseñó a no mezclar los trajes; este módulo te enseña a hacer los dos.","sound":"ij zaks dia mal gants AIN-faj","level":"b2","produce":true,"itemId":"b2m11natfasse"},"lessonId":"b2m11l9","level":"b2"},{"card":{"id":"nat-b2m12-4","book":"Ich möchte etwas sagen.","real":"Darf ich mal?","meaning":"¿Puedo decir algo? / ¿Me dejas?","when":"Para pedir turno entre amigos. En el Sprechen Teil 2, la fórmula de examen: Darf ich dazu das Wort ergreifen? Sin eso, cortar al compañero resta Interaktion.","register":"amigos","exam":"Darf ich dazu das Wort ergreifen?","note":"mal es la partícula de «un momento». El examen nombra das Wort: es el mismo gesto, otro traje. El m11 ya lo tenía como vocabulario de reunión; aquí es la fila que puntúa.","sound":"darf ij da-TSUU das vort er-GRAI-fen","level":"b2","produce":true,"itemId":"b2m12wortergreifenexam"},"lessonId":"b2m12l6","level":"b2"},{"card":{"id":"nat-b2m12-1","book":"Ich möchte über X sprechen.","real":"Also, ich red mal über X.","meaning":"Voy a hablar de X.","when":"La calle abre con also y un verbo recortado. El Vortrag del Goethe abre de usted, con el público nombrado. Si entras con «also ich red mal», la banda de registro se cae antes del primer argumento.","register":"amigos","exam":"Meine Damen und Herren, ich möchte Ihnen heute das Thema X näherbringen.","note":"näherbringen es el verbo de ponencia. sprechen über vale; esta fórmula puntúa más porque suena a seminario, que es el marco del Teil 1.","sound":"MAI-ne DAA-men unt HE-ren, ij MÖJ-te II-nen HOI-te … NÉE-a-brin-guen","level":"b2","produce":true,"itemId":"b2m12meinedamen"},"lessonId":"b2m12l7","level":"b2"},{"card":{"id":"nat-b2m12-2","book":"Das war alles.","real":"Ja, das wär's dann.","meaning":"Eso es todo / ya estaría.","when":"Para bajar el telón entre amigos. En el Vortrag, jamás: el cierre tiene que ofrecer la ronda de preguntas, que vale 12 puntos. Cortar con «das wär's» es dejar 12 puntos en la mesa.","register":"amigos","exam":"Vielen Dank für Ihre Aufmerksamkeit. Ich stehe Ihnen nun für Fragen zur Verfügung.","note":"Dos frases, no una. El agradecimiento solo no abre la ronda. Verfügung es el traje; wär's es la barra.","sound":"FII-len dank füa II-re AUF-merk-zaam-kait. ij SHTEE-e II-nen nun füa FRAA-guen tsur fea-FÜ-gung","level":"b2","produce":true,"itemId":"b2m12stehefragen"},"lessonId":"b2m12l8","level":"b2"},{"card":{"id":"nat-b2m12-3","book":"Ich bin nicht einverstanden.","real":"Nee, seh ich nicht so.","meaning":"No, yo no lo veo así.","when":"Entre iguales, para cortar sin discurso. Delante de los examinadores, anschließen: te despegas de la tesis y dejas al interlocutor en pie. Interaktion se puntúa aparte.","register":"amigos","exam":"Dem kann ich mich nicht anschließen.","note":"El B1 tenía «Das sehe ich anders». El B2 sube un traje: anschließen es el verbo de las actas. Nee seh ich nicht so es el de la cocina de Nico.","sound":"deem kan ij mij nijt AN-shlee-sen","level":"b2","produce":true,"itemId":"b2m5demkannichmichnichtanschliessen"},"lessonId":"b2m12l9","level":"b2"}],
  "en": [{"card":{"id":"nat-ena1m1-1","book":"How are you?","real":"How's it going?","meaning":"¿Qué tal? / ¿Cómo va? — el saludo informal de cada día","when":"Con amigos, compañeros y baristas: Londres entero lo dice. En una entrevista de trabajo o con un desconocido mayor, la del libro. Se responde igual: «Good, thanks!»","register":"neutral","note":"En la calle el going pierde la g final: «how's it goin'»","sound":"jáus̬ it GÓU-ing","level":"a1"},"lessonId":"ena1m1l3","level":"a1"},{"card":{"id":"nat-ena1m1-2","book":"You're welcome.","real":"No worries!","meaning":"«De nada» o «no pasa nada» — responde a un thank you Y a un sorry","when":"Cafés, tiendas, compañeros: el comodín informal-neutro de Londres (y de Australia entera). En un email formal o con un cliente: «You're welcome».","register":"neutral","note":"Dos usos en uno: cierra agradecimientos y disculpas con la misma sonrisa","sound":"nóu UÓ-ris̬","level":"a1"},"lessonId":"ena1m1l5","level":"a1"},{"card":{"id":"nat-ena1m1-3","book":"Sorry? Can you repeat that, please?","real":"You what?","meaning":"¿cómo? / ¿qué has dicho? — pedir repetición a la brava","when":"Lo oirás entre amigos y por toda la calle londinense. No lo uses tú con desconocidos: suena brusco. Tu «Sorry?» o «Can you repeat that?» quedan siempre bien.","register":"regional","note":"habla popular de Londres y del norte — economía pura: dos palabras y una ceja levantada","sound":"yu UÓT","level":"a1"},"lessonId":"ena1m1l7","level":"a1"},{"card":{"id":"nat-ena1m1-4","book":"Have a nice day!","real":"Have a good one!","meaning":"¡que tengas un buen día! — la versión relajada del cartel","when":"Cajeros, baristas y vecinos al despedirse: el comodín informal de cada día. En el examen y por escrito: Have a nice day.","register":"neutral","note":"one sustituye a day: vale para el día, la tarde o lo que venga después","sound":"jav a gud UÁN","level":"a1"},"lessonId":"ena1m1l8","level":"a1"},{"card":{"id":"nat-ena1m1-5","book":"Hello!","real":"Hiya!","meaning":"¡hola! — el saludo exprés de cada día","when":"Tiendas, compañeros, vecinos: el hola relajado que oirás por todo el Reino Unido. En el examen y con desconocidos formales: Hello.","register":"amigos","note":"hi estirado con un -ya de propina — se dice con sonrisa o no cuenta","sound":"JÁI-ya","level":"a1"},"lessonId":"ena1m1l9","level":"a1"},{"card":{"id":"nat-ena1m2-1","book":"I'm going to call my mother.","real":"I'm gonna call my mother.","meaning":"«Voy a llamar a mi madre» — going to (ir a hacer algo) fundido en gonna","when":"Lo oirás en series, canciones y todo Londres informal. En el examen y por escrito: going to. Tú aún no lo necesitas producir — solo reconocerlo cuando vuele.","register":"neutral","note":"going to se funde en el habla rápida: gonna — como wanna (want to)","sound":"áim GO-na kool mái MÁ-da","level":"a1"},"lessonId":"ena1m2l4","level":"a1"},{"card":{"id":"nat-ena1m2-2","book":"She is very nice.","real":"She's, y'know, very nice.","meaning":"«Es, ¿sabes?, muy maja» — y'know es la muletilla para ganar un segundo mientras piensas","when":"Conversación relajada entre amigos y compañeros. No la uses en el examen ni la escribas: reconócela para no buscarle un significado que no tiene.","register":"amigos","note":"you know se funde en y'know — es relleno puro, como el «o sea» español","sound":"shíis̬, ya-NÓU, VE-ri náis","level":"a1"},"lessonId":"ena1m2l5","level":"a1"},{"card":{"id":"nat-ena1m2-3","book":"the children","real":"the kids","meaning":"los niños / los críos — como dicen children todos los padres","when":"Padres, profesores y todo el mundo informal: «the kids are at school». En el examen y por escrito: children.","register":"neutral","note":"kid = crío; el singular también vuela solo: «he's a good kid»","sound":"de KIDs̬","level":"a1"},"lessonId":"ena1m2l7","level":"a1"},{"card":{"id":"nat-ena1m2-4","book":"Very nice!","real":"Lovely!","meaning":"¡precioso! / ¡qué bien! — el comodín británico para todo lo bueno","when":"Fotos, bebés, planes, tés: en el Reino Unido todo lo bueno es lovely. Entiéndelo como un «¡qué maravilla!» multiusos. En el examen te vale nice / very nice.","register":"neutral","note":"también responde a buenas noticias: «I'm fine!» — «Lovely!»","sound":"LAV-li","level":"a1"},"lessonId":"ena1m2l8","level":"a1"},{"card":{"id":"nat-ena1m2-5","book":"grandmother / grandfather","real":"Gran / Grandad","meaning":"abuela / abuelo — como «la yaya» y «el yayo»","when":"Dentro de la familia, siempre: «Gran's house» es casa de la abuela. En el examen y con desconocidos: grandmother / grandfather.","register":"amigos","note":"cada familia elige el suyo: Gran, Granny, Nana… y Grandad o Grandpa","sound":"gran / GRAN-dad","level":"a1"},"lessonId":"ena1m2l9","level":"a1"},{"card":{"id":"nat-ena1m3-1","book":"You're Spanish, aren't you?","real":"You're Spanish, innit?","meaning":"«Eres español, ¿verdad?» — coletilla para pedir confirmación","when":"La oirás por todo Londres, sobre todo entre gente joven, pegada a cualquier frase. No la uses tú: en el examen y con desconocidos suena fuera de lugar; para confirmar en neutro vale «right?».","register":"regional","note":"innit nace de «isn't it» fundido — y el habla joven de Londres lo pega a todo","sound":"Í-nit","level":"a1"},"lessonId":"ena1m3l4","level":"a1"},{"card":{"id":"nat-ena1m3-2","book":"a cup of tea","real":"a cuppa","meaning":"una taza de té — LA bebida nacional británica","when":"En casa, en la oficina y en el café de Sam: «Fancy a cuppa?» = ¿te apetece un té? Por escrito y en el examen, la versión del libro: a cup of tea.","register":"amigos","note":"cup of tea se funde: el of casi desaparece y queda KÁ-pa","sound":"a KÁ-pa","level":"a1"},"lessonId":"ena1m3l6","level":"a1"},{"card":{"id":"nat-ena1m3-3","book":"Thank you very much!","real":"Cheers!","meaning":"¡gracias! — y también ¡adiós! o ¡salud! (al brindar)","when":"En tiendas, pubs y con cualquiera que te haga un favor pequeño: LA palabra multiusos británica. En el examen y en contextos formales: thank you.","register":"neutral","note":"un solo cheers cubre gracias + adiós al colgar o al salir — economía británica pura","sound":"chías̬","level":"a1"},"lessonId":"ena1m3l7","level":"a1"},{"card":{"id":"nat-ena1m3-4","book":"Thank you!","real":"Ta!","meaning":"gracias — la versión de una sílaba","when":"Al recibir el cambio, al pasarte algo, al abrirte la puerta: gracias exprés entre amigos y en tiendas del día a día. En el examen y por escrito: thank you.","register":"regional","note":"thank you reducido a una sola sílaba — muy común en el norte de Inglaterra","sound":"taa","level":"a1"},"lessonId":"ena1m3l8","level":"a1"},{"card":{"id":"nat-ena1m3-5","book":"See you later!","real":"See ya!","meaning":"¡hasta luego! — la despedida exprés","when":"Al colgar el teléfono, al salir del café, entre compañeros: la despedida rápida universal. En el examen y por escrito: See you later / See you soon.","register":"amigos","note":"you átono se funde en ya — la frase entera cabe en media sonrisa","sound":"si-YÁ","level":"a1"},"lessonId":"ena1m3l9","level":"a1"},{"card":{"id":"nat-ena1m4-1","book":"I don't know.","real":"Dunno.","meaning":"«Ni idea» — no lo sé","when":"Con amigos y en respuestas rápidas, muchas veces con encogimiento de hombros. En el examen oral y con desconocidos, la del libro: I don't know.","register":"amigos","note":"I don't know se funde entero: da-NÓU","sound":"da-NÓU","level":"a1"},"lessonId":"ena1m4l3","level":"a1"},{"card":{"id":"nat-ena1m4-3","book":"It's half past seven.","real":"It's half seven.","meaning":"son las siete y media — el half past sin el past","when":"Al quedar con alguien la oirás constantemente: «half seven», «half ten». Es SIEMPRE y media de esa hora: half seven = 7:30 (nunca 6:30). En el examen y por escrito, la del libro: half past seven.","register":"neutral","note":"el past se cae en el habla rápida — solo el contexto británico lo repone","sound":"jaf SÉ-ven","level":"a1"},"lessonId":"ena1m4l4","level":"a1"},{"card":{"id":"nat-ena1m4-4","book":"Good morning!","real":"Morning!","meaning":"¡buenos días! — la versión exprés de cada mañana","when":"Al entrar al trabajo, al café de Sam o al cruzarte con el vecino: el saludo matinal británico casi nunca lleva el good. En el examen y en contextos formales, entero: Good morning.","register":"neutral","note":"el good se cae y el morning se queda — pasa igual con (good) afternoon y (good) evening","sound":"MÓO-ning","level":"a1"},"lessonId":"ena1m4l8","level":"a1"},{"card":{"id":"nat-ena1m4-2","book":"I've got to go.","real":"I gotta go!","meaning":"«¡Me tengo que ir!» — la despedida con prisa","when":"Con amigos, en mensajes y con prisa real. En el examen y en situaciones formales: I have to go.","register":"amigos","note":"got to se funde en gotta, casi siempre pegado a I o a we","sound":"ái GÓ-ta góu","level":"a1"},"lessonId":"ena1m4l7","level":"a1"},{"card":{"id":"nat-ena1m5-1","book":"Here is your coffee.","real":"Here you go!","meaning":"«Aquí tienes» — al entregarte algo.","when":"Lo dice quien te DA algo: el café, el cambio, una bolsa. Lo oirás en todas las cafeterías y tiendas de Londres. Tú no necesitas decirlo: responde con thank you y listo.","register":"neutral","note":"También oirás «There you go» — es exactamente lo mismo.","sound":"JÍA yu góu","level":"a1"},"lessonId":"ena1m5l2","level":"a1"},{"card":{"id":"nat-ena1m5-2","book":"Do you want a coffee?","real":"Fancy a coffee?","meaning":"«¿Te apetece un café?» — la invitación británica de cada día.","when":"Entre amigos, compañeros de curso o de trabajo: Fancy a coffee? Fancy a pizza? En una cafetería el camarero NO te lo dirá — y tú no necesitas decirlo: con Do you want… quedas perfecto.","register":"amigos","note":"fancy = apetecer; la pregunta entera se come el Do you: (Do you) fancy…?","sound":"FAN-si a KO-fi","level":"a1"},"lessonId":"ena1m5l5","level":"a1"},{"card":{"id":"nat-ena1m5-3","book":"Thank you.","real":"Cheers!","meaning":"«¡Gracias!» al RECIBIR algo — el café, el cambio, la bolsa.","when":"Justo cuando te ponen algo en la mano: Sam le pasa el café a Amy y ella responde Cheers! Es el gracias del intercambio rápido en cafés y tiendas. En un email o una situación formal: thank you, siempre.","register":"neutral","note":"Ya lo conoces como gracias multiusos (módulo 3) — aquí lo ves en su momento estrella: el instante en que recibes algo.","sound":"chías̬","level":"a1"},"lessonId":"ena1m5l6","level":"a1"},{"card":{"id":"nat-ena1m5-4","book":"Can I help you?","real":"What can I get you?","meaning":"«¿Qué te pongo?» — la pregunta real del mostrador","when":"Es lo primero que oirás al llegar a la barra de un café o un pub. Tú no la dices: la respondes con tu Can I have…, please. En el examen, la del libro: Can I help you?","register":"neutral","note":"get = «traer/poner» detrás del mostrador: la pregunta viaja de ellos hacia ti","sound":"uót kan ái GUÉT iu","level":"a1"},"lessonId":"ena1m5l7","level":"a1"},{"card":{"id":"nat-ena1m5-5","book":"Tea or coffee?","real":"Tea or coffee, love?","meaning":"«¿Té o café, cariño?» — el love de los mostradores","when":"Camareras y dependientes lo pegan a cualquier frase, sobre todo fuera de Londres: no es coqueteo, es amabilidad de barrio. Tú no lo usas: sonríe y pide lo tuyo con please.","register":"regional","note":"love (y según la zona dear o duck) es el apelativo cariñoso universal del mostrador británico","sound":"tíi óo KO-fi, laf","level":"a1"},"lessonId":"ena1m5l9","level":"a1"},{"card":{"id":"nat-ena1m6-1","book":"It's ten pounds.","real":"It's ten quid.","meaning":"«Son diez libras» — quid es «libra» en jerga.","when":"Lo oirás constantemente en Londres al hablar de dinero entre gente de confianza. Nunca en precios escritos, nunca en el examen, y tú no lo necesitas decir: pounds vale siempre. Ojo: quid no tiene plural — five quid, jamás «quids».","register":"jerga","note":"Como «pavos» para los euros/dólares: ten quid = diez pavos británicos.","sound":"kuíd","level":"a1"},"lessonId":"ena1m6l2","level":"a1"},{"card":{"id":"nat-ena1m6-2","book":"Do you have this in blue?","real":"Have you got this in blue?","meaning":"«¿Tienes esto en azul?» — el británico prefiere have got para tener.","when":"En las tiendas británicas lo oirás todo el tiempo: Have you got…? Tu «Do you have…?» es perfecto, se entiende siempre y es lo que el examen espera de ti — solo entrena el oído para reconocer la versión got.","register":"neutral","note":"have got = have: got no añade significado, solo acento británico.","sound":"jav yu GOT dis in blúu","level":"a1"},"lessonId":"ena1m6l4","level":"a1"},{"card":{"id":"nat-ena1m6-3","book":"That is three pounds fifty.","real":"That'll be three fifty.","meaning":"«Son 3,50» — como lo dice de verdad quien te cobra.","when":"Lo dice el tendero o el camarero al cantarte el total: That'll be… — y muchas veces sin pounds: «three fifty». Tú solo necesitas cazar el número; para responder te basta pagar y decir thank you.","register":"neutral","note":"that will se funde en that'll; los nativos ahorran hasta el pounds.","sound":"DHA-tl bi zríi FIF-ti","level":"a1"},"lessonId":"ena1m6l5","level":"a1"},{"card":{"id":"nat-ena1m6-4","book":"five pounds / ten pounds","real":"a fiver / a tenner","meaning":"Un billete de cinco / de diez libras","when":"Entre amigos y en tiendas pequeñas al hablar de billetes: «it's a fiver». En el examen y en los precios escritos: five pounds, ten pounds.","register":"jerga","note":"Como decir «un cinco»: fiver = el billete de £5, tenner = el de £10 — primos de quid","sound":"FÁI-va / TE-na","level":"a1"},"lessonId":"ena1m6l7","level":"a1"},{"card":{"id":"nat-ena1m6-5","book":"Thank you!","real":"Ta!","meaning":"Gracias — la versión británica ultracorta","when":"Al recibir el cambio, la bolsa o un favor pequeño, entre gente de confianza en Reino Unido. En el examen y con desconocidos: thank you.","register":"regional","note":"Una sílaba de agradecimiento — la oirás en cada caja británica, sobre todo en el norte","sound":"TAA","level":"a1"},"lessonId":"ena1m6l9","level":"a1"},{"card":{"id":"nat-ena1m7-1","book":"Where is the bathroom?","real":"Where's the loo?","meaning":"¿Dónde está el baño? — «loo» es la palabra británica de andar por casa para el váter","when":"En casas, pubs y entre amigos en el Reino Unido — lo oirás a diario. En un hotel, en un restaurante formal o en el examen: la del libro.","register":"regional","note":"Los británicos casi nunca dicen bathroom fuera de casa: dicen loo o toilet","sound":"UÉAs̬ de LUU","level":"a1"},"lessonId":"ena1m7l1","level":"a1"},{"card":{"id":"nat-ena1m7-2","book":"There's a TV in the living room.","real":"There's a telly in the living room.","meaning":"Hay una tele en el salón — «telly» = la tele","when":"En casa, con amigos y familia británicos. En clase, por escrito o en el examen: TV.","register":"regional","note":"TV → telly, igual que en español televisión → tele","sound":"TE-li","level":"a1"},"lessonId":"ena1m7l2","level":"a1"},{"card":{"id":"nat-ena1m7-3","book":"Thank you very much!","real":"Cheers!","meaning":"Gracias — y también «hasta luego»: la palabra multiusos británica","when":"Al recibir una dirección, el cambio o un favor pequeño, y al despedirte. En el examen y por escrito: thank you.","register":"regional","note":"Un londinense te dirá cheers diez veces al día — casi nunca thank you very much","sound":"CHÍAs̬","level":"a1"},"lessonId":"ena1m7l5","level":"a1"},{"card":{"id":"nat-ena1m7-4","book":"Hello! How are you?","real":"You alright?","meaning":"Hola, ¿qué tal? — el saludo británico que descoloca a todo hispanohablante","when":"Entre vecinos, en la tienda, en el pub — no preguntan por tu salud: es un hola. Se contesta con otro «You alright?» o «Yeah, good». En el examen: Hello, how are you?","register":"regional","note":"Suena a pregunta médica pero es puro saludo — nadie espera un parte de salud","sound":"yu ol-RÁIT","level":"a1"},"lessonId":"ena1m7l7","level":"a1"},{"card":{"id":"nat-ena1m7-5","book":"Perfect! No problem.","real":"Sorted!","meaning":"¡Listo! / ¡Solucionado! — cuando algo queda resuelto","when":"La compra hecha, el plan cerrado, la mudanza terminada: sorted. Muy británico e informal — en el examen: perfect / that's fine.","register":"amigos","note":"Viene de to sort out (resolver): lo resuelto queda «sorted»","sound":"SÓO-tid","level":"a1"},"lessonId":"ena1m7l9","level":"a1"},{"card":{"id":"nat-ena1m8-3","book":"Hello! How are you?","real":"Hiya!","meaning":"¡Hola! — el saludo británico rápido y cercano","when":"Entre amigos, compañeros y vecinos, sobre todo en el norte de Inglaterra. Antes de preguntar por hobbies o lo que sea: Hiya! En el examen y con desconocidos: Hello.","register":"amigos","note":"hi + ya: el saludo que abre el 90% de las charlas informales británicas","sound":"JÁI-ya","level":"a1"},"lessonId":"ena1m8l1","level":"a1"},{"card":{"id":"nat-ena1m8-1","book":"Do you want to play football?","real":"Do you fancy playing football?","meaning":"¿Te apetece jugar al fútbol? — «fancy» = apetecer","when":"Invitaciones informales entre amigos británicos: Fancy a coffee? Fancy watching a film? Con desconocidos o en el examen: Do you want…?","register":"amigos","note":"Tras fancy, el verbo va en -ing — el mismo traje que tras like/love/hate","sound":"du yu FÁN-si PLÉI-ing FÚT-bol","level":"a1"},"lessonId":"ena1m8l2","level":"a1"},{"card":{"id":"nat-ena1m8-2","book":"It's a little cold.","real":"It's kinda cold.","meaning":"Hace un poco de frío — «kinda» = kind of: un poco, como que","when":"Habla rápida e informal, sobre todo americana. En mensajes a amigos, vale; en un email, en clase o en el examen: a little / a bit.","register":"amigos","note":"kind of se funde en kinda en el habla real — como what do you → whaddya","sound":"its KÁIN-da KÓULD","level":"a1"},"lessonId":"ena1m8l4","level":"a1"},{"card":{"id":"nat-ena1m8-4","book":"Do you want to play?","real":"D'you wanna play?","meaning":"¿Quieres jugar? — want to se funde en wanna","when":"Habla rápida informal, en invitaciones entre amigos: wanna play?, wanna watch a film? Tú no necesitas decirlo — pero si no lo reconoces, te pierdes la invitación. Por escrito y en el examen: want to.","register":"amigos","note":"La misma fusión que whaddya: los nativos comprimen las palabras de función","sound":"dyu UÓ-na PLÉI","level":"a1"},"lessonId":"ena1m8l7","level":"a1"},{"card":{"id":"nat-ena1m8-5","book":"Let's play football!","real":"Let's play footy!","meaning":"¡Juguemos al fútbol! — footy es el apodo cariñoso del fútbol","when":"En el parque, en el pub y entre amigos británicos (y australianos): footy. En el examen y por escrito: football.","register":"amigos","note":"El inglés informal acorta y añade -y: football → footy, como telly o cuppa","sound":"FÚ-ti","level":"a1"},"lessonId":"ena1m8l9","level":"a1"},{"card":{"id":"nat-ena1m9-1","book":"It's a really good job.","real":"It's, like, a really good job.","meaning":"Es un trabajo muy bueno — con un «like» de relleno que no significa nada.","when":"La oirás sin parar en Londres, sobre todo entre jóvenes: rellena la pausa mientras piensan. Reconócela y sigue escuchando — ese like NO es el verbo gustar. En el examen y al escribir: ni se te ocurra usarla.","register":"amigos","note":"like muletilla ≠ like verbo (gustar): aquí es puro relleno, como el «o sea» español","sound":"its laik a RÍ-li gud yob","level":"a1"},"lessonId":"ena1m9l4","level":"a1"},{"card":{"id":"nat-ena1m9-2","book":"You know, English is easy.","real":"Y'know, English is easy.","meaning":"«Sabes…, el inglés es fácil» — coletilla para buscar complicidad.","when":"Conversación relajada: abre o remata frases, igual que el «¿sabes?» español. No añade información — es ritmo puro. La oirás cada minuto en Londres; en el examen oral, mejor evítala.","register":"amigos","note":"you know se funde en y'know en el habla rápida","sound":"ia-NÓU","level":"a1"},"lessonId":"ena1m9l5","level":"a1"},{"card":{"id":"nat-ena1m9-3","book":"…, isn't it?","real":"…, innit?","meaning":"¿verdad? / ¿a que sí? — la coletilla británica para pedir confirmación","when":"Pegada al final de la frase, entre amigos y en la calle: It's cold, innit? Con desconocidos formales y en el examen: isn't it?","register":"regional","note":"isn't it comprimido en una sílaba y media — en Londres se cuelga de casi cualquier frase","sound":"Í-nit","level":"a1"},"lessonId":"ena1m9l7","level":"a1"},{"card":{"id":"nat-ena1m9-4","book":"Wait a minute, please.","real":"Gimme a sec!","meaning":"¡Dame un segundo! — gimme = give me, sec = second","when":"Mensajes y habla rápida entre amigos o compañeros de trabajo. En tu email del examen: jamás — ahí se escribe todo entero.","register":"amigos","note":"give me se funde en gimme, de la misma familia que gonna y wanna","sound":"GUÍ-mi a SEK","level":"a1"},"lessonId":"ena1m9l8","level":"a1"},{"card":{"id":"nat-ena1m9-5","book":"I'm very busy.","real":"I'm dead busy.","meaning":"Estoy ocupadísimo — dead = «muy», el intensificador británico","when":"Reino Unido, entre amigos y compañeros: dead busy, dead good, dead easy. En el examen y por escrito: very.","register":"amigos","note":"dead no habla de muertos: es un very con acento de barrio","sound":"áim DED BÍ-s̬i","level":"a1"},"lessonId":"ena1m9l9","level":"a1"},{"card":{"id":"nat-ena1m10-1","book":"the Underground","real":"the tube","meaning":"El metro de Londres.","when":"«The Underground» es el nombre oficial: mapas, carteles, megafonía. En boca de un londinense: «the tube», siempre — Ben jamás dice otra cosa. Entiende las dos; di la que quieras: tube te hará sonar local.","register":"regional","note":"por la forma de tubo de sus túneles — literalmente «el tubo»","sound":"de TIÚB","level":"a1"},"lessonId":"ena1m10l1","level":"a1"},{"card":{"id":"nat-ena1m10-2","book":"Thank you very much.","real":"Cheers, mate!","meaning":"¡Gracias, tío! — el gracias rápido e informal británico.","when":"Londres y el Reino Unido: al bajar del bus, cuando te indican el camino, entre desconocidos de trato relajado. NO en el examen, no en un email, no con tu jefa el primer día. Y ojo: en el pub, Cheers! = ¡salud!","register":"regional","note":"mate = colega; los conductores como Ben lo oyen cien veces al día","sound":"CHÍAs̬ méit","level":"a1"},"lessonId":"ena1m10l3","level":"a1"},{"card":{"id":"nat-ena1m10-3","book":"It's very near.","real":"It's just round the corner.","meaning":"Está a la vuelta de la esquina — cerquísima","when":"LA respuesta clásica al preguntar el camino en el Reino Unido. Resérvala para el oído; en el examen di It's near / It's not far.","register":"neutral","note":"round the corner = doblando la esquina: la distancia favorita de los londinenses (aunque luego sean diez minutos)","sound":"its yast ráund de KÓO-na","level":"a1"},"lessonId":"ena1m10l4","level":"a1"},{"card":{"id":"nat-ena1m10-4","book":"Take the bus.","real":"Get the bus.","meaning":"Coge el autobús — los británicos lo «pillan» con get","when":"Reino Unido, a diario: get the bus, get the train, get the tube. Entiende las dos; en el examen y por escrito, take siempre funciona.","register":"neutral","note":"get = el verbo comodín británico: pillar el bus, pillar un café, pillarlo todo","sound":"guet de BAS","level":"a1"},"lessonId":"ena1m10l5","level":"a1"},{"card":{"id":"nat-ena1m10-5","book":"Excuse me, madam…","real":"'Scuse me, love…","meaning":"Disculpe… — con el «love» que los británicos regalan a desconocidos","when":"Tenderos, conductores de bus y señoras de todo el Reino Unido te llamarán love, dear o darling sin conocerte: no es romántico, es cortesía de barrio. Tú responde normal — y en el examen: Excuse me, a secas.","register":"regional","note":"excuse me pierde la e inicial en el habla rápida: 'scuse me","sound":"SKIÚs̬ mi, LOV","level":"a1"},"lessonId":"ena1m10l7","level":"a1"},{"card":{"id":"nat-ena1m11-1","book":"I don't know.","real":"Dunno…","meaning":"No sé… / Ni idea — la respuesta vaga cuando aún no sabes si puedes","when":"Entre amigos, al responder a un plan: «Do you want to come?» — «Dunno… maybe!». En el examen y por escrito, siempre I don't know.","register":"amigos","note":"don't know se funde en dunno («da-NÓU»). Emparienta con el «nsé» español.","sound":"da-NÓU","level":"a1"},"lessonId":"ena1m11l1","level":"a1"},{"card":{"id":"nat-ena1m11-2","book":"That's a good idea.","real":"Sounds good!","meaning":"¡Suena bien! / ¡Me apunto! — el sí rápido a cualquier plan","when":"Respuesta comodín con amigos y compañeros. En un email formal o en el examen escrito, la del libro.","register":"neutral","note":"sounds = suena: el plan «suena» bien. Lo oirás decenas de veces al día.","sound":"sáunds̬ gud","level":"a1"},"lessonId":"ena1m11l2","level":"a1"},{"card":{"id":"nat-ena1m11-3","book":"See you tomorrow!","real":"See ya!","meaning":"¡Nos vemos! — la despedida rápida de cada día","when":"Entre amigos y compañeros, al salir de cualquier sitio. En el examen di la del libro: See you / Goodbye.","register":"amigos","note":"you átono suena «ya». Lo oirás todo el día en Londres — en tiendas, en el bus, en el curro.","sound":"sii ya","level":"a1"},"lessonId":"ena1m11l3","level":"a1"},{"card":{"id":"nat-ena1m11-4","book":"Do you want to go to the cinema?","real":"Fancy the cinema?","meaning":"¿Te apetece cine? — la invitación exprés británica","when":"Entre amigos y compañeros, para cualquier plan pequeño: Fancy a coffee? Fancy a cuppa? En el examen y por escrito: Do you want to…?","register":"amigos","note":"fancy = apetecer: una sola palabra y la invitación está hecha","sound":"FAN-si de SÍ-ne-ma","level":"a1"},"lessonId":"ena1m11l7","level":"a1"},{"card":{"id":"nat-ena1m11-5","book":"Sorry, I can't come.","real":"Sorry, can't make it!","meaning":"No puedo ir — la versión exprés de los mensajes","when":"En mensajes y habla rápida entre amigos: can't make it = no llego / no me viene bien. En el examen y con desconocidos: Sorry, I can't come.","register":"amigos","note":"make it = «conseguir llegar»: si no lo haces (make), no estás","sound":"kaant MÉIK it","level":"a1"},"lessonId":"ena1m11l9","level":"a1"},{"card":{"id":"nat-ena1m12-1","book":"Now, question number one.","real":"Right, so… question one.","meaning":"Vale, pues… — así arranca las frases el examinador (y cualquier nativo)","when":"Lo oirás en el oral y en los audios: Right y so solo ARRANCAN la frase, no cambian la pregunta. Reconócelo y sigue; tú no necesitas decirlo.","register":"neutral","note":"Right, so, OK, well… son muletillas de arranque, como el «vale, pues» español.","sound":"ráit, sóu","level":"a1"},"lessonId":"ena1m12l1","level":"a1"},{"card":{"id":"nat-ena1m12-2","book":"Good luck!","real":"Fingers crossed!","meaning":"¡Suerte! — literalmente «dedos cruzados»","when":"Entre amigos y familia, antes de un examen o una entrevista. El examinador te dirá Good luck tal cual — respóndele Thank you!","register":"amigos","note":"Cruzar los dedos para desear suerte también se DICE en voz alta. Amy te lo dirá antes del examen.","sound":"FÍN-gas̬ krost","level":"a1"},"lessonId":"ena1m12l6","level":"a1"},{"card":{"id":"nat-ena1m12-3","book":"Can you say that again, please?","real":"Sorry?","meaning":"¿Cómo? / ¿Perdona? — pedir repetición en una sola palabra","when":"En la calle y también en el examen: un Sorry? con entonación de pregunta hace que te repitan la frase entera. La versión larga siempre suma: Can you say that again, please?","register":"neutral","note":"la entonación ES la pregunta: sorry sube al final — ¿so-RRI?","sound":"SO-ri? (subiendo)","level":"a1"},"lessonId":"ena1m12l7","level":"a1"},{"card":{"id":"nat-ena1m12-4","book":"Best wishes,","real":"See you soon! xx","meaning":"las equis son besos — la firma informal de los mensajes británicos","when":"En mensajes y postales entre amigos: x = un beso, xx = dos. En el EXAMEN, jamás: Best wishes y tu nombre.","register":"amigos","note":"una x por beso: x, xx, xxx — cuantas más equis, más cariño","sound":"kis, kis (no se leen: se ven)","level":"a1"},"lessonId":"ena1m12l8","level":"a1"},{"card":{"id":"nat-ena1m12-5","book":"Goodbye! Good luck!","real":"Take care!","meaning":"¡Cuídate! — la despedida con cariño","when":"Al despedirte de amigos, compañeros o del barista de siempre; también cierra emails informales. En el examen: Goodbye / Thank you.","register":"neutral","note":"literalmente «ten cuidado», pero suena a abrazo, no a aviso","sound":"téik KÉA","level":"a1"},"lessonId":"ena1m12l9","level":"a1"},{"card":{"id":"nat-ena2m1-1","book":"It was very good.","real":"It was brilliant.","meaning":"Estuvo genial / de lujo","when":"Con amigos y compañeros, en cuanto valoras algo: una fiesta, una peli, un finde. En Reino Unido se oye a todas horas. En el examen escrito, la versión del libro (very good, really nice) también puntúa: brilliant no te resta, pero no lo estires a un email formal.","register":"amigos","note":"brilliant en inglés británico casi nunca es «brillante»: es «genial». Y su hermana pequeña, lovely, ya la traes del A1.","sound":"it uos̬ BRÍ-liant","level":"a2"},"lessonId":"ena2m1l1","level":"a2"},{"card":{"id":"nat-ena2m1-2","book":"There were a lot of people.","real":"It was packed.","meaning":"Estaba a tope / hasta arriba","when":"Hablando de un bar, un concierto, el metro o una tienda en rebajas. Es informal pero no vulgar: lo dice todo el mundo. En el Writing del examen escribe la del libro (There were a lot of people), que es la que enseña la gramática que te puntúan.","register":"amigos","note":"packed es «empaquetado»: tan lleno que no cabe nadie más. Su gemelo es «It was dead» — vacío, sin ambiente.","sound":"it uos̬ PAKT","level":"a2"},"lessonId":"ena2m1l3","level":"a2"},{"card":{"id":"nat-ena2m1-3","book":"It rained a lot.","real":"It chucked it down.","meaning":"Cayó una buena / diluvió","when":"Entre amigos, quejándose del tiempo británico, que es deporte nacional. En el examen, escribe It rained a lot o It rained heavily: chucked it down es de bar, no de Writing.","register":"amigos","note":"Otra ración de /t/ final: chucked = CHAKT. Y fíjate en el it repetido — el inglés no deja huecos donde va un sujeto o un objeto.","sound":"it CHAKT it dáun","level":"a2"},"lessonId":"ena2m1l5","level":"a2"},{"card":{"id":"nat-ena2m1-4","book":"We were very tired.","real":"We were knackered.","meaning":"Estábamos reventadas","when":"Con amigos y compañeros de trabajo, a todas horas. Es informal pero no es palabrota. En el examen: very tired o exhausted.","register":"amigos","note":"knackered es britanismo puro: en Estados Unidos no lo dicen. Y ojo al were átono de delante: «ui ua NÁ-kad».","sound":"ui ua NÁ-kad","level":"a2","itemId":"ena2m1weweretired"},"lessonId":"ena2m1l7","level":"a2"},{"card":{"id":"nat-ena2m1-5","book":"What did you do at the weekend?","real":"What did you get up to at the weekend?","meaning":"¿Qué hiciste el finde? / ¿En qué has andado metido?","when":"Entre amigos y compañeros, el lunes por la mañana. Tiene un puntito travieso, como el «¿qué has estado tramando?» español, pero se usa con total normalidad. En el examen, la versión del libro.","register":"amigos","note":"get up to = «hacer», con guasa. Y al hablar rápido, did you se funde en «did-ya»: uót DÍD-ya guet AP tu…","sound":"uót did yu guet AP tu at de UÍI-kend","level":"a2","itemId":"ena2m1whatdidyoudo"},"lessonId":"ena2m1l8","level":"a2"},{"card":{"id":"nat-ena2m2-1","book":"We had a good time.","real":"We had a laugh.","meaning":"Nos lo pasamos genial / nos reímos mucho","when":"Con amigos y compañeros, contando una noche o un finde. Es de las expresiones más británicas que hay y no lleva ninguna carga: se dice de una cena, de un concierto o de un turno de trabajo llevadero. En el Writing del examen, la versión del libro (a good time, a great time).","register":"amigos","note":"a laugh aquí no es «una risa»: es «un buen rato». Y se dice también de una persona — «Sam's a laugh» = «Sam es divertidísimo».","sound":"ui jad a LAAF","level":"a2","itemId":"ena2m2wehadagoodtime"},"lessonId":"ena2m2l1","level":"a2"},{"card":{"id":"nat-ena2m2-2","book":"I didn't sleep very well.","real":"I didn't sleep a wink.","meaning":"No pegué ojo","when":"Con amigos y en el trabajo, quejándote de la noche. Es una exageración amable, igual que «no pegué ojo» en español: nadie se la toma al pie de la letra. En el Writing del examen, la del libro.","register":"amigos","note":"a wink es «un parpadeo». La expresión solo existe en negativo: nadie dice «I slept a wink».","sound":"ái DÍ-dent sliip a UÍNK","level":"a2","itemId":"ena2m2ididntsleep"},"lessonId":"ena2m2l3","level":"a2"},{"card":{"id":"nat-ena2m2-3","book":"It cost a lot of money.","real":"It cost a fortune.","meaning":"Me costó un dineral / un riñón","when":"Con amigos, contando una compra o un viaje. Es exageración amable y se usa muchísimo. En el Writing del examen vale también, pero para un texto neutro la versión del libro (it was very expensive) va más segura.","register":"amigos","note":"Ojo al verbo: cost no cambia en pasado. «It cost a fortune» ya es pasado — lo dice el contexto, no el verbo.","sound":"it kost a FÓO-chun","level":"a2","itemId":"ena2m2putgroup"},"lessonId":"ena2m2l5","level":"a2"},{"card":{"id":"nat-ena2m2-4","book":"It was very bad luck.","real":"Just my luck!","meaning":"¡Lo que me faltaba! / ¡Qué mala suerte la mía!","when":"Con amigos y compañeros, justo después de contar el contratiempo. Se dice con resignación y media sonrisa, nunca en serio. En un email de examen, mejor «Unfortunately…» o «It was very bad luck».","register":"amigos","note":"Es irónica: dice «mi suerte de siempre» y significa lo contrario. Nadie la usa cuando algo sale bien.","sound":"chast mái LAK","level":"a2","itemId":"ena2m2unfortunately"},"lessonId":"ena2m2l7","level":"a2"},{"card":{"id":"nat-ena2m2-5","book":"It was a very bad day.","real":"It was a nightmare.","meaning":"Fue una pesadilla","when":"Con amigos y compañeros, resumiendo un día horrible: un viaje, una mudanza, una jornada de trabajo. Es exageración normal y nadie la toma en serio. En el Writing del examen, la del libro (it was terrible, it was a disaster).","register":"amigos","note":"Se dice de situaciones, no de personas. Y su hermana pequeña, «It was a disaster», ya la tienes en esta lección.","sound":"it uos̬ a NÁIT-mea","level":"a2","itemId":"ena2m2itwasadisaster"},"lessonId":"ena2m2l9","level":"a2"},{"card":{"id":"nat-ena2m3-1","book":"She has long dark hair.","real":"She's got long dark hair.","meaning":"Tiene el pelo largo y moreno","when":"En Reino Unido, «have got» es lo NORMAL al hablar de lo que uno tiene: el pelo, un coche, hermanos, dolor de cabeza. «She has» no está mal —y en el examen escrito puntúa igual—, pero suena a libro. En Estados Unidos se prefiere «has» a secas.","register":"neutral","note":"El got no añade significado: es puro relleno británico. Y al hablar rápido «she's got» se funde en «shis̬-got», una sola pieza.","sound":"shis̬ got long daak JÉA","level":"a2","itemId":"ena2m3longdarkhair"},"lessonId":"ena2m3l1","level":"a2"},{"card":{"id":"nat-ena2m3-2","book":"She's very nice.","real":"She's so lovely.","meaning":"Es un cielo / es un encanto","when":"Entre amigos y compañeros, hablando bien de alguien. En Reino Unido «lovely» se usa a todas horas y para casi todo (una persona, una tarde, una taza de té). En el Writing del examen, very nice o really kind: son las que enseñan la gramática que te puntúan.","register":"amigos","note":"so + adjetivo es el «qué maja es» español: lleva emoción, no medida. Y lovely ya lo traías del A1, solo que aplicado a cosas.","sound":"shis̬ sóu LAV-li","level":"a2","itemId":"ena2m3sonice"},"lessonId":"ena2m3l2","level":"a2"},{"card":{"id":"nat-ena2m3-3","book":"He works very hard.","real":"He works his socks off.","meaning":"Trabaja como un burro / se deja la piel","when":"Entre amigos y compañeros, admirando a alguien que se mata a trabajar. Es informal pero cariñoso, nunca ofensivo. En el Writing del examen escribe la del libro: he works very hard.","register":"amigos","note":"Literalmente «trabaja hasta quedarse sin calcetines». El inglés tiene media docena de estas con off. Y ojo al hard sin -ly de la versión del libro.","sound":"ji uéeks jis̬ SOKS of","level":"a2","itemId":"ena2m3sheworkshard"},"lessonId":"ena2m3l4","level":"a2"},{"card":{"id":"nat-ena2m3-4","book":"The house is very beautiful.","real":"The house is stunning.","meaning":"La casa es una preciosidad","when":"Entre amigos, valorando una casa, una vista, un vestido o una foto. Es entusiasta y muy común en Reino Unido. En el Writing del examen: very beautiful o really nice, que son las que enseñan el vocabulario que puntúa.","register":"amigos","note":"Y de paso, otra ración de clínica: stunning lleva el golpe en la primera — STA-ning, no stan-NÍNG.","sound":"de jáus is̬ STA-ning","level":"a2","itemId":"ena2m3beautiful"},"lessonId":"ena2m3l5","level":"a2"},{"card":{"id":"nat-ena2m3-5","book":"I was very bored.","real":"I was bored stiff.","meaning":"Me aburrí como una ostra","when":"Entre amigos, contando una charla, una reunión o una película insufrible. Muy común en Reino Unido y nada grosero. En el Writing del examen: very bored o really bored.","register":"amigos","note":"stiff es «tieso»: tan aburrido que te quedas rígido. Y fíjate en que sigue siendo -ed, porque quien se aburre eres tú.","sound":"ái uos̬ bood STIF","level":"a2","itemId":"ena2m3bored"},"lessonId":"ena2m3l7","level":"a2"},{"card":{"id":"nat-ena2m4-1","book":"It's very cheap.","real":"It's a bargain.","meaning":"Es una ganga / está tirado de precio","when":"En tiendas, mercadillos y rebajas, con amigos o con el dependiente. Es palabra de todos los días, no jerga. En el Writing del examen también vale, aunque la del libro (it's very cheap, it's good value) es la que nunca falla.","register":"neutral","note":"En las rebajas verás carteles con «bargains» a secas: son las gangas. Y ojo, bargain también es «regatear» cuando es verbo.","sound":"its a BAA-guin","level":"a2","itemId":"ena2m4muchcheaper"},"lessonId":"ena2m4l1","level":"a2"},{"card":{"id":"nat-ena2m4-2","book":"That's much better.","real":"That's way better.","meaning":"Eso está mucho mejor","when":"Con amigos y compañeros, comparando cualquier cosa: una foto, una versión, un sitio. Es informal pero muy corriente en Reino Unido. En el examen escrito, much better: way better te marcaría el registro como demasiado coloquial.","register":"amigos","note":"way delante de un comparativo es «mucho» subido de tono: way cheaper, way worse, way too expensive.","sound":"dats uéi BÉ-ta","level":"a2","itemId":"ena2m4itsbetterthan"},"lessonId":"ena2m4l3","level":"a2"},{"card":{"id":"nat-ena2m4-3","book":"How much is it?","real":"How much d'you want for it?","meaning":"¿Cuánto quieres por esto?","when":"En mercadillos y en compraventa entre particulares, donde el precio se habla. En una tienda normal, jamás: allí se dice How much is it? En el examen, siempre la del libro.","register":"amigos","note":"En Reino Unido no se regatea en las tiendas, pero sí en los mercadillos y en las ventas de segunda mano. Esta frase es la que abre esa conversación.","sound":"jáu mach dchu UÓNT fo rit","level":"a2","itemId":"enhowmuchisit"},"lessonId":"ena2m4l5","level":"a2"},{"card":{"id":"nat-ena2m4-4","book":"It's very big.","real":"It's massive.","meaning":"Es enorme","when":"Con amigos, para cualquier cosa grande de verdad: un piso, una maleta, una cola. Es de las palabras más usadas del inglés británico coloquial. En el examen escrito, very big o really big.","register":"amigos","note":"La familia entera funciona igual: massive (enorme), tiny (diminuto), freezing (helado), boiling (achicharrante). Son adjetivos que ya llevan el «muy» dentro, así que no admiten very delante.","sound":"its MA-siv","level":"a2","itemId":"ena2m4howbigisit"},"lessonId":"ena2m4l6","level":"a2"},{"card":{"id":"nat-ena2m4-5","book":"I prefer the first one.","real":"I'd go for the first one.","meaning":"Yo me quedaría con la primera","when":"Con amigos y compañeros, decidiendo entre dos opciones: un piso, un plan, un plato de la carta. Es la forma normal de dar tu preferencia sin sonar solemne. En el examen oral valen las dos; en el escrito, mejor I prefer.","register":"neutral","note":"go for something = decidirse por algo. Nada que ver con «ir a por algo» de recado, que sería go and get it.","sound":"áid góu fo de FÉEST uan","level":"a2","itemId":"ena2m4iprefertheseconone"},"lessonId":"ena2m4l9","level":"a2"},{"card":{"id":"nat-ena2m5-1","book":"Two coffees, please.","real":"Two coffees, cheers.","meaning":"Dos cafés, gracias","when":"En una barra, un pub o un puesto de comida, con quien te atiende. En Reino Unido «cheers» vale como «gracias» todo el día y no solo para brindar. En el Writing del examen, y con cualquiera a quien trates de usted, escribe please y thank you: cheers no puntúa como registro neutro.","register":"amigos","note":"Es una fórmula de cierre: se dice al final de la frase y sustituye al gracias, nunca al por favor.","sound":"tuu KO-fis̬, CHÍAS̬","level":"a2","itemId":"ena2m5twocoffeesplease"},"lessonId":"ena2m5l1","level":"a2"},{"card":{"id":"nat-ena2m5-2","book":"There's a lot of sugar in it.","real":"There's loads of sugar in it.","meaning":"Lleva un montón de azúcar","when":"Con amigos, hablando de cantidades: comida, gente, trabajo. «Loads of» vale para los dos montones, igual que a lot of, y en Reino Unido se oye a todas horas. En el examen escrito, a lot of: loads no baja nota pero no suma registro.","register":"amigos","note":"Su hermana es «tons of», y las dos son informales. Lo que NO se dice en afirmativa es «much sugar»: eso suena a gramática de examen mal aprendida.","sound":"déas̬ LÓUDS̬ ov SHU-ga","level":"a2","itemId":"ena2m5alotof"},"lessonId":"ena2m5l4","level":"a2"},{"card":{"id":"nat-ena2m5-3","book":"Could I have a coffee, please?","real":"Can I get a coffee, please?","meaning":"¿Me pones un café?","when":"En cafeterías y sitios de comida rápida, sobre todo con gente joven. Nació en Estados Unidos y hoy se oye por todo Reino Unido, aunque a los mayores les suena brusco. En el examen —oral y escrito— usa Could I have: es la que puntúa como registro neutro.","register":"amigos","note":"El get sustituye al have y baja medio peldaño la escalera: más rápido, menos formal. Sigue llevando please, que es lo que evita que sea una orden.","sound":"kan ái GUET a KO-fi, plíis̬","level":"a2","itemId":"ena2m5couldihavethemenu"},"lessonId":"ena2m5l8","level":"a2"},{"card":{"id":"nat-ena2m5-4","book":"Excuse me, there's a problem with my soup.","real":"Sorry to be a pain, but my soup's a bit cold.","meaning":"Perdona que dé la lata, pero la sopa está fría","when":"En Reino Unido, con quien te atiende, cuando quieres quejarte y que no se te note. «Sorry to be a pain» es la fórmula nacional: pide perdón por quejarse antes de quejarse. En el examen escribe la del libro, que es la que enseña la estructura que puntúan.","register":"amigos","note":"«A pain» es «un pesado». Es la capa cuarta de la queja: primero te disculpas por molestar y después dices lo que pasa, siempre con a bit.","sound":"SO-ri tu bi a PÉIN, bat mái suups a bit KÓULD","level":"a2","itemId":"ena2m5excusemethisiscold"},"lessonId":"ena2m5l9","level":"a2"},{"card":{"id":"nat-ena2m6-1","book":"We're going to travel by train.","real":"We're getting the train.","meaning":"Vamos en tren","when":"Con amigos y compañeros, para un plan ya cerrado. En Reino Unido «get the train / get the bus» es lo normal para coger un transporte. En el examen escribe «take the train» o «go by train»: las dos puntúan y no suenan raras.","register":"amigos","note":"get es el comodín del inglés hablado: get the train, get a taxi, get home. En el papel, take.","sound":"uía GUE-tin de TRÉIN","level":"a2","itemId":"entrain"},"lessonId":"ena2m6l1","level":"a2"},{"card":{"id":"nat-ena2m6-2","book":"What are you doing tonight?","real":"You up to anything tonight?","meaning":"¿Tienes algo esta noche? / ¿Haces algo esta noche?","when":"Entre amigos y compañeros, para tantear si alguien está libre antes de proponer nada. Se come el «Are» del principio, que es lo que la hace sonar tan informal. En el examen, y con quien no conoces: What are you doing tonight? o Are you free tonight?","register":"amigos","note":"«to be up to something» = tener algo entre manos. Ojo: no es lo mismo que «be up for something», que es «apuntarse».","sound":"yu AP tu É-ni-zing tu-NÁIT","level":"a2","itemId":"ena2m6whatareyoudoingtonight"},"lessonId":"ena2m6l3","level":"a2"},{"card":{"id":"nat-ena2m6-3","book":"I'm going to be late.","real":"I'm gonna be late!","meaning":"Voy a llegar tarde","when":"En cualquier conversación hablada, con quien sea: gonna no es vulgar, es sencillamente cómo suena going to cuando se habla a velocidad normal. Lo dice un catedrático y lo dice un niño. Lo que no se hace es escribirlo — ni en un email de trabajo ni en el examen.","register":"neutral","note":"Solo funciona delante de verbo. «I'm gonna the station» no existe en boca de nadie.","sound":"áim GA-na bi LÉIT","level":"a2","itemId":"ena2m6weregoingtobelate"},"lessonId":"ena2m6l5","level":"a2"},{"card":{"id":"nat-ena2m6-4","book":"There is a lot of traffic today.","real":"The traffic's terrible today.","meaning":"Hay un tráfico horrible hoy","when":"Con cualquiera, todos los días: es la queja nacional británica junto con el tiempo. Fíjate en que el nativo no dice «hay mucho», dice «el tráfico está fatal» — cambia la construcción entera. En el examen, «There's a lot of traffic» está perfecto y es más seguro.","register":"neutral","note":"El mismo giro sirve para el tiempo: «The weather's terrible». Es la forma corta de quejarse sin decir there is.","sound":"de TRÁ-fiks TE-ri-bol tu-DÉI","level":"a2","itemId":"ena2m6atrafficjam"},"lessonId":"ena2m6l7","level":"a2"},{"card":{"id":"nat-ena2m6-5","book":"Have a good trip!","real":"Safe travels!","meaning":"¡Buen viaje!","when":"Al despedir a alguien que se va de viaje, con amigos o con compañeros de trabajo. Se ha vuelto lo normal en los últimos años, sobre todo por escrito, en un mensaje. Para una postal o un email de examen, «Have a good trip!» sigue siendo perfecto y nunca queda raro.","register":"neutral","note":"Ojo con «Good trip!» a secas: no se dice. O va con Have a…, o se usa Safe travels.","sound":"séif TRÁ-vels̬","level":"a2","itemId":"ena2m6haveagoodtrip"},"lessonId":"ena2m6l9","level":"a2"},{"card":{"id":"nat-ena2m7-1","book":"You have to check in first.","real":"You've got to check in first.","meaning":"Primero hay que facturar","when":"Entre amigos y en cualquier conversación de calle en Reino Unido: have got to es tan corriente como have to, quizá más. En el Writing del examen, mejor have to: es la forma neutra y no falla nunca.","register":"neutral","note":"Y al hablar deprisa, «got to» se funde en gotta: I gotta go. Eso ya es informal del todo — se reconoce, no se escribe.","sound":"yuv got tu CHEK in féest","level":"a2","itemId":"ena2m7youhavetocheckin"},"lessonId":"ena2m7l1","level":"a2"},{"card":{"id":"nat-ena2m7-2","book":"I must go.","real":"I'd better be off.","meaning":"Me tengo que ir yendo","when":"Entre amigos y en visitas, para levantarse sin dar un portazo: es la forma educada de anunciar que te marchas. En una carta o en el examen escrito, I must go o I have to go.","register":"amigos","note":"Literalmente «más me vale estar fuera». En Reino Unido se dice muchísimo, y casi siempre acompañada de un movimiento de levantarse de la silla.","sound":"áid BE-ta bi OF","level":"a2","itemId":"ena2m7imustgo"},"lessonId":"ena2m7l2","level":"a2"},{"card":{"id":"nat-ena2m7-3","book":"You mustn't do that.","real":"You're not supposed to do that.","meaning":"Eso no se puede hacer / no deberías estar haciendo eso","when":"En la calle, en el trabajo y entre vecinos, para recordarle a alguien una norma sin sonar a policía. Es la forma que oirás de verdad; mustn't, dicho a la cara, suena bastante duro. En el examen escrito, mustn't o isn't allowed.","register":"neutral","note":"be supposed to = «se supone que tienes que». Sirve para las dos direcciones: You're supposed to sign it (hay que firmarlo) y You're not supposed to park here (no se puede aparcar).","sound":"yoo not sa-PÓUS̬T tu du DAT","level":"a2","itemId":"ena2m7youmustntsmoke"},"lessonId":"ena2m7l3","level":"a2"},{"card":{"id":"nat-ena2m7-4","book":"You don't have to pay.","real":"You don't need to pay.","meaning":"No hace falta pagar","when":"En cualquier mostrador de Reino Unido: need to es hoy tan corriente como have to y suena un poco más amable, menos a reglamento. Las dos valen en el examen, escrito y oral.","register":"neutral","note":"Y hay una tercera, más seca, que también oirás: «There's no need». Sirve ella sola de respuesta cuando alguien se ofrece a pagar.","sound":"yu dóunt níid tu PÉI","level":"a2","itemId":"ena2m7youdonthavetopay"},"lessonId":"ena2m7l4","level":"a2"},{"card":{"id":"nat-ena2m7-5","book":"I'm afraid you can't.","real":"Sorry, no can do.","meaning":"Lo siento, imposible","when":"Entre compañeros y amigos, y solo para cosas sin importancia: un favor pequeño, un cambio de turno. Con un cliente o en una ventanilla, jamás — ahí suena a que te da igual. En el examen, siempre I'm afraid you can't.","register":"amigos","note":"Es una frase hecha con la gramática rota a propósito, como el «ni de broma» español. No intentes analizarla: se aprende entera o no se usa.","sound":"SO-ri, nóu kan DÚU","level":"a2","itemId":"ena2m7imafraidyoucant"},"lessonId":"ena2m7l6","level":"a2"},{"card":{"id":"nat-ena2m7-6","book":"Could I have a stamp, please?","real":"Could I get a stamp, please?","meaning":"¿Me pone un sello, por favor?","when":"En cafés, tiendas y ventanillas, sobre todo entre gente joven: «Could I get…» se ha comido media isla en veinte años. A alguien mayor puede sonarle americano y un poco brusco, así que en el examen y por escrito, siempre have.","register":"neutral","note":"Los dos verbos piden lo mismo. La diferencia es de generación, no de educación: have es lo de siempre y get es lo de ahora.","sound":"kud ái guet a STAMP, plíis̬","level":"a2","itemId":"ena2m7couldihaveastamp"},"lessonId":"ena2m7l7","level":"a2"},{"card":{"id":"nat-ena2m7-7","book":"I couldn't get through.","real":"I couldn't get hold of anyone.","meaning":"No conseguí hablar con nadie","when":"En cualquier queja de servicio, hablando o por escrito, y es de las pocas expresiones informales que también quedan bien en un correo de reclamación. En el examen valen las dos.","register":"neutral","note":"get hold of someone = «localizar a alguien», por el medio que sea. Si la línea comunicaba, get through; si nadie te devolvió las llamadas, get hold of.","sound":"ái KU-dent guet JÓULD ov E-ni-uan","level":"a2","itemId":"ena2m7icouldntgetthrough"},"lessonId":"ena2m7l8","level":"a2"},{"card":{"id":"nat-ena2m7-8","book":"What does that sign say?","real":"What's that sign on about?","meaning":"¿Y ese cartel qué quiere decir?","when":"Entre amigos, con un punto de fastidio: se usa cuando el cartel te parece absurdo o incomprensible. En una ventanilla o en el examen, la del libro.","register":"amigos","note":"be on about = «ir de qué», «querer decir», siempre con un poquito de guasa. What are you on about? es «¿pero tú de qué hablas?».","sound":"uóts dat SÁIN on a-báut","level":"a2","itemId":"ena2m7whatdoesthesignsay"},"lessonId":"ena2m7l9","level":"a2"},{"card":{"id":"nat-ena2m8-1","book":"I have a very bad headache.","real":"I've got a splitting headache.","meaning":"Tengo un dolor de cabeza que me parte","when":"Entre amigos y en casa, cuando el dolor de cabeza es de los gordos. Se oye a diario en Reino Unido. En el examen, oral o escrito, di la del libro (a very bad headache): es la que enseña la estructura que puntúan.","register":"amigos","note":"splitting es de split, «partir en dos»: la misma imagen que el español «me parte la cabeza». Por una vez, las dos lenguas ven lo mismo.","sound":"áiv got a SPLÍ-ting JÉ-deik","level":"a2","itemId":"ena2m8ihaveaheadache"},"lessonId":"ena2m8l1","level":"a2"},{"card":{"id":"nat-ena2m8-2","book":"I don't feel very well.","real":"I feel a bit rough.","meaning":"Estoy hecho polvo / regular","when":"Con amigos, compañeros y en casa, para decir que no estás bien sin dar detalles. Muy británico. En la consulta y en el examen, la del libro: «I don't feel very well» es la que entiende todo el mundo y la que puntúa.","register":"amigos","note":"rough es «áspero, tosco»; aplicado a personas es «hecho polvo». Su pariente cercano es «I feel awful», que ya es más fuerte.","sound":"ái fiil a bit RAF (rough rima con «stuff»)","level":"a2","itemId":"ena2m8idontfeelwell"},"lessonId":"ena2m8l2","level":"a2"},{"card":{"id":"nat-ena2m8-3","book":"I have a stomach ache.","real":"I've got a dodgy tummy.","meaning":"Tengo la tripa fatal","when":"Entre amigos, en casa y en el trabajo, para no dar detalles. Purísimo inglés británico. En la consulta y en el examen, la del libro: «a stomach ache» es lo que entiende el médico y lo que puntúa por escrito.","register":"amigos","note":"dodgy es «poco fiable, chungo»: sirve para una tripa, un coche y una web. Y tummy es «tripa» en el registro de andar por casa.","sound":"áiv got a DO-dchi TA-mi","level":"a2","itemId":"ena2m8achegroup"},"lessonId":"ena2m8l4","level":"a2"},{"card":{"id":"nat-ena2m8-4","book":"Why don't you rest for a while?","real":"Why don't you have a lie-down?","meaning":"¿Por qué no te echas un rato?","when":"En casa, con familia y amigos, cuando alguien está agotado o malo. Muy británico y muy de todos los días. En el examen, la del libro: rest es la palabra que entiende cualquier corrector.","register":"amigos","note":"a lie-down es «una tumbada»: un sustantivo hecho del verbo lie down. El inglés fabrica muchos así — a chat, a walk, a look.","sound":"uái dóunchu jav a LÁI-daun","level":"a2","itemId":"ena2m8whydontyougohome"},"lessonId":"ena2m8l6","level":"a2"},{"card":{"id":"nat-ena2m8-5","book":"Have you got anything for a cough?","real":"Have you got anything for a tickly cough?","meaning":"¿Tiene algo para la tos seca, esa que pica?","when":"En la farmacia, tal cual: en Reino Unido distinguen «tickly cough» (seca, que pica) de «chesty cough» (con flema), y los jarabes vienen etiquetados así. Saberlo te ahorra comprar el que no es. En el examen basta con «a cough».","register":"neutral","note":"tickly es de tickle, «hacer cosquillas»: una tos que hace cosquillas. Y chesty viene de chest, el pecho.","sound":"jav yu got E-ni-zing foo a TÍ-kli KOF","level":"a2","itemId":"ena2m8acough"},"lessonId":"ena2m8l8","level":"a2"},{"card":{"id":"nat-ena2m8-6","book":"I'm much better, thanks.","real":"I'm on the mend.","meaning":"Ya voy mejorando","when":"Con amigos, vecinos y compañeros, cuando ya has pasado lo peor pero no estás del todo. Muy común en Reino Unido, sobre todo entre gente mayor. En el examen, la del libro: «much better» es la que enseña el comparativo que puntúan.","register":"amigos","note":"mend es «arreglar, remendar»: estar «on the mend» es estar en proceso de arreglo, como un jersey en el costurero.","sound":"áim on de MEND","level":"a2","itemId":"ena2m8imuchbetterthanks"},"lessonId":"ena2m8l9","level":"a2"},{"card":{"id":"nat-ena2m9-1","book":"Can you help me?","real":"Give us a hand, would you?","meaning":"Échame una mano, ¿quieres?","when":"Entre compañeros de piso, amigos y compañeros de trabajo, para pedir ayuda con algo pequeño y físico: una caja, una mesa, la compra. En el examen escribe Could you help me, please?: «give us a hand» es de cocina, no de Writing.","register":"amigos","note":"Y ojo al detalle que te descoloca: ese «us» quiere decir «me». En el inglés hablado de Reino Unido, us se cuela con frecuencia donde el libro pondría me. No lo produzcas todavía; reconócelo al oírlo.","sound":"guiv as a JAND, uud yu","level":"a2"},"lessonId":"ena2m9l1","level":"a2"},{"card":{"id":"nat-ena2m9-2","book":"I don't understand.","real":"You've lost me.","meaning":"Me he perdido / no te sigo.","when":"Cuando alguien te está explicando algo y te has descolgado: en una conversación con amigos, con compañeros de piso o de trabajo. Es más suave que «I don't understand», porque pone la culpa en la explicación y no en ti. En el examen escrito, la del libro.","register":"amigos","note":"Y fíjate en el pronombre: «me» detrás del verbo, como toda la lección. Lo que sigue después suele ser «Can you say that again?».","sound":"yuuv LOST mi","level":"a2"},"lessonId":"ena2m9l2","level":"a2"},{"card":{"id":"nat-ena2m9-3","book":"Come in and sit down, please.","real":"Make yourself at home.","meaning":"Estás en tu casa.","when":"Cuando alguien entra en tu piso por primera vez. Es de las fórmulas más fijas del inglés doméstico y no se cambia ni una palabra. En un email formal no pega; entre amigos y compañeros de piso, es lo normal.","register":"amigos","note":"Otro reflexivo de los que sí van: «yourself» porque el que se pone cómodo es el propio invitado. La hermana pequeña, para la cocina, es «Help yourself».","sound":"méik yoo-SELF at JÓUM","level":"a2"},"lessonId":"ena2m9l3","level":"a2"},{"card":{"id":"nat-ena2m9-4","book":"It isn't mine.","real":"Nothing to do with me.","meaning":"Yo no he sido / no es cosa mía.","when":"Entre compañeros de piso, cuando aparece algo en la cocina y nadie lo reclama, o cuando te achacan un lío que no es tuyo. Suena a defensa rápida; en un email de trabajo escribe «That wasn't me» o «It isn't mine».","register":"amigos","note":"Frase sin verbo, como muchas de las que se dicen de verdad. Y otra vez el pronombre de objeto detrás de la preposición: with ME, nunca with I.","sound":"NA-zing tu du uid mi","level":"a2"},"lessonId":"ena2m9l4","level":"a2"},{"card":{"id":"nat-ena2m9-7","book":"Can you take out the rubbish?","real":"Can you stick the bins out?","meaning":"¿Sacas la basura?","when":"Entre compañeros de piso y en familia, en Reino Unido. «The bins» son los cubos grandes que se dejan en la acera, y «stick» aquí no es pegar: significa «poner ahí sin más». En la nota de la nevera y en el examen, «take out the rubbish».","register":"amigos","note":"«Stick it in the fridge», «stick it on the table», «stick the kettle on»: stick sirve para colocar cualquier cosa en cualquier sitio sin ceremonia. Es de las palabras más útiles del inglés doméstico.","sound":"kan yu STIK de BINS̬ áut","level":"a2"},"lessonId":"ena2m9l7","level":"a2"},{"card":{"id":"nat-ena2m9-8","book":"I have to go now. Goodbye.","real":"Right, I'll let you get on.","meaning":"Bueno, te dejo, que sigas con lo tuyo.","when":"Para cerrar una conversación en persona o por teléfono sin que parezca que huyes: pones la excusa en el otro («que sigas con lo tuyo») en vez de en ti. Es de lo más británico que hay. En el examen escrito, «I have to go now».","register":"amigos","note":"«Get on» aquí es «seguir con lo que estabas haciendo». Y el «Right» del principio es la señal de cierre: sin ella, la frase suena a que te están echando.","sound":"ráit, áil let yu guet ON","level":"a2"},"lessonId":"ena2m9l8","level":"a2"},{"card":{"id":"nat-ena2m9-9","book":"The woman who lives next door is a nurse.","real":"The woman next door's a nurse.","meaning":"La vecina de al lado es enfermera.","when":"Al hablar de vecinos: «the woman next door» es un sitio («de al lado»), no una relativa recortada. Lo que sí se come el habla es el is: door's = door is. En el examen escrito, la frase entera con «who lives».","register":"amigos","note":"Ojo a ese «door's», que es «door is» y no un genitivo, aunque se escriba igual. Es el par de la lección 5 otra vez: la ortografía no distingue lo que la gramática sí.","sound":"de UÚ-man nekst DÓOS̬ a NEES̬","level":"a2"},"lessonId":"ena2m9l9","level":"a2"},{"card":{"id":"nat-ena2m10-1","book":"Have you ever tried it?","real":"Ever tried it?","meaning":"¿Lo has probado alguna vez?","when":"Entre amigos, hablando de comida, de una serie o de un sitio. Se cae el «Have you» entero y arranca por ever. En el examen escribe y di la pregunta completa: el recorte es de conversación, no de papel.","register":"amigos","note":"El inglés hablado se come el principio de las preguntas cuando el contexto ya lo dice: «Been there?», «Seen it?», «Got a minute?».","sound":"É-va TRÁID it","level":"a2","itemId":"ena2m10haveyouever"},"lessonId":"ena2m10l1","level":"a2"},{"card":{"id":"nat-ena2m10-2","book":"I have finished.","real":"I'm done.","meaning":"Ya está / He terminado","when":"Entre amigos y compañeros: acabas la comida, el turno o una tarea. Es cortísima y clarísima. Ojo, no es el participio de este módulo haciendo de perfecto: es done funcionando como adjetivo, «listo». En el examen escrito, I've finished.","register":"amigos","note":"Su gemela para preguntar es «Are you done?» — «¿has acabado?». Y en un restaurante, «Are you done with that?» significa «¿se lo retiro?».","sound":"áim DAN","level":"a2"},"lessonId":"ena2m10l2","level":"a2"},{"card":{"id":"nat-ena2m10-5","book":"I have not seen him.","real":"I've not seen him.","meaning":"No lo he visto","when":"Muy británico, sobre todo en el norte y en Escocia: en vez de contraer el not (haven't), se contrae el have y el not queda suelto. Las dos son correctas y las dos se escriben. En el examen, cualquiera de las dos vale.","register":"regional","note":"Es una de las pocas veces en que el inglés te deja elegir dónde poner la contracción. Un londinense dirá «I haven't seen him»; un mancuniano, «I've not seen him».","sound":"áiv not SÍIN jim","level":"a2"},"lessonId":"ena2m10l5","level":"a2"},{"card":{"id":"nat-ena2m10-7","book":"I have worked here for a long time.","real":"I've been here ages.","meaning":"Llevo aquí un montón de tiempo","when":"Charla informal en el trabajo o con vecinos. Fíjate en dos cosas: «ages» es «un montón», no «edades», y en esta fórmula hasta el for se cae. En el examen escribe la de arriba, con for y todo.","register":"amigos","note":"«ages» es tan común que sirve para todo: «I haven't seen you for ages» — «hace siglos que no te veo». Esa sí conserva el for.","sound":"áiv bin jía ÉI-dchis̬","level":"a2","itemId":"ena2m10forthreeyears"},"lessonId":"ena2m10l7","level":"a2"},{"card":{"id":"nat-ena2m10-8","book":"I passed the exam.","real":"I got through it.","meaning":"Lo saqué / conseguí aprobarlo","when":"Contándoselo a alguien de confianza, cuando el examen costó. Lleva dentro un «por los pelos» que pass no tiene. En el Writing del examen, pass.","register":"amigos","note":"get through sirve para todo lo que se supera con esfuerzo: un examen, una semana horrible, una entrevista. Y también, muy útil, «I couldn't get through» = no conseguí que me cogieran el teléfono.","sound":"ái got ZRÚU it","level":"a2","itemId":"ena2m10ipassedtheexam"},"lessonId":"ena2m10l8","level":"a2"},{"card":{"id":"nat-ena2m10-9","book":"It's the best coffee I have ever had.","real":"Best coffee ever.","meaning":"El mejor café de la historia","when":"Coloquial y muy actual: se cae la frase entera y quedan tres palabras. Vale para todo — «best day ever», «worst film ever». En el examen escribe la fórmula completa: es superlativo + I've ever + participio, y ahí sí puntúa.","register":"amigos","note":"Es la única puerta por la que ever entra en una afirmativa: detrás de un superlativo. En cualquier otro sitio, ever es de preguntas.","sound":"best KO-fi É-va","level":"a2","itemId":"ena2m10thebestivever"},"lessonId":"ena2m10l9","level":"a2"},{"card":{"id":"nat-ena2m11-2","book":"I think it will rain.","real":"I reckon it'll rain.","meaning":"Yo creo que va a llover","when":"Entre amigos y compañeros, en todo Reino Unido, para dar tu opinión sobre algo que aún no ha pasado. «Reckon» es cotidiano y muy común en el habla, pero en el Writing del examen escribe «I think»: es lo que espera el corrector y no te la juegas.","register":"amigos","note":"reckon se usa casi solo en presente y con opinión: I reckon, do you reckon? Nada de «I am reckoning».","sound":"ái RE-kon Í-tol RÉIN","level":"a2","itemId":"ena2m11ithinkitllrain"},"lessonId":"ena2m11l2","level":"a2"},{"card":{"id":"nat-ena2m11-3","book":"It's raining a lot.","real":"It's chucking it down.","meaning":"Está cayendo un diluvio","when":"Entre amigos y en el trabajo, en todo Reino Unido, cuando llueve de verdad. Muy hablado y muy británico. En el examen escribe «It's raining heavily» o «It's pouring»: las dos son correctas y ninguna te baja el registro.","register":"amigos","note":"«It's pouring» está a medio camino: se dice mucho y se puede escribir sin problema.","sound":"its CHA-king it DÁUN","level":"a2","itemId":"enitsraining"},"lessonId":"ena2m11l3","level":"a2"},{"card":{"id":"nat-ena2m11-4","book":"Perhaps. I am not sure.","real":"Might do.","meaning":"A lo mejor. / Puede.","when":"Entre amigos, como respuesta corta a «¿vas a ir?», «¿lo vas a hacer?». Es muy británico y muy hablado: dos palabras y ni un sujeto. En el examen contesta «I might» o «I'm not sure yet»: dicen lo mismo y sí puntúan.","register":"amigos","note":"El truco está en el «do», que sustituye al verbo entero de la pregunta: «Are you going?» → «Might do».","sound":"máit DÚU","level":"a2","itemId":"ena2m11itmightrain"},"lessonId":"ena2m11l4","level":"a2"},{"card":{"id":"nat-ena2m11-5","book":"We will not be long.","real":"We won't be a minute.","meaning":"No tardamos nada","when":"Con amigos y en cualquier tienda o casa ajena, cuando te vas un momento y quieres tranquilizar al otro. Literalmente dice «no seremos un minuto», que es al revés de lo que significa, y aun así es de lo más corriente. En el examen, «We won't be long».","register":"neutral","note":"Hay un gemelo aún más raro: «I won't be a sec». Se oye, se entiende y no se escribe nunca.","sound":"ui uóunt bi a MI-nit","level":"a2","itemId":"ena2m11wewontbelong"},"lessonId":"ena2m11l5","level":"a2"},{"card":{"id":"nat-ena2m11-6","book":"If it rains, we will stay at home.","real":"If it rains, we'll just stay in.","meaning":"Si llueve, nos quedamos en casa y ya está","when":"Con amigos y en casa. «Stay in» es quedarse en casa, y es lo que dice todo el mundo; «stay at home» suena a redacción. Y ese «just» no significa «solo»: es el «y ya está» que quita hierro al plan B. En el examen, «stay at home» o «stay in», las dos valen.","register":"amigos","note":"El par es stay in / go out, y funciona igual que quedarse y salir.","sound":"if it RÉINS̬, uíil dchast stéi IN","level":"a2","itemId":"ena2m11ifitrains"},"lessonId":"ena2m11l6","level":"a2"},{"card":{"id":"nat-ena2m11-8","book":"I hope so.","real":"Fingers crossed!","meaning":"¡A ver si hay suerte! / ¡Crucemos los dedos!","when":"Con amigos y compañeros, para desear que algo salga bien: el tiempo, una entrevista, un tren que llega. Se dice y se hace el gesto a la vez. Por escrito aparece en mensajes, nunca en un email de examen: ahí escribe «I hope so» o «Let's hope so».","register":"amigos","note":"En Reino Unido se cruzan dos dedos de la misma mano; el gesto español de tocar madera no se usa.","sound":"FING-gas̬ KROST","level":"a2","itemId":"ena2m11ihopeso"},"lessonId":"ena2m11l8","level":"a2"},{"card":{"id":"nat-ena2m11-9","book":"We will go whatever the weather is.","real":"We're going, rain or shine.","meaning":"Vamos, llueva o no llueva","when":"Con amigos y compañeros, para decir que el plan no se cancela pase lo que pase. Es de las expresiones más comunes del inglés británico y aparece en carteles de mercadillos y de fiestas de barrio. En el examen escribe «whatever the weather»: dice lo mismo y es igual de correcta.","register":"neutral","note":"No se dice «rain or sun»: la pareja fija es rain or shine, y se queda así.","sound":"uía GÓU-ing, RÉIN oo SHÁIN","level":"a2","itemId":"ena2m11whatevertheweather"},"lessonId":"ena2m11l9","level":"a2"},{"card":{"id":"nat-ena2m12-1","book":"You will hear the recording twice.","real":"You'll hear it twice.","meaning":"Oirá la grabación dos veces — la frase que te salva el Listening","when":"En el audio del examen la versión completa; en boca del invigilador de la sala, la corta. Tú no tienes que decirla: solo reconocerla y respirar.","register":"neutral","note":"El inglés hablado contrae el auxiliar y sustituye el sustantivo largo por it en cuanto ya se sabe de qué se habla.","sound":"yul JÍA it TUÁIS","level":"a2","itemId":"entwice"},"lessonId":"ena2m12l1","level":"a2"},{"card":{"id":"nat-ena2m12-2","book":"Would you like some more tea?","real":"More tea?","meaning":"¿Más té? — el ofrecimiento reducido a dos palabras","when":"En casa de alguien, en una mesa, con la tetera en la mano. En el examen lo oyes así de corto en la Parte 2 y tienes que reconocer que es un OFRECIMIENTO, no una pregunta de información.","register":"amigos","note":"Los ofrecimientos en inglés se acortan hasta el sustantivo: «Coffee?», «Lift?», «Hand?». La entonación sube y eso basta.","sound":"móo TÍI? (subiendo)","level":"a2","itemId":"ena2m5wouldyoulikesometea"},"lessonId":"ena2m12l2","level":"a2"},{"card":{"id":"nat-ena2m12-3","book":"Hold the line, please.","real":"Bear with me a sec.","meaning":"Un momentito, por favor — «no cuelgue» en versión humana","when":"Al teléfono en una oficina, en el banco, en una tienda. Lo vas a OÍR mucho más de lo que lo vas a decir. En la Parte 3 del Listening te sitúa de golpe: si alguien dice esto, estás en una llamada.","register":"neutral","note":"bear with me = «ten paciencia conmigo»; a sec es second recortado, como el «un segui» español.","sound":"béa uid mi a SEK","level":"a2","itemId":"ena2m12holdtheline"},"lessonId":"ena2m12l3","level":"a2"},{"card":{"id":"nat-ena2m12-4","book":"The shop is closed today.","real":"We're shut.","meaning":"Está cerrado — lo que dice el tendero, no el cartel","when":"En la puerta de una tienda, dicho por una persona. El cartel escribe CLOSED; la persona dice we're shut. En el examen lo leerás como closed y lo oirás como shut: son la misma cosa.","register":"neutral","note":"shut es más de boca que de papel: en carteles y avisos escritos casi siempre pone closed.","sound":"uía SHAT","level":"a2","itemId":"ena2m12thenotice"},"lessonId":"ena2m12l4","level":"a2"},{"card":{"id":"nat-ena2m12-5","book":"Sorry for the late reply!","real":"Sorry, only just seen this!","meaning":"Perdona, lo acabo de ver — la disculpa por tardar, en versión mensajería","when":"En WhatsApp o en un mensaje entre amigos. En el Writing 1 del examen escribe la versión completa: es igual de informal y no se juega nada.","register":"amigos","note":"El inglés escrito rápido se come el sujeto: «Only just seen this» por «I've only just seen this».","sound":"SO-ri, ÓUN-li dchast SÍIN dis","level":"a2","itemId":"ena2m12sorryforthelatereply"},"lessonId":"ena2m12l6","level":"a2"},{"card":{"id":"nat-ena2m12-6","book":"I would be grateful for any information.","real":"Any info would be great, thanks!","meaning":"Cualquier información me vendría bien — la misma petición, en correo de trabajo del día a día","when":"En un correo entre compañeros o a una tienda pequeña. En el Writing 2 del examen, NUNCA: info por information y great por grateful son justo lo que el criterio de registro está mirando.","register":"neutral","note":"info es la forma corta de information y en inglés hablado se usa muchísimo; en un texto formal, jamás.","sound":"É-ni ÍN-fou ud bi GRÉIT, zanks","level":"a2","itemId":"ena2m12iwouldbegrateful"},"lessonId":"ena2m12l7","level":"a2"},{"card":{"id":"nat-ena2m12-7","book":"Sorry, I don't understand the question.","real":"Sorry, come again?","meaning":"Perdona, ¿cómo dices? — pedir que repitan sin decir que no entiendes","when":"En cualquier conversación. En el examen puedes usar la corta una vez; si necesitas más, di la larga, que además enseña al examinador que sabes construirla.","register":"amigos","note":"come again? es «repite» en tres sílabas; la versión de examen es la completa, y no cuesta puntos usarla.","sound":"SO-ri, kam a-GUÉN?","level":"a2","itemId":"ena2m12sorryidontunderstandthequestion"},"lessonId":"ena2m12l8","level":"a2"},{"card":{"id":"nat-ena2m12-8","book":"Good luck with your exam!","real":"Break a leg!","meaning":"¡Mucha suerte! — literalmente «rómpete una pierna», que es como se desea suerte sin gafarla","when":"Antes de un examen, de una actuación o de una entrevista, entre gente que se conoce. En un correo formal, Good luck a secas; break a leg entre amigos y con sonrisa.","register":"amigos","note":"Viene del teatro: desear suerte directamente daba mala suerte, así que se desea lo contrario.","sound":"bréik a LEG","level":"a2","itemId":"engoodluck"},"lessonId":"ena2m12l9","level":"a2"},{"card":{"id":"nat-enb1m1-1","book":"I have lived here for two years.","real":"I've been here two years now.","meaning":"Llevo aquí dos años ya","when":"Hablando, con cualquiera: es lo que dice de verdad un londinense. Se come el «for» y añade «now». En el Writing NO: allí el «for» va escrito y la forma continua suma en el criterio de gramática.","register":"neutral","exam":"I've been living in London for two years.","note":"El «now» final no significa «ahora»: significa «a estas alturas». Y el «for» desaparece en el habla porque la duración ya se entiende — pero desaparece solo cuando la dices, nunca cuando la escribes.","sound":"aiv bin JÍA tuu YÍAS̬ nau","level":"b1","produce":true,"itemId":"enb1m1natbeenhere"},"lessonId":"enb1m1l1","level":"b1"},{"card":{"id":"nat-enb1m1-2","book":"I am very tired.","real":"I'm shattered.","meaning":"Estoy hecho polvo","when":"Con amigos, compañeros y vecinos, en todo el Reino Unido. Es coloquial pero no vulgar: se lo dices a tu casera sin problema. En el Writing formal y en el Speaking de examen, no: allí sube el registro a «exhausted».","register":"amigos","exam":"I'm exhausted.","note":"«shattered» es literalmente «hecho añicos», y es el adjetivo de cansancio más británico que hay. Sus primos: «knackered» (más informal todavía) y «worn out» (neutro).","sound":"aim SHÁ-tad","level":"b1","produce":true,"itemId":"enb1m1natshattered"},"lessonId":"enb1m1l3","level":"b1"},{"card":{"id":"nat-enb1m1-3","book":"It is very expensive.","real":"It costs an arm and a leg.","meaning":"Cuesta un ojo de la cara","when":"Quejándote con amigos o compañeros de trabajo, y sobre precios de verdad —el alquiler, un billete de tren, una boda—, nunca sobre un café. En el Writing formal y en el Reading no aparece: allí el precio se comenta con un adverbio, no con una imagen.","register":"amigos","exam":"It's rather expensive.","note":"El español pone un ojo y el inglés un brazo y una pierna: las dos lenguas pagan con el cuerpo. Ojo con «rather» en la versión de examen — suena a queja contenida, que es justo el tono que puntúa.","sound":"it kosts an aam and a leg","level":"b1","produce":true,"itemId":"enb1m1natarmandaleg"},"lessonId":"enb1m1l4","level":"b1"},{"card":{"id":"nat-enb1m1-4","book":"I have to go now.","real":"I'd better be off.","meaning":"Me tengo que ir yendo","when":"Para despedirte sin brusquedad de una conversación que ya se alarga: en casa de alguien, en el pub, al final de una visita al piso. Es la fórmula educada de la calle. En un correo o en el Speaking de examen no cabe: allí se avisa con una frase entera.","register":"neutral","exam":"I'm afraid I have to go now.","note":"«had better» siempre se contrae en «'d better», y muchísimos hablantes se comen hasta eso: «Better be off». Ojo — detrás va infinitivo SIN «to»: «I'd better go», nunca «I'd better to go».","sound":"aid BÉ-ta bi of","level":"b1","produce":true,"itemId":"enb1m1natbetterbeoff"},"lessonId":"enb1m1l9","level":"b1"},{"card":{"id":"nat-enb1m2-1","book":"I'm looking for a job.","real":"I'm on the job hunt.","meaning":"Estoy buscando trabajo","when":"Hablando, con amigos y compañeros: es lo que se dice de verdad, y suena activo, no lastimero. En una carta de presentación o en el Writing NO: allí queda coloquial y baja el criterio de vocabulario por registro.","register":"neutral","exam":"I am currently looking for work.","note":"«Hunt» es «caza», y la imagen es esa: no estás esperando, estás persiguiendo. Se dice «on the job hunt» o «job-hunting», nunca «in the job hunt».","sound":"aim on de dchob jant","level":"b1","produce":true,"itemId":"enb1m2natjobhunt"},"lessonId":"enb1m2l1","level":"b1"},{"card":{"id":"nat-enb1m2-2","book":"I earn enough.","real":"It pays the bills.","meaning":"Da para vivir","when":"Contestando a «¿qué tal el trabajo?» cuando no quieres entrar en cifras. Lleva dentro un encogimiento de hombros: no es entusiasmo, es conformidad. En el Writing formal y en el Speaking de examen, no: allí se dice con una frase entera y neutra.","register":"neutral","exam":"The salary is adequate.","note":"Casi siempre va sola, como respuesta corta, y muchas veces con un «well» delante: «Well, it pays the bills». Si alguien te la dice, no le preguntes cuánto gana: te acaba de decir que prefiere no hablar de eso.","sound":"it péis̬ de bils̬","level":"b1","produce":true,"itemId":"enb1m2natpaysthebills"},"lessonId":"enb1m2l4","level":"b1"},{"card":{"id":"nat-enb1m2-3","book":"He was dismissed.","real":"He got the sack.","meaning":"Lo echaron del trabajo","when":"Hablando, entre conocidos, y siempre de otra persona o de uno mismo en tono resignado. En un correo, en un formulario o en el Writing, jamás: allí se dice «he was dismissed» o —si fue por recorte de plantilla y no por culpa suya— «he was made redundant», que es otra cosa y conviene no confundir.","register":"amigos","exam":"He was dismissed.","note":"«The sack» es literalmente «el saco»: la imagen es la de recoger tus herramientas y llevártelas. También se oye «he got sacked» y «they sacked him». Ojo con la diferencia legal: «sacked» es por algo que hiciste; «made redundant» es porque el puesto desapareció.","sound":"ji got de sak","level":"b1","produce":true,"itemId":"enb1m2natgotthesack"},"lessonId":"enb1m2l5","level":"b1"},{"card":{"id":"nat-enb1m2-4","book":"I'll do it.","real":"I'll crack on with it.","meaning":"Me pongo con ello ahora mismo","when":"En el trabajo, con compañeros o con un jefe con el que tienes confianza: significa que empiezas ya y sin dar más vueltas. En un correo a alguien de fuera o en el Writing, no: allí queda demasiado de andar por casa.","register":"neutral","exam":"I'll get on with it straight away.","note":"«Crack on» es «ponerse a ello sin más» y es muy británico. También se usa suelto, como ánimo: «Right, crack on» = «venga, al lío». Ojo: «crack on with» algo, nunca «crack on something».","sound":"ail krak on uid it","level":"b1","produce":true,"itemId":"enb1m2natcrackon"},"lessonId":"enb1m2l9","level":"b1"},{"card":{"id":"nat-enb1m3-1","book":"He said he was tired.","real":"He was like, 'I'm knackered'.","meaning":"Y él va y dice: «estoy reventado»","when":"Contando una anécdota entre amigos, y sobre todo entre menores de cuarenta. Es la forma más viva de citar a alguien en el inglés hablado de hoy — pero es SOLO para reconocerla: en el Writing y en el Speaking del examen baja el registro de golpe.","register":"jerga","exam":"He said (that) he was tired.","note":"Aquí la versión del libro y la del examen coinciden, cosa rarísima en estas tarjetas: es que el estilo indirecto normal YA es lo que puntúa. Lo que cambia es la calle. Y ojo al «be like»: no significa «parecerse», significa «y dice/dijo», y lo que viene detrás es la cita literal, no una frase referida.","sound":"ji uos̬ laik, aim NÁ-kad","level":"b1","itemId":"enb1m3natwaslike"},"lessonId":"enb1m3l1","level":"b1"},{"card":{"id":"nat-enb1m3-2","book":"Where is the station?","real":"Where's the station, mate?","meaning":"¿Dónde está la estación, tío?","when":"Entre hombres jóvenes, en la calle, y sobre todo si el otro es un desconocido de tu edad: «mate» ablanda la brusquedad de la pregunta directa. No lo digas en un mostrador, ni a alguien mayor, ni en el examen — allí lo que ablanda es la pregunta incrustada, no la palabra final.","register":"amigos","exam":"Could you tell me where the station is, please?","note":"Es el par que resume el módulo: la misma pregunta, dos mundos. «mate» funciona en Inglaterra y Australia; en Escocia oirás «pal», y en Irlanda «lad». Y ojo, «mate» no significa «compañero de piso»: eso es «flatmate».","sound":"uéas̬ de STÉI-shon, meit","level":"b1","produce":true,"itemId":"enb1m3natmate"},"lessonId":"enb1m3l4","level":"b1"},{"card":{"id":"nat-enb1m3-3","book":"She told me a secret.","real":"She let it slip.","meaning":"Se le escapó","when":"Contando algo que alguien dijo SIN QUERER: en el trabajo, entre amigos, sobre una sorpresa que se ha destripado. Lleva dentro que la persona no debía decirlo, así que no sirve para contar un secreto compartido a propósito. En el Writing formal no aparece.","register":"neutral","exam":"She mentioned it.","note":"«slip» es «resbalar»: la información se le escurrió. Su primo es «It slipped out», sin culpable. Y ojo con la versión de examen: «mentioned» no dice si fue queriendo o sin querer — es más pobre, pero es la que no te juega ninguna mala pasada de registro.","sound":"shi let it slip","level":"b1","produce":true,"itemId":"enb1m3natletitslip"},"lessonId":"enb1m3l6","level":"b1"},{"card":{"id":"nat-enb1m3-4","book":"What did you say?","real":"Sorry? Say that again?","meaning":"¿Cómo? ¿Me lo repites?","when":"En cualquier sitio y con casi cualquiera: «Sorry?» es LA forma británica de pedir que te repitan. Con amigos también «Say that again?». Lo que NO se dice a un desconocido es «What?» a secas — la traducción literal de «¿qué?» suena a mala gana.","register":"neutral","exam":"I beg your pardon? Could you repeat that, please?","note":"«Sorry?» con entonación ASCENDENTE es «¿cómo?»; con entonación descendente es «lo siento». La misma palabra, dos actos de habla, y lo único que los separa es la melodía. Es el mejor ejemplo de por qué el B1 trabaja el oído.","sound":"SÓ-ri · sei dat a-GUÉN","level":"b1","produce":true,"itemId":"enb1m3natsaythatagain"},"lessonId":"enb1m3l7","level":"b1"},{"card":{"id":"nat-enb1m4-1","book":"Someone stole my phone.","real":"My phone got nicked.","meaning":"Me han robado el móvil","when":"Contándoselo a alguien, en cualquier conversación. «nick» es robar en británico coloquial y se oye a todas horas. En una denuncia, en un correo al seguro o en el Writing del examen, NO: allí va «My phone was stolen».","register":"jerga","exam":"My phone was stolen.","note":"«got» en vez de «was» es lo que baja el registro; «nicked» en vez de «stolen» lo baja del todo. Son dos escalones, y puedes usar solo uno: «my phone got stolen» es el punto medio.","sound":"mai fóun got nikt","level":"b1","produce":true,"itemId":"enb1m4natnicked"},"lessonId":"enb1m4l4","level":"b1"},{"card":{"id":"nat-enb1m4-2","book":"I read it on the internet.","real":"I saw it online.","meaning":"Lo vi en internet","when":"Hablando, siempre. «On the internet» suena a manual de 2005; lo que se dice es «online», sin artículo y sin preposición delante. En un texto escrito de examen conviene decir además DE DÓNDE salía, que es lo que puntúa.","register":"neutral","exam":"According to an article I read, the pool is closing.","note":"El salto de banda no está en «online»: está en citar la fuente. «I saw it online» no informa a nadie; «according to an article I read» convierte el rumor en dato y sube el criterio de vocabulario.","sound":"ai soo it on-LÁIN","level":"b1","produce":true,"itemId":"enb1m4natsawitonline"},"lessonId":"enb1m4l5","level":"b1"},{"card":{"id":"nat-enb1m4-3","book":"It is said that the pool will close.","real":"They reckon it'll close.","meaning":"Dicen por ahí que va a cerrar","when":"Hablando, con quien sea: «reckon» es «creer, calcular» y en Inglaterra se dice a todas horas — «I reckon», «what do you reckon?». En el Writing formal NO: ahí va el molde con «It is said that…», que es lo que puntúa.","register":"amigos","exam":"It is believed that the pool will close.","note":"«They reckon» tiene sujeto y el sujeto es un «ellos» que no existe. Justo eso es lo que el molde de examen elimina: nadie dice quién, pero tampoco se inventa un «ellos».","sound":"dei RÉ-kon Í-tol klóus̬","level":"b1","produce":true,"itemId":"enb1m4natreckon"},"lessonId":"enb1m4l7","level":"b1"},{"card":{"id":"nat-enb1m4-4","book":"That is not true.","real":"That's rubbish.","meaning":"Eso es una tontería (literalmente «eso es basura»)","when":"Con amigos, en la cocina, en el pub. Es fuerte pero no grosero. Con tu jefa, en una reunión o por escrito, NO: ahí baja el registro de golpe y te deja como alguien que no sabe discutir.","register":"amigos","exam":"I don't think that's accurate.","note":"El inglés discrepa por abajo, no por arriba: «I'm not sure that's right», «I don't think that's accurate». Cuanto más fuerte es tu desacuerdo, más suave se pone la fórmula — al revés que en español.","sound":"dats RÁ-bish","level":"b1","produce":true,"itemId":"enb1m4natrubbish"},"lessonId":"enb1m4l8","level":"b1"},{"card":{"id":"nat-enb1m5-1","book":"I have no money.","real":"I'm skint.","meaning":"Estoy sin blanca","when":"Con amigos y compañeros, y siempre sobre algo pasajero: llegas justo a fin de mes, no a que seas pobre. Se dice muchísimo en todo el Reino Unido e Irlanda. En un correo de trabajo, en una reclamación o en el examen escrito no cabe: allí el dinero se nombra por lo que puedes o no puedes permitirte.","register":"amigos","exam":"I can't afford it at the moment.","note":"«broke» significa lo mismo y se entiende en todas partes; «skint» es más británico y suena más de barrio. Ojo con «I'm poor»: en inglés eso es una descripción de tu vida, no una queja del día 28.","sound":"aim skint","level":"b1","produce":true,"itemId":"enb1m5natskint"},"lessonId":"enb1m5l1","level":"b1"},{"card":{"id":"nat-enb1m5-2","book":"I want to complain.","real":"Can I have a word?","meaning":"¿Puedo hablar un momento contigo?","when":"Cara a cara y antes de que la cosa se ponga formal: al encargado del café, a un compañero, a un vecino. Avisa de que viene algo serio pero deja la puerta abierta. En un correo o en el Writing no cabe, y al escribirlo a un desconocido suena incluso amenazante.","register":"neutral","exam":"I'd like to make a complaint.","note":"Ojo con el tono: dicho suave es «oye, ¿te puedo comentar una cosa?»; dicho seco y con el ceño fruncido, en el Reino Unido es la antesala de una bronca. Y no es «una palabra»: «a word» aquí significa una conversación corta.","sound":"kan ai jav a ueed","level":"b1","produce":true,"itemId":"enb1m5natwordwith"},"lessonId":"enb1m5l4","level":"b1"},{"card":{"id":"nat-enb1m5-3","book":"It's very cheap.","real":"It's a bargain.","meaning":"Es una ganga","when":"Al enseñarle a alguien lo que has comprado, en el mercadillo, en las rebajas. Se dice con orgullo: quien lo dice está presumiendo un poco. También existe «It's a steal», más enfática y más informal. En una carta de reclamación o en un informe no cabe: allí un precio se comenta con «good value for money».","register":"neutral","exam":"It's very good value for money.","note":"Ojo con «cheap» a secas: en inglés arrastra la idea de «malo, de mala calidad» («cheap shoes»). Por eso el nativo dice «a bargain» —barato PARA lo que es— y en el examen se escribe «good value for money», que dice exactamente eso sin sonar a mercadillo.","sound":"its a BAA-guin","level":"b1","produce":true,"itemId":"enb1m5natbargain"},"lessonId":"enb1m5l6","level":"b1"},{"card":{"id":"nat-enb1m5-4","book":"We are saving money.","real":"We're putting a bit by.","meaning":"Vamos apartando algo cada mes","when":"En conversación, entre amigos o en familia, y siempre de un ahorro modesto y sin meta declarada: lo que se aparta «por si acaso». Es de las expresiones que dicen las personas mayores y que entiende todo el mundo. En un formulario del banco o en el Writing no cabe: allí se dice «save up».","register":"neutral","exam":"We're saving up.","note":"«put by» y «put aside» son lo mismo: apartar dinero. Ojo con el orden, porque lleva objeto en medio: «put a bit by», «put fifty pounds by». Y no lo confundas con «put off», que es aplazar.","sound":"uía PÚ-ting a bit bai","level":"b1","produce":true,"itemId":"enb1m5natputabitby"},"lessonId":"enb1m5l9","level":"b1"},{"card":{"id":"nat-enb1m6-1","book":"I am ill.","real":"I'm not feeling too great.","meaning":"No me encuentro muy allá","when":"Hablando, con quien sea. El británico casi nunca dice «I am ill» de sí mismo: suena grave y un poco dramático. Se quita hierro con una negación floja. En el Writing y en el Sprechen del examen, la versión sin adornos.","register":"neutral","exam":"I'm not feeling well.","note":"«too great» no significa «demasiado bien»: es el understatement británico, decir la mitad para que se entienda el doble. Cuanto peor está uno, más suave lo dice.","sound":"aim not FÍI-ling tuu gréit","level":"b1","produce":true,"itemId":"enb1m6natnottoogreat"},"lessonId":"enb1m6l1","level":"b1"},{"card":{"id":"nat-enb1m6-2","book":"I have a cold.","real":"I've come down with something.","meaning":"Me está entrando algo","when":"Hablando, y sobre todo al principio: cuando aún no sabes qué es. Sirve para avisar en el trabajo sin dar un parte médico. En cuanto ya sabes lo que tienes, se vuelve a «I've got a cold» — y en el examen, la versión completa.","register":"neutral","exam":"I think I'm coming down with a cold.","note":"«something» hace todo el trabajo: dice que hay síntomas y que aún no hay diagnóstico. Es la deducción de la lección 1 metida en una sola palabra.","sound":"aiv kam daun uid SÁM-zing","level":"b1","produce":true,"itemId":"enb1m6natcomedownwith"},"lessonId":"enb1m6l3","level":"b1"},{"card":{"id":"nat-enb1m6-3","book":"I have a doctor's appointment.","real":"I've got a GP appointment.","meaning":"Tengo cita con el médico de cabecera","when":"Avisando en el trabajo o quedando con alguien. En inglés británico lo normal es «I've got», no «I have», y el médico de cabecera es «the GP», no «the doctor», en cuanto hablas de una cita. En el examen escrito, la versión completa y sin siglas.","register":"neutral","exam":"I have an appointment with my doctor.","note":"«have got» no es más informal que «have»: es sencillamente lo que dice el británico. Lo que sí cambia el registro son las siglas — «GP» en una carta formal se explica la primera vez.","sound":"aiv got a dchii PÍI a-PÓINT-ment","level":"b1","produce":true,"itemId":"enb1m6natgpappointment"},"lessonId":"enb1m6l5","level":"b1"},{"card":{"id":"nat-enb1m6-4","book":"It isn't serious.","real":"It's nothing to worry about.","meaning":"No es nada preocupante","when":"Es lo que dice un médico, una enfermera o un amigo para tranquilizar. «It isn't serious» es correcto pero suena a informe; la versión real mira a la persona, no al diagnóstico. En el Writing formal, la corta y neutra.","register":"neutral","exam":"It's not serious.","note":"Fíjate en que el inglés tranquiliza en negativo y con un sustantivo vacío: «nothing to worry about». En español haríamos «no te preocupes», con imperativo — y el imperativo inglés ahí sonaría a orden.","sound":"its NÁ-zing tu UÓ-ri a-báut","level":"b1","produce":true,"itemId":"enb1m6natnothingtoworry"},"lessonId":"enb1m6l7","level":"b1"},{"card":{"id":"nat-enb1m7-1","book":"Yes, it's a small kitchen.","real":"Aye, it's a wee kitchen.","meaning":"Sí, es una cocina pequeña.","when":"En Escocia y en el norte de Irlanda, en cualquier registro hablado: «aye» y «wee» no son argot juvenil, los dice todo el mundo y salen impresos en la prensa local. Fuera de allí no se usan, y en un examen internacional tampoco.","register":"regional","exam":"Yes, it's quite a small kitchen.","note":"«wee» va delante del sustantivo como cualquier adjetivo («a wee bit», «a wee minute») y suaviza además de empequeñecer: «a wee problem» es «un problemilla». «Aye» es simplemente «yes» — hasta el Parlamento británico vota diciendo «the ayes have it».","sound":"ai, its a uíi KÍ-chen","level":"b1","produce":false,"itemId":"enb1m7nataye"},"lessonId":"enb1m7l1","level":"b1"},{"card":{"id":"nat-enb1m7-3","book":"I took the lift up to my flat in autumn.","real":"I took the elevator up to my apartment in the fall.","meaning":"Subí en ascensor a mi piso, en otoño.","when":"La columna de la derecha es lo normal en Estados Unidos y Canadá, y lo vas a leer y oír todos los días en internet. Fuera de Norteamérica no se usa, y en tu examen —británico— tampoco.","register":"regional","exam":"In autumn I went up to the flat in the lift.","note":"Lo que puntúa aquí no es cuál eliges: es no mezclarlas. Un texto con «lift» y «apartment» en la misma línea no es de ningún país, y el criterio de vocabulario lo nota. Elige una variedad al empezar el examen y no la sueltes.","sound":"ai tuk di É-le-vei-ta ap tu mai a-PAAT-ment in de fool","level":"b1","produce":false,"itemId":"enb1m7natelevator"},"lessonId":"enb1m7l4","level":"b1"},{"card":{"id":"nat-enb1m7-2","book":"How are things?","real":"What's the craic?","meaning":"¿Qué tal? ¿Qué se cuenta?","when":"En Irlanda, entre gente que ya se conoce: es el saludo informal por defecto, no una pregunta sobre nada en concreto. Fuera de Irlanda casi nadie lo dice, y en un examen no cabe: allí se saluda con la fórmula neutra.","register":"regional","exam":"How's everything going?","note":"«craic» se pronuncia igual que «crack» y significa el ambiente, la conversación, lo que se cuenta. «It was great craic» = «estuvo genial». Se escribe con esa ortografía irlandesa, y verla escrita de otra manera suele ser señal de que quien lo escribe no es de allí.","sound":"uots de krak","level":"b1","produce":false,"itemId":"enb1m7natcraic"},"lessonId":"enb1m7l5","level":"b1"},{"card":{"id":"nat-enb1m7-4","book":"Please deal with this.","real":"Please do the needful.","meaning":"Haga lo que haga falta.","when":"En correos de trabajo en la India y en buena parte del sur de Asia: es una fórmula de cierre normal y educada, ni antigua ni graciosa. Fuera de allí no se usa, y en tu examen tampoco.","register":"regional","exam":"Please could you deal with this?","note":"El inglés de la India es lengua propia de más gente que el de Reino Unido y Australia juntos, así que esto no es una curiosidad: es una de las variedades que más vas a leer en un correo de trabajo. «Revert» por «contestar» y «prepone» —lo contrario de «postpone»— vienen del mismo sitio y son igual de correctos allí.","sound":"plíis̬ du de NÍID-ful","level":"b1","produce":false,"itemId":"enb1m7natneedful"},"lessonId":"enb1m7l8","level":"b1"},{"card":{"id":"nat-enb1m8-1","book":"much more expensive","real":"way more expensive","meaning":"muchísimo más caro","when":"Hablando, con cualquiera menos con un tribunal: «way» es el matizador de la calle y se oye a todas horas (way better, way too much, way more). En el Writing NO se escribe: en un texto formal baja el registro y el criterio de vocabulario lo nota.","register":"neutral","exam":"considerably more expensive","note":"«way» viene de «a long way» — «un largo trecho más caro». Por eso no admite matices: o es mucho, o no se usa «way».","sound":"uéi moo iks-PÉN-siv","level":"b1","produce":true,"itemId":"enb1m8natwaymore"},"lessonId":"enb1m8l1","level":"b1"},{"card":{"id":"nat-enb1m8-2","book":"second-hand","real":"pre-loved / from a charity shop","meaning":"de segunda mano","when":"«Pre-loved» lo usan las tiendas y la gente joven vendiendo por internet: suena a mimo, no a pobreza. «From a charity shop» es lo que dice cualquiera hablando de su chaqueta, y en Reino Unido no tiene ninguna connotación mala. En el Writing, en cambio, se escribe «second-hand» y punto: es lo neutro y no hay que explicarlo.","register":"neutral","exam":"second-hand","note":"«Pre-loved» nació como eufemismo comercial y se quedó porque funciona: «second-hand» describe el objeto, «pre-loved» describe que alguien lo quiso antes. Ojo con calcarlo al español: «pre-amado» no existe.","sound":"prii-LÁVD / from a CHÁ-ri-ti shop","level":"b1","produce":true,"itemId":"enb1m8natpreloved"},"lessonId":"enb1m8l6","level":"b1"},{"card":{"id":"nat-enb1m8-3","book":"It isn't very good.","real":"It's not great, is it?","meaning":"No es gran cosa, ¿verdad?","when":"Hablando, con cualquiera. Es el understatement británico: se dice mucho menos de lo que se piensa y se espera que el otro entienda el resto. «It's not great» casi nunca significa «es regular»: significa «es malo». Y la coletilla «is it?», con la voz BAJANDO, no pregunta — invita a que estés de acuerdo. En el Writing esto no se escribe: allí hay que decir el nivel de crítica que de verdad quieres decir.","register":"neutral","exam":"It leaves something to be desired.","note":"La escala completa, de peor a mejor, para que no te la juegues: «it's not great» (malo) < «it's not bad» (bastante bueno) < «it's quite good» (bueno) < «it's not bad at all» (muy bueno). El inglés británico dice las cosas malas hacia arriba y las buenas hacia abajo.","sound":"its not gréit, is̬ it","level":"b1","produce":true,"itemId":"enb1m8natnotgreat"},"lessonId":"enb1m8l7","level":"b1"},{"card":{"id":"nat-enb1m8-4","book":"I agree.","real":"Fair enough. / You've got a point.","meaning":"Vale, tienes razón / algo de razón tienes","when":"Hablando, con cualquiera. «Fair enough» acepta y cierra el tema —es lo que dices cuando dejas de discutir sin darle del todo la razón al otro—, y «You've got a point» concede a medias y te deja seguir hablando. En el Writing formal no se escriben: allí va la versión larga, que además suena a que has pensado la respuesta.","register":"amigos","exam":"I couldn't agree more.","note":"«Fair enough» es literalmente «bastante justo», y ahí está todo: no dices que el otro tenga razón, dices que lo que ha dicho es razonable. Por eso sirve para cerrar una discusión sin que nadie pierda. Ojo con no confundirla con «I take your point, but…», que verás más adelante en este mismo módulo: esa concede y GIRA hacia un desacuerdo — no es un sinónimo de acuerdo.","sound":"féa i-NÁF / yuv got a póint","level":"b1","produce":true,"itemId":"enb1m8natfairenough"},"lessonId":"enb1m8l8","level":"b1"},{"card":{"id":"nat-enb1m9-1","book":"The train is late.","real":"The train's been delayed again.","meaning":"Otra vez el tren con retraso","when":"Hablando, en el andén o por mensaje. El británico rara vez dice «the train is late» de un servicio: dice que lo han retrasado, en pasiva y con «again» aunque sea la primera vez. Es queja educada, no información. En el Writing y en el Speaking del examen, la versión completa y sin «again».","register":"neutral","exam":"The train has been delayed.","note":"La pasiva no es adorno: «is late» culpa al tren y «has been delayed» culpa a quien lo gestiona. El «again» es el que lleva la queja, y por eso se dice en un tono plano, casi resignado.","sound":"de tréins̬ bin di-LÉID a-GUÉN","level":"b1","produce":true,"itemId":"enb1m9natdelayedagain"},"lessonId":"enb1m9l1","level":"b1"},{"card":{"id":"nat-enb1m9-2","book":"Hurry up!","real":"We'd better get a move on.","meaning":"Habría que ir moviéndose","when":"Hablando, con gente de confianza y también con compañeros de trabajo. «Hurry up!» es una orden y solo se le dice a un niño o a alguien con quien tienes mucha confianza; el adulto británico mete prisa incluyéndose («we») y en condicional («we'd better»). En el Speaking del examen, la versión neutra.","register":"amigos","exam":"We should hurry.","note":"Fíjate en el «we»: aunque el lento seas tú, quien lo dice se mete dentro. Es la misma cortesía que hace que un jefe británico diga «shall we make a start?» en vez de «start».","sound":"uid BÉ-ta guet a múuv on","level":"b1","produce":true,"itemId":"enb1m9natgetamoveon"},"lessonId":"enb1m9l3","level":"b1"},{"card":{"id":"nat-enb1m9-3","book":"Where is gate 12?","real":"Which way's gate twelve?","meaning":"¿Por dónde se va a la doce?","when":"Hablando, a alguien de uniforme o a otro pasajero, cuando lo que quieres no es la ubicación exacta sino la dirección. Se usa muchísimo en aeropuertos y estaciones grandes. En el Speaking del examen, la pregunta indirecta completa: es la que sube la banda de gramática.","register":"neutral","exam":"Excuse me, could you tell me where gate 12 is?","note":"«Which way» pregunta por la dirección, no por el sitio: la respuesta que espera es «left at the end» o «keep going». Y fíjate en el número dicho en letra, «twelve»: en los avisos y hablando, las puertas y los andenes se dicen, no se deletrean.","sound":"uich uéis̬ guéit tuélv","level":"b1","produce":true,"itemId":"enb1m9natwhichwaysgate"},"lessonId":"enb1m9l6","level":"b1"},{"card":{"id":"nat-enb1m9-4","book":"The journey takes two hours.","real":"It's a couple of hours.","meaning":"Son un par de horas","when":"Hablando, siempre que no te pidan una cifra exacta. Lo normal en inglés británico es redondear y suavizar: «a couple of», «about», «or so». Dar el minuto exacto suena a que estás leyendo el horario. En el Writing del examen, la versión con «approximately».","register":"neutral","exam":"The journey takes approximately two hours.","note":"«A couple of» significa dos, pero en la práctica es «dos o tres»: nadie te va a corregir si son dos horas y veinte. Y ojo, el «of» no se puede quitar: «a couple hours» es americano.","sound":"its a KÁ-pel ov ÁUAS̬","level":"b1","produce":true,"itemId":"enb1m9natcoupleofhours"},"lessonId":"enb1m9l9","level":"b1"},{"card":{"id":"nat-enb1m10-1","book":"We are friends.","real":"We get on really well.","meaning":"Nos llevamos genial","when":"Hablando, con cualquiera. Cuando alguien te pregunta por una persona, el británico no contesta con la etiqueta de la relación, contesta con cómo funciona. Para el Writing y el Speaking del examen vale la misma idea, un punto más neutra.","register":"neutral","exam":"We get on well together.","note":"«Really» aquí no es «realmente»: es el intensificador de todos los días, el equivalente de «genial» o «muy bien». Sin él, «we get on well» suena correcto pero tibio.","sound":"ui guet on RÍA-li uel","level":"b1","produce":true,"itemId":"enb1m10getonreallywell"},"lessonId":"enb1m10l2","level":"b1"},{"card":{"id":"nat-enb1m10-2","book":"We argued.","real":"We had a bit of a falling-out.","meaning":"Tuvimos nuestro más y nuestro menos","when":"Contando algo a alguien de confianza, y casi siempre para quitarle hierro a una bronca que fue bastante seria. En el Writing y en el Speaking del examen, la versión neutra y sin atenuador.","register":"neutral","exam":"We had a disagreement.","note":"«A bit of a» no significa «un poco»: es el atenuador británico. Cuanto más se atenúa, más gorda fue la cosa — un año sin hablarse cabe perfectamente aquí dentro.","sound":"ui jad a bit ov a FÓO-ling áut","level":"b1","produce":true,"itemId":"enb1m10natfallingout"},"lessonId":"enb1m10l5","level":"b1"},{"card":{"id":"nat-enb1m10-3","book":"I am sorry.","real":"Sorry about that.","meaning":"Perdona, lo siento (por algo pequeño y ya pasado)","when":"Hablando, con cualquiera, y para cosas pequeñas: un retraso, un despiste, un pisotón. Para algo serio hace falta subir de escalón. Y en una carta formal del examen, la fórmula entera.","register":"neutral","exam":"I would like to apologise for the delay.","note":"El sujeto y el verbo se caen enteros: nadie dice «I am sorry about that» en una situación menor. Dicho completo, suena a que la cosa fue grave.","sound":"SO-ri a-báut dat","level":"b1","produce":true,"itemId":"enb1m10natsorryaboutthat"},"lessonId":"enb1m10l9","level":"b1"},{"card":{"id":"nat-enb1m10-4","book":"I miss you.","real":"I miss you loads.","meaning":"Te echo muchísimo de menos","when":"Por escrito y hablando, con gente de confianza: familia, amigos de verdad, pareja. Es la despedida de una carta informal, no de un correo de trabajo. En el examen, la versión con «very much».","register":"amigos","exam":"I miss you very much.","note":"«Loads» es «un montón», y de tanto usarse ha perdido lo exagerado: hoy es el intensificador normal entre amigos, por delante de «a lot». «Very much» es correcto y suena a carta de otra época.","sound":"ai mis yu lóuds̬","level":"b1","produce":true,"itemId":"enb1m10natmissyouloads"},"lessonId":"enb1m10l10","level":"b1"},{"card":{"id":"nat-enb1m11-1","book":"It is not allowed.","real":"You're not meant to.","meaning":"No se puede / se supone que no","when":"Hablando, con cualquiera, y sobre todo cuando NO quieres sonar a autoridad: al vecino, al compañero de trabajo, al amigo que va a aparcar donde no debe. En un cartel o en un reglamento no aparece jamás. En el Writing formal y en el Spoken del examen, la versión de la derecha.","register":"neutral","exam":"It is not permitted.","note":"«Meant to» le echa la culpa a la norma y no a la persona: por eso se puede decir sin que nadie se ofenda. Es la misma jugada que hace el británico con «I'm afraid» — poner un colchón delante del mensaje.","sound":"yoo not MEN-tu","level":"b1","produce":true,"itemId":"enb1m11natnotmeantto"},"lessonId":"enb1m11l3","level":"b1"},{"card":{"id":"nat-enb1m11-2","book":"That's not fair.","real":"That's a bit out of order.","meaning":"Eso está feo / eso no se hace","when":"Hablando, entre iguales: con amigos, con vecinos, con compañeros de trabajo. Es más fuerte de lo que parece — «a bit» no lo suaviza, lo enmascara. Con un jefe o en un escrito, no. En el examen, la versión de la derecha, que es la que se puede defender delante de cualquiera.","register":"amigos","exam":"I don't think that's fair.","note":"«Out of order» de una máquina es «averiada»; de una persona es «se ha pasado». El británico casi nunca dice «that's not fair» de adulto: suena a patio de colegio.","sound":"dats a bit áut ov ÓO-da","level":"b1","produce":true,"itemId":"enb1m11natoutoforder"},"lessonId":"enb1m11l7","level":"b1"},{"card":{"id":"nat-enb1m11-3","book":"I disagree.","real":"I'm not so sure about that.","meaning":"No lo tengo yo tan claro","when":"En cualquier discusión hablada: reunión de vecinos, trabajo, café. Es la forma normal de decir que no sin cerrar la puerta — de hecho invita al otro a explicarse. En el Writing formal y en el Spoken del examen, la versión de la derecha, que es un no claro y perfectamente educado.","register":"neutral","exam":"I'm afraid I disagree.","note":"El británico casi nunca discrepa de frente: primero reconoce algo («that's a good point»), luego amortigua y solo entonces da su razón. Saltarse los dos primeros pasos no es más eficaz: es más difícil de escuchar.","sound":"aim not sóu shóo a-báut dat","level":"b1","produce":true,"itemId":"enb1m11natnotsosure"},"lessonId":"enb1m11l8","level":"b1"},{"card":{"id":"nat-enb1m11-4","book":"I want to complain.","real":"I want to have a word with someone.","meaning":"Quiero hablar con alguien de esto (algo no va bien)","when":"Hablando, y sobre todo cuando la cosa aún se puede arreglar sin papeles: con el casero, con el encargado, con un compañero. «Can I have a word?» a solas es el arranque británico de toda conversación incómoda. En cuanto la cosa va por escrito, la versión de la derecha.","register":"neutral","exam":"I'd like to make a formal complaint.","note":"«Have a word» suena a charla y no lo es: todo el mundo entiende que algo va mal. Es el mismo mecanismo de siempre — decir la mitad para que se entienda el doble.","sound":"ai uónt tu jav a uéed uid SÁM-uan","level":"b1","produce":true,"itemId":"enb1m11nathaveaword"},"lessonId":"enb1m11l9","level":"b1"},{"card":{"id":"nat-enb1m12-1","book":"Let me think.","real":"Hang on, let me think.","meaning":"Espera, déjame pensar","when":"En el oral, cuando la pregunta te pilla en blanco. Sirve en las cuatro partes y con cualquier interlocutor: es informal pero no descuidado. Lo que NO puedes hacer es callarte tres segundos, porque el silencio se oye en la grabación y la fluidez es un criterio entero de los cuatro.","register":"neutral","exam":"That's an interesting question. Let me think for a moment.","note":"«Hang on» es literalmente «agárrate», y aquí significa «un momento». Pedir tiempo EN INGLÉS suma; quedarte callado o decir «eeeh» a la española, no. La versión de examen es más larga a propósito: mientras la dices, ya estás pensando.","sound":"jang on, let mi zink","level":"b1","produce":true,"itemId":"enb1m12nathangon"},"lessonId":"enb1m12l1","level":"b1"},{"card":{"id":"nat-enb1m12-2","book":"I mean…","real":"Well, what I mean is…","meaning":"Bueno, lo que quiero decir es…","when":"Cuando has empezado una frase y se te ha torcido. Sirve en las cuatro partes del oral y también en la vida: es la manera inglesa de <b>autocorregirse sin disculparse</b>. Lo que NO se hace es parar, decir «sorry, sorry» y empezar de cero: eso son tres segundos de grabación tirados y el examinador solo oye el titubeo.","register":"neutral","exam":"Or rather… What I meant to say is…","note":"El descriptor oficial del B1 asume que vas a titubear: «pausing for grammatical and lexical planning and repair is very evident». O sea, que reparar sobre la marcha ES el nivel — pero hay que reparar EN INGLÉS. «Well, what I mean is…» te compra dos segundos y suena a hablante, no a examinando.","sound":"uel, uot ai miin is̬","level":"b1","produce":true,"itemId":"enb1m12natwhatimeanis"},"lessonId":"enb1m12l8","level":"b1"},{"card":{"id":"nat-enb1m12-3","book":"You mean…?","real":"So you're saying…?","meaning":"O sea, que dices que… ¿no?","when":"En la Parte 3, cuando quieres confirmar lo que ha propuesto el otro antes de aceptar o discrepar. Vale con cualquiera y en cualquier registro. Lo que NO hace es rellenar: si lo usas cada dos frases, suena a que no te enteras de nada.","register":"neutral","exam":"So, if I understand correctly, you're saying that…","note":"Esta fórmula está en el descriptor oficial del B1 —«can repeat back part of what someone has said to confirm mutual understanding»—, así que no es un truco de examen: es el nivel. Y de propina te compra dos segundos de pensar mientras la dices.","sound":"sóu yoo SÉI-ing","level":"b1","produce":true,"itemId":"enb1m12natsoyouresaying"},"lessonId":"enb1m12l9","level":"b1"},{"card":{"id":"nat-enb1m12-4","book":"That is all.","real":"Yeah, that's about it.","meaning":"Sí, eso es más o menos todo.","when":"Para cerrar tu minuto y medio de monólogo cuando ya has dicho lo que tenías. Es mil veces mejor que quedarse callado o que decir «finish»: suena a que has terminado porque querías, no porque te has quedado en blanco.","register":"neutral","exam":"And that's everything I wanted to say.","note":"El examinador no penaliza que acabes antes de los noventa segundos; penaliza que te apagues. Un cierre dicho a propósito convierte un monólogo corto en un monólogo completo.","sound":"yea, dats a-BÁUT it","level":"b1","produce":true,"itemId":"enb1m12natthatsaboutit"},"lessonId":"enb1m12l10","level":"b1"},{"card":{"id":"nat-enb2m1-1","book":"In conclusion","real":"So yeah, basically.","meaning":"En conclusión / Bueno, total, que…","when":"El cierre hablado de una explicación, con amigos o con Amy en la cocina. En un Writing de examen no se escribe jamás: allí el cierre es In conclusion o All things considered. Al revés tampoco: nadie dice «in conclusion» al levantarse del sofá.","register":"amigos","exam":"In conclusion, the first draft did not work.","note":"«Basically» no significa «básicamente» de manual: significa «te lo resumo». Quien lo escribe en un informe suena a que no ha terminado de pensar.","sound":"sóu yeah, BÉI-si-kli","level":"b2","produce":true,"itemId":"enb2m1natinconclusion"},"lessonId":"enb2m1l1","level":"b2"},{"card":{"id":"nat-enb2m1-3","book":"The reason is that","real":"The thing is, I haven't got time.","meaning":"La razón es que / Es que no tengo tiempo","when":"Para poner el foco en lo que importa, en una conversación. Con Amy, con Sam, con Ben. En el Writing formal se escribe The reason for this is that o The problem is that. «The thing is» en un informe baja el criterio de vocabulario por registro.","register":"neutral","exam":"The reason for this is that the first line buried the request.","note":"La coma detrás de «The thing is» es de habla. En el examen, si usas The problem is that, la coma no va: that ya abre la subordinada.","sound":"de zing is̬, ai JÁ-vent got taim","level":"b2","produce":true,"itemId":"enb2m1natthethingis"},"lessonId":"enb2m1l3","level":"b2"},{"card":{"id":"nat-enb2m1-2","book":"However","real":"But then again.","meaning":"Sin embargo / Aunque, por otra parte…","when":"Contraste de charla, cuando le das la vuelta a lo que acabas de conceder. Con amigos. En el Writing, Nevertheless o That said. However —que es A2— sigue valiendo por escrito; But then again, no.","register":"amigos","exam":"Nevertheless, the first draft was worth rewriting.","note":"«Then again» y «but then again» son la misma pieza. El however del libro ya lo tenías; lo nuevo es no usarlo en voz alta como si hablaras con un tribunal.","sound":"bat den a-GHÉN","level":"b2","produce":true,"itemId":"enb2m1natbutthenagain"},"lessonId":"enb2m1l5","level":"b2"},{"card":{"id":"nat-enb2m1-4","book":"Furthermore","real":"And another thing.","meaning":"Además / Y otra cosa","when":"Para sumar un punto en una discusión de cocina o de rellano. Con Nora, con Ben, con Sam. En un informe o en el Writing 1, Moreover o What is more. «And another thing» en un ensayo baja el registro; «furthermore» en el pub lo sube de más.","register":"amigos","exam":"What is more, the ending repeats the opening.","note":"Furthermore y moreover son la misma altura formal. What's more es la de en medio. And another thing es la de la calle. Tres trajes, una función: sumar.","sound":"and a-NÁ-dha zing","level":"b2","produce":true,"itemId":"enb2m1natanotherthing"},"lessonId":"enb2m1l9","level":"b2"},{"card":{"id":"nat-enb2m2-2","book":"increase","real":"The rent's gone up again.","meaning":"subir / un aumento","when":"El verbo de la calle, con Ben en el autobús o con Amy en la cocina. En un informe o en la Writing 1, a rise in / an increase in. «Gone up» en una carta a la agencia baja el registro; «an increase in» en el pub lo sube de más.","register":"neutral","exam":"There has been a rise in overtime this month.","note":"Tres alturas de la misma subida: go up (calle) · increase (verbo neutro) · a rise in / an increase in (nombre de informe). El módulo entrena subir y bajar a voluntad.","sound":"de rents gon ap a-GHÉN","level":"b2","produce":true,"itemId":"enb2m2natgoup"},"lessonId":"enb2m2l1","level":"b2"},{"card":{"id":"nat-enb2m2-1","book":"I would like to apply for","real":"I'm after that job.","meaning":"Quiero ese puesto / Voy a por ese trabajo","when":"Con Sam, con Amy, con Ben, cuando el puesto es una noticia de café. En la Writing 1, I am writing to apply for. «I'm after that job» en una carta a Nadia tumba el registro; «I am writing to apply» en el pub suena a otra persona.","register":"amigos","exam":"I am writing to apply for the afternoon post.","note":"«After» aquí no es «después»: es «a por». La pieza se oye mucho en británico hablado y no se escribe en un informe.","sound":"aim AAF-ta dat dchob","level":"b2","produce":true,"itemId":"enb2m2natafterthatjob"},"lessonId":"enb2m2l4","level":"b2"},{"card":{"id":"nat-enb2m2-3","book":"a lot of money","real":"It cost a fortune.","meaning":"mucho dinero / un dineral","when":"Quejándote de un precio de verdad —el alquiler, un curso, una reparación—, con Amy o con Ben. En un informe o en la Writing 1, a considerable sum. «A fortune» en una carta a Nadia baja el registro; «a considerable sum» en el pub lo sube de más.","register":"amigos","exam":"The overtime comes to a considerable sum.","note":"Fortune no es siempre literalmente una fortuna: es la queja. En el examen, considerable sum hace el mismo trabajo sin la queja.","sound":"it kost a FÓO-chun","level":"b2","produce":true,"itemId":"enb2m2natafortune"},"lessonId":"enb2m2l9","level":"b2"},{"card":{"id":"nat-enb2m2-4","book":"I want to know","real":"Any chance you could tell me the hours?","meaning":"Quiero saber / ¿Hay alguna posibilidad de que me digas el horario?","when":"Para pedir una cifra o una hora a un igual —Sam, Amy, Ben. En la Writing 1, I would be grateful if you could confirm. «Any chance» en una carta a Nadia es un tono de pasillo; «I want to know» es peor: es una exigencia.","register":"neutral","exam":"I would be grateful if you could confirm the hours.","note":"Tres alturas de la misma pregunta: I want to know (brusco) · any chance you could (calle educada) · I would be grateful if you could (examen). El módulo entrena elegir la altura, no memorizar una.","sound":"É-ni chaans yu kud tel mi di ÁUas̬","level":"b2","produce":true,"itemId":"enb2m2natanychance"},"lessonId":"enb2m2l10","level":"b2"},{"card":{"id":"nat-enb2m3-1","book":"I am not satisfied","real":"This is a joke.","meaning":"No estoy satisfecha / Esto es un chiste","when":"La queja a un igual, en casa, cuando el cargo es un insulto. Con Amy. Al banco y en el Writing, I am far from satisfied with. «This is a joke» en una carta tumba el registro; «I am not satisfied» en la cocina suena a tribunal.","register":"amigos","exam":"I am far from satisfied with the response.","note":"Tres alturas de la misma queja: this is a joke (calle) · I am not satisfied (manual) · I am far from satisfied with (examen). El módulo es elegir la altura, no memorizar una.","sound":"dhis is̬ a dchóuk","level":"b2","produce":true,"itemId":"enb2m3natjoke"},"lessonId":"enb2m3l1","level":"b2"},{"card":{"id":"nat-enb2m3-2","book":"Could you help me?","real":"Any chance you could help me with this?","meaning":"¿Podrías ayudarme?","when":"Petición a un igual. Con Amy, con Sam, con Ben. Al banco y en el oral de examen, I would appreciate it if you could. «Any chance» en una carta formal es pasillo; «Could you help me?» a un extraño, sin please, se queda corto.","register":"neutral","exam":"I would appreciate it if you could look at this.","note":"Any chance se come el verbo auxiliar y suena a cocina británica. En el Part 2 del oral, con un interlocutor que hace de vecino, sí; con uno que hace de jefe, no.","sound":"É-ni chaans yu kud help mi uid dhis","level":"b2","produce":true,"itemId":"enb2m3natanychancehelp"},"lessonId":"enb2m3l2","level":"b2"},{"card":{"id":"nat-enb2m3-3","book":"That is not correct","real":"That's not right, is it?","meaning":"Eso no es correcto / Eso no está bien, ¿verdad?","when":"Contradecir a un igual sin pelea. Con Amy, con el operador si el tono lo aguanta. En el Writing y en el Part 2 con un jefe, I am afraid that is not quite accurate. El tag is it? es el hueco que dejas para que el otro no pierda la cara.","register":"neutral","exam":"I am afraid that is not quite accurate.","note":"El tag no pregunta. Envuelve. Sin él, That's not right suena a acusación; con él, a duda compartida. Esa es la diferencia que el oral marca.","sound":"dhats not rait, is̬ it","level":"b2","produce":true,"itemId":"enb2m3natnotright"},"lessonId":"enb2m3l5","level":"b2"},{"card":{"id":"nat-enb2m3-4","book":"Yes, I agree","real":"Yeah, fair enough.","meaning":"Sí, estoy de acuerdo / Vale, de acuerdo","when":"Conceder a un igual, cuando te han pillado un punto. Con Amy, con Ben, con el operador si el tono lo aguanta. En el examen, I take your point, although… Yes, I agree se queda corto: no deja hueco para el but, y el B2 puntúa la concesión, no el sí pelado.","register":"amigos","exam":"I take your point, although the charge still stands.","note":"Fair enough no es «justo de precio»: es «me has convencido, en parte». Sin el although posterior, en un Writing, parece que has cambiado de bando.","sound":"yeah, fee ÁU-naf","level":"b2","produce":true,"itemId":"enb2m3natfairenough"},"lessonId":"enb2m3l9","level":"b2"},{"card":{"id":"nat-enb2m4-1","book":"People say that","real":"Apparently it's shutting.","meaning":"Dicen que / Por lo visto cierra","when":"Rumor de rellano, con Amy, con Nora, con Sam. En un artículo o en el Writing, It is widely believed that. Apparently en un informe suena a pasillo; People say en un titular, a que no tienes fuente.","register":"neutral","exam":"It is widely believed that the shop will close.","note":"Apparently se come el dueño entero. Es la calle honesta: no sé quién lo ha dicho. Widely believed finge que lo sabe mucha gente. Elegir entre las dos es el registro, no la gramática.","sound":"a-PÁ-rent-li its SHÁ-ting","level":"b2","produce":true,"itemId":"enb2m4natapparently"},"lessonId":"enb2m4l1","level":"b2"},{"card":{"id":"nat-enb2m4-2","book":"They cancelled it","real":"It got cancelled last night.","meaning":"Lo cancelaron / Se canceló anoche","when":"La pasiva con get, que es la de la calle: un tren, un turno, una cita. En un artículo, It was cancelled. They cancelled it es el manual, y suena a que tienes un they. Get es lo que dice Ben del 55 cuando lo quitan.","register":"neutral","exam":"It was cancelled.","note":"Get-passive no es vulgar: es hablada. En el Writing formal, was. En el Part 4 del oral, got puntúa como rango si el tema es de la calle.","sound":"it got KÁN-sld laast nait","level":"b2","produce":true,"itemId":"enb2m4natgotcancelled"},"lessonId":"enb2m4l3","level":"b2"},{"card":{"id":"nat-enb2m4-3","book":"The report says","real":"Word is they're cutting it.","meaning":"El informe dice / Se rumorea que lo van a recortar","when":"Rumor de parada de autobús, de rellano, de café. En un artículo, According to the report / The council says. Word is en un Writing formal es pasillo; The report says en el 55 suena a que llevas el Gazette encima.","register":"amigos","exam":"According to the report, the night bus will be cut.","note":"Word is se come until y that. Es una pieza, no una frase. According to the report no se come nada: la fuente va escrita.","sound":"ueed is̬ déa KÁ-ting it","level":"b2","produce":true,"itemId":"enb2m4natwordis"},"lessonId":"enb2m4l7","level":"b2"},{"card":{"id":"nat-enb2m4-4","book":"It is not true","real":"That's rubbish.","meaning":"No es verdad / Eso es basura","when":"Desmentir en la cocina o en el 55, con Amy o con Ben. En un artículo, These claims have been denied. That's rubbish en un Writing formal tumba el registro; It is not true en el rellano suena a tribunal.","register":"amigos","exam":"These claims have been denied.","note":"That's rubbish ya era tarjeta Nativo del B1 (prensa). Aquí no se redeclarar: se recicla el id enb1m4natrubbish y se le pone al lado el molde de examen que el B1 no exigía todavía. Una palabra, una tarjeta. El progreso viaja.","sound":"dhats RÁ-bish","level":"b2","produce":true,"itemId":"enb1m4natrubbish"},"lessonId":"enb2m4l9","level":"b2"},{"card":{"id":"nat-enb2m5-1","book":"It is probable that","real":"Odds are","meaning":"Lo más seguro es que… / Hay muchas papeletas de que…","when":"Con amigos, al vaticinar algo cotidiano: que llegue tarde, que llueva, que el autobús no venga. En un informe, en una reclamación o en el Writing del examen no cabe: allí la misma altura se dice «It is highly likely that».","register":"amigos","exam":"It is highly likely that","note":"«Odds» son las cuotas de una apuesta. Quien ignore la raya de Odds are y ponga «It is probable that» en una caña no pasa nada; quien ponga «Odds are» en el informe le baja la banda de registro.","sound":"ods aa","level":"b2","produce":true,"itemId":"enb2m5natoddsare"},"lessonId":"enb2m5l1","level":"b2"},{"card":{"id":"nat-enb2m5-2","book":"It must be true","real":"It's got to be","meaning":"Tiene que ser eso / no hay otra lectura","when":"Con amigos, cuando ya no te cabe otra explicación. En el informe y en el examen escrito, la misma certeza se dice con evidencia: «The evidence strongly suggests». «It's got to be» en un Writing Part 1 te baja el criterio de vocabulario por registro.","register":"amigos","exam":"The evidence strongly suggests","note":"«Have got to» de obligación ya lo tienes de A2. Aquí no obliga: deduce. El oído no distingue las dos; el contexto sí.","sound":"its got tu bi","level":"b2","produce":true,"itemId":"enb2m5natgottobe"},"lessonId":"enb2m5l2","level":"b2"},{"card":{"id":"nat-enb2m5-3","book":"It is supposed to be good","real":"It's meant to be great","meaning":"Dicen que está genial / se supone que merece la pena","when":"Al recomendar un sitio, una serie, un restaurante, sin haber ido. Es rumor con ganas. En el Writing, la misma frase se pone en formal: «It is said to be». No la uses para una norma («You're meant to submit the form» vale en la calle; en un reglamento, «You are required to»).","register":"amigos","exam":"It is said to be","note":"«Meant to» y «supposed to» de rumor son intercambiables en conversación. El examen las acepta las dos. «Reputed to» lo vas a leer; no hace falta producirlo.","sound":"its ment tu bi greit","level":"b2","produce":true,"itemId":"enb2m5natmeanttobegreat"},"lessonId":"enb2m5l3","level":"b2"},{"card":{"id":"nat-enb2m5-4","book":"I don't know","real":"Search me","meaning":"Ni idea / no me preguntes a mí","when":"Con amigos, cuando de verdad no sabes y no te da vergüenza. En el informe y en el Speaking del examen, la misma ignorancia se dice «There is no conclusive evidence» o «I have no data on that». «Search me» en un Writing 1 es un error de registro, no de sinceridad.","register":"amigos","exam":"There is no conclusive evidence","note":"La broma vieja es «búscame a mí»: si la respuesta estuviera en algún sitio, estaría en mi persona, y no está. Quien ignore la raya seguirá leyendo una s, que es el error de partida.","sound":"séech mi","level":"b2","produce":true,"itemId":"enb2m5natsearchme"},"lessonId":"enb2m5l9","level":"b2"},{"card":{"id":"nat-enb2m6-2","book":"I should have told you","real":"I should've said something","meaning":"Tendría que haber dicho algo / me arrepiento de haberme callado","when":"Con amigos, al reconocer un silencio. En una disculpa formal o en el Writing, la misma frase se pone en hindsight: «In hindsight, I ought to have». La contracción should've no entra en un correo a un comité.","register":"amigos","exam":"In hindsight, I ought to have","note":"«Said something» es más vago que «told you»: en la calle basta. En el examen, nombra qué.","sound":"ai SHÚ-dav sed SÁM-zing","level":"b2","produce":true,"itemId":"enb2m6natsouldvesaid"},"lessonId":"enb2m6l2","level":"b2"},{"card":{"id":"nat-enb2m6-1","book":"I am sorry","real":"My bad","meaning":"Culpa mía / lo siento","when":"Con amigos, por una cosa pequeña y reciente: se te ha olvidado el azúcar, has llegado diez minutos tarde. En un correo de trabajo, en una disculpa de examen o cuando el daño tiene nombre, no cabe: allí se escribe «I sincerely apologise for».","register":"amigos","exam":"I sincerely apologise for","note":"Americana de origen y ya británica de café. Dos palabras. Si el daño es serio, dos palabras no bastan, y se nota.","sound":"mai bad","level":"b2","produce":true,"itemId":"enb2m6natmybad"},"lessonId":"enb2m6l4","level":"b2"},{"card":{"id":"nat-enb2m6-4","book":"That is not what I meant","real":"No, hang on — what I meant was","meaning":"No, espera: lo que quería decir era…","when":"En una conversación, cuando te oyes la frase torcida y la paras a mitad. En el Speaking de examen, la misma reparación se dice «Allow me to rephrase that»: cierra el turno anterior y abre el bueno, y puntúa.","register":"amigos","exam":"Allow me to rephrase that","note":"Hang on no es hang up (colgar). On = espera un segundo. Up = cuelgas. El phrasal que ya conoces, con la partícula que cambia el oficio.","sound":"nou, jang on — uot ai ment uos̬","level":"b2","produce":true,"itemId":"enb2m6nathangon"},"lessonId":"enb2m6l5","level":"b2"},{"card":{"id":"nat-enb2m6-3","book":"I made a mistake","real":"I messed up","meaning":"La pifié / me equivoqué","when":"Con amigos y compañeros, cuando el daño es tuyo y no quieres un discurso. En el Writing y en una disculpa a alguien con más poder en la habitación, la misma asunción se dice «I take full responsibility». Messed up en un correo a un comité es un error de registro.","register":"amigos","exam":"I take full responsibility","note":"Up aquí no es colgar ni esperar: es «hasta el fondo». El phrasal entero es el bloque. No se calca «*I messed».","sound":"ai mest ap","level":"b2","produce":true,"itemId":"enb2m6natmessedup"},"lessonId":"enb2m6l7","level":"b2"},{"card":{"id":"nat-enb2m7-1","book":"It was very good","real":"It was banging","meaning":"Estaba buenísimo / estaba de muerte","when":"Con amigos, de comida, de una noche, de un concierto. En una reseña escrita o en el Writing, la misma valoración se dice «The food was outstanding». Banging en un informe es un error de registro, no de entusiasmo.","register":"amigos","exam":"The food was outstanding","note":"Banging de comida es británico reciente. Quien lo ignore y ponga very good no falla; quien lo ponga en la reseña del examen, sí, por registro.","sound":"it uos̬ BÁN-ging","level":"b2","produce":true,"itemId":"enb2m7natbanging"},"lessonId":"enb2m7l1","level":"b2"},{"card":{"id":"nat-enb2m7-2","book":"postpone","real":"put it off","meaning":"aplazarlo","when":"Put off es lo que se dice. Postpone es lo que escribe quien no se quiere arriesgar con un phrasal — y es correcto. En el Writing formal, postpone y defer puntúan; en el Speaking, put it off suena a persona. Elegir siempre el latino es evitación, y ahora tiene nombre.","register":"neutral","exam":"postpone / defer","note":"Esta es la tarjeta que te pone el espejo. Si en el ejercicio de paraphrase te ha salido postpone de primeras, te has reconocido.","sound":"put it of","level":"b2","produce":true,"itemId":"enb1m6putoff"},"lessonId":"enb2m7l3","level":"b2"},{"card":{"id":"nat-enb2m7-4","book":"very expensive","real":"a bit steep","meaning":"un poco salado (el precio)","when":"Con amigos, de una cuenta. En una reseña, el matiz que puntúa es «on the pricey side»; si de verdad no lo vale, «overpriced». Steep en un Writing formal es aceptable; very expensive es el B1.","register":"amigos","exam":"on the pricey side / overpriced","note":"Steep de cuesta ya lo tenías. Steep de precio es la acepción B2, igual que los phrasals de la L3: misma palabra, oficio nuevo.","sound":"a bit stiip","level":"b2","produce":true,"itemId":"enb2m7abitsteep"},"lessonId":"enb2m7l4","level":"b2"},{"card":{"id":"nat-enb2m7-3","book":"I stopped smoking","real":"I packed it in","meaning":"Lo dejé / dejé ese hábito","when":"Con amigos, de un hábito: azúcar, tabaco, un especial de la carta que no funciona. En el Writing, «I gave up smoking» / «I stopped eating sugar». Packed it in en una reseña formal es registro de más a la calle.","register":"amigos","exam":"I gave up smoking","note":"Stop doing / stop to do sigue en pie: packed it in es solo el de dejar del todo. No existe packed it in to eat.","sound":"ai pakt it in","level":"b2","produce":true,"itemId":"enb2m7natpackeditin"},"lessonId":"enb2m7l7","level":"b2"},{"card":{"id":"nat-enb2m8-1","book":"On the other hand","real":"Then again","meaning":"Por otro lado / pensándolo bien","when":"Con amigos, al girar un argumento sin montar una subordinada. En el ensayo y en el Writing, la misma vuelta se dice «Whereas» o «By contrast». Then again en un informe es registro de menos.","register":"amigos","exam":"Whereas / By contrast","note":"On the other hand es B1 y sigue valiendo. Whereas es el que el EVP marcó como B2 y el curso no te dio hasta hoy.","sound":"den a-GHÉN","level":"b2","produce":true,"itemId":"enb2m8natthenagain"},"lessonId":"enb2m8l1","level":"b2"},{"card":{"id":"nat-enb2m8-2","book":"It is true that… but","real":"Alright, fair enough, but","meaning":"Vale, de acuerdo, pero…","when":"Con amigos, al conceder sin montar un ensayo. En el Writing, el molde que puntúa es «Admittedly, … Nevertheless,». Fair enough en un informe es registro de menos; Admittedly en un café, de más.","register":"amigos","exam":"Admittedly, … Nevertheless,","note":"La concesión es la función nueva del nivel. Sin ella, argumentas como en B1: una lista. Con ella, evalúas. Eso es todo el módulo.","sound":"óol-ráit, féar i-NÁF, bat","level":"b2","produce":true,"itemId":"enb2m8natfairenoughbut"},"lessonId":"enb2m8l3","level":"b2"},{"card":{"id":"nat-enb2m8-4","book":"In my opinion","real":"If you ask me","meaning":"Si quieres que te diga / en mi opinión","when":"Con amigos, cuando te piden qué piensas. En un ensayo, la misma tesis se pone sin yo: «It could be argued that». If you ask me en un Writing 1 formal es registro de menos; It could be argued that en un Part 1 oral, de más. Elige la habitación.","register":"amigos","exam":"It could be argued that","note":"Quitarse del medio es la cuarta nativa del módulo, y es la pericia: la opinión sin «yo». El B1 anunciaba I think. El B2, a veces, no hace falta que aparezcas.","sound":"if yu aask mi","level":"b2","produce":true,"itemId":"enb2m8natifyouaskme"},"lessonId":"enb2m8l5","level":"b2"},{"card":{"id":"nat-enb2m8-3","book":"because of this","real":"So, yeah","meaning":"Pues eso / así que bueno","when":"Con amigos, al cerrar una explicación que ya se ha entendido. En el ensayo, la misma consecuencia se dice «as a result» o «consequently». So, yeah en un Writing es un error de registro, no de lógica.","register":"amigos","exam":"as a result / consequently","note":"Yeah no es yes: es el cierre que da por sentado que el otro ya ha llegado. En un argumento, llegar no basta: hay que nombrarlo.","sound":"sóu, yé","level":"b2","produce":true,"itemId":"enb2m8natsoyeah"},"lessonId":"enb2m8l7","level":"b2"},{"card":{"id":"nat-enb2m9-1","book":"After I finished, I left.","real":"Soon as I was done, I was off.","meaning":"En cuanto terminé, me fui.","when":"La de la calle es de andén y de mensaje. En el Writing y en el monólogo del examen, la no finita. After I finished no está mal —está en B1— y es justo la que hay que dejar de usar cuando te están midiendo el rango.","register":"amigos","exam":"Having finished, I left.","note":"Soon as pierde el as; I was off es el phrasal de «me largué». Ninguna de las dos se escribe en una propuesta.","sound":"suun as ai uos dan, ai uos of","level":"b2","produce":true,"itemId":"enb2m9nathavingfinished"},"lessonId":"enb2m9l1","level":"b2"},{"card":{"id":"nat-enb2m9-2","book":"which was very good","real":"which was nice","meaning":"lo cual estuvo bien / nos vino bien","when":"La relativa de frase entera se oye todo el rato en el habla, casi siempre con nice, good, a relief. En el Writing, el verbo tiene que evaluar de verdad: proved invaluable, made a real difference, came as a relief. Which was nice en un informe suena a recado.","register":"neutral","exam":"which proved invaluable","note":"Va con coma porque no describe un nombre: comenta todo lo anterior. Quítala y has escrito otra frase.","sound":"uich uos náis","level":"b2","produce":true,"itemId":"enb2m9natwhichproved"},"lessonId":"enb2m9l3","level":"b2"},{"card":{"id":"nat-enb2m9-3","book":"the flat about which I told you","real":"the flat I told you about","meaning":"el piso del que te hablé","when":"Hablando, siempre la de la preposición al final, y también en el Writing: no es un bajón de registro. About which se reserva para un informe muy formal o para cuando el que escribe está demostrando que se sabe la gramática del siglo XIX.","register":"neutral","exam":"the flat that I mentioned earlier","note":"El examen y la calle coinciden en la preposición al final. Lo que cambia es el verbo: told you about en la conversación, mentioned earlier en el papel.","sound":"de flat ai tóuld yu a-BÁUT","level":"b2","produce":true,"itemId":"enb2m9nattoldyouabout"},"lessonId":"enb2m9l5","level":"b2"},{"card":{"id":"nat-enb2m9-4","book":"It was cancelled.","real":"It got binned.","meaning":"Lo han cancelado / lo han tirado a la basura (el servicio, el plan, el tren).","when":"Got binned es de andén y de grupo de WhatsApp, y se dice del tren, del concierto y del plan de las ocho. En una reclamación, en un Writing y en el Speaking del examen, The service was suspended o The service has been cancelled. Binnear un tren en el papel te baja el registro de golpe.","register":"jerga","exam":"The service was suspended.","note":"Get-passive es la pasiva de la calle. El B2 la reconoce; no la escribe en una propuesta.","sound":"it got bind","level":"b2","produce":true,"itemId":"enb2m9natsuspended"},"lessonId":"enb2m9l7","level":"b2"},{"card":{"id":"nat-enb2m10-1","book":"she said quietly","real":"she went, all quiet","meaning":"dijo, en voz baja / se quedó toda seria","when":"Went, all quiet es de conversación: el verbo de decir se vuelve go, y el adverbio se vuelve un all + adjetivo. En el relato del examen, she said quietly o murmured Nora. Went no se escribe en una composition.","register":"amigos","exam":"she said quietly","note":"El examen y el libro coinciden aquí a propósito: la calle es la que se aparta. Murmured Nora es la variante de inversión, también de examen.","sound":"shi uent, ool KUÁI-et","level":"b2","produce":true,"itemId":"enb2m10shesaidquietly"},"lessonId":"enb2m10l3","level":"b2"},{"card":{"id":"nat-enb2m10-2","book":"It was very moving.","real":"It got me, that.","meaning":"Me llegó. Me tocó.","when":"It got me, that se dice después, con la coma y el that al final, como quien cierra el grifo. En el Writing y en el monólogo, I found it profoundly moving: el found it + adverbio + adjetivo es el molde que puntúa, y evita el it was very que suena a B1.","register":"amigos","exam":"I found it profoundly moving.","note":"Got me no se escribe. Profoundly no se dice en el café. Las dos columnas existen para no mezclarlas.","sound":"it got mi, dat","level":"b2","produce":true,"itemId":"enb2m10profoundlymoving"},"lessonId":"enb2m10l5","level":"b2"},{"card":{"id":"nat-enb2m10-4","book":"He told me not to go.","real":"He was like, don't go.","meaning":"Me dijo que no fuera.","when":"Was like + la orden en directo es de conversación, de contar lo que dijo alguien. En el relato del examen, he told me not to go o he advised me not to go. Like no es un verbo de decir en el papel.","register":"amigos","exam":"He advised me not to go.","note":"El not se pega al infinitivo. He advised me to not to go duplica el to y es el calco.","sound":"ji uos̬ laik, dóunt góu","level":"b2","produce":true,"itemId":"enb2m10headvisedmenotto"},"lessonId":"enb2m10l7","level":"b2"},{"card":{"id":"nat-enb2m10-3","book":"I had never seen it before.","real":"Never seen it before, me.","meaning":"Yo no lo había visto nunca.","when":"La elipsis con me al final es de conversación, de andén, de salida de la galería. En el Writing y en el monólogo, la inversión: Never before had I seen…, que sí es B2. I had never seen it before también vale, y es la de B1: correcta, y es evitación si ya sabes la otra.","register":"amigos","exam":"Never before had I seen it.","note":"El me al final no es un complemento: es un sello de «hablo yo». En el papel no se pone.","sound":"né-va siin it bi-FÓO, mi","level":"b2","produce":true,"itemId":"enb2m10neverbeforehadiseen"},"lessonId":"enb2m10l9","level":"b2"},{"card":{"id":"nat-enb2m11-3","book":"Not only is it cheap, it is fast.","real":"It's cheap AND it's quick.","meaning":"Es barato y, además, rápido.","when":"AND con las dos mayúsculas se oye cuando alguien está vendiendo las dos virtudes a la vez, en el rellano. En el Speaking y en el Writing, Not only is it cheaper, but it is also faster. La inversión es el énfasis; AND es el de la calle.","register":"amigos","exam":"Not only is it cheaper, but it is also faster.","note":"Cheaper / faster, en comparativo, es lo que el examen quiere si estás comparando dos planes. Cheap / fast vale si no comparas.","sound":"its chiip and its kuik","level":"b2","produce":true,"itemId":"enb2m11notonlyisitcheaper"},"lessonId":"enb2m11l2","level":"b2"},{"card":{"id":"nat-enb2m11-1","book":"I do not agree.","real":"Yeah, I'm not sure about that.","meaning":"Eso no lo veo claro.","when":"I'm not sure about that es la forma británica de decir no sin romper la mesa. En el Part 3 del examen puedes usarla; si quieres subir el rango, I see it rather differently. I do not agree es de carta, no de interlocutor.","register":"amigos","exam":"I see it rather differently.","note":"Yeah al frente suaviza. Quítalo en el oral si te está saliendo demasiado de café.","sound":"yea, aim not shóo a-BÁUT dat","level":"b2","produce":true,"itemId":"enb2m11iseeitratherdifferently"},"lessonId":"enb2m11l5","level":"b2"},{"card":{"id":"nat-enb2m11-2","book":"We should decide.","real":"Let's just call it.","meaning":"Cerremos ya / decidamos de una vez.","when":"Call it es de rellano y de pub: se acaba la discusión. En el Part 3, Shall we agree on…? es lo que oye el examinador como cierre de plan. We should decide es el libro, y se queda corto porque no nombra el qué.","register":"amigos","exam":"Shall we agree on the lift?","note":"Call it no lleva objeto del tema: por eso en el examen hay que poner on the lift, on a split, on Friday.","sound":"lets dchast kool it","level":"b2","produce":true,"itemId":"enb2m11shallweagreeon"},"lessonId":"enb2m11l8","level":"b2"},{"card":{"id":"nat-enb2m11-4","book":"That is not fair.","real":"That's out of order.","meaning":"Eso no se hace / eso es injusto.","when":"Out of order, dicho de una persona o de una decisión, es moral, no mecánico (el ascensor out of order es otra ficha, del A2). En el oral y en la carta, That strikes me as unfair. That is not fair es el libro, y se queda corto de rango.","register":"amigos","exam":"That strikes me as unfair.","note":"Out of order de máquina y out of order de conducta se distinguen por el sujeto: the lift / that (lo que acaba de decir alguien).","sound":"dats áut ov ÓO-da","level":"b2","produce":true,"itemId":"enb2m11thatstrikemeasunfair"},"lessonId":"enb2m11l9","level":"b2"},{"card":{"id":"nat-enb2m12-4","book":"In conclusion, I think…","real":"So yeah, that's me.","meaning":"Bueno, eso es todo / en conclusión.","when":"So yeah, that's me cierra un café. In conclusion, I think es de manual y suena a recitar. El monólogo de dos minutos se cierra con To sum up, the evidence points to… o And that's everything I wanted to say: un cierre dicho a propósito, con una tesis, no un apagón.","register":"amigos","exam":"To sum up, the evidence points to…","note":"In conclusion también vale y es B2. Evidence points to sube el rango porque quita el I think.","sound":"sóu yea, dats mi","level":"b2","produce":true,"itemId":"enb2m12tosumuptheevidence"},"lessonId":"enb2m12l7","level":"b2"},{"card":{"id":"nat-enb2m12-3","book":"I think that…","real":"Reckon.","meaning":"Yo creo.","when":"Reckon es una palabra, y en el café basta. En el Part 1 del B2 las preguntas ya piden hipótesis y responsabilidad: From my perspective / It seems to me que sostienen una razón. I think that también vale, y se queda corto de rango si es lo único que te sale.","register":"amigos","exam":"From my perspective,","note":"Reckon no lleva that. From my perspective lleva coma y sigue la tesis.","sound":"RÉ-kon","level":"b2","produce":true,"itemId":"enb2m12frommyperspective"},"lessonId":"enb2m12l8","level":"b2"},{"card":{"id":"nat-enb2m12-2","book":"Could you repeat that?","real":"Sorry, say again?","meaning":"¿Puedes repetir?","when":"Say again es de café y de andén. En el oral, I beg your pardon, could you repeat the question?: la reparación puntúa, y pedir que te la repitan es mejor que inventar la pregunta. Could you repeat that también vale; la de examen nombra the question, que es lo que el interlocutor acaba de hacer.","register":"amigos","exam":"I beg your pardon, could you repeat the question?","note":"Pardon aquí no es perdón de culpa: es «no he oído». El beg your lo sube de registro sin dejar de ser una petición.","sound":"só-ri, séi a-GUÉN","level":"b2","produce":true,"itemId":"enb2m12ibegyourpardon"},"lessonId":"enb2m12l9","level":"b2"},{"card":{"id":"nat-enb2m12-1","book":"I am nervous.","real":"I'm bricking it.","meaning":"Estoy cagado de miedo.","when":"Bricking it es de vestuario y de WhatsApp, y se oye mucho el día antes. En el oral, I am rather apprehensive: el nervio dicho como un adulto que se examina, no como un chiste. I am nervous también vale, y se queda en B1.","register":"jerga","exam":"I am rather apprehensive.","note":"Brick aquí no es un ladrillo que se tira: es el cuerpo que se te pone de ladrillo. No se explica en el examen. Se evita.","sound":"aim BRÍ-king it","level":"b2","produce":true,"itemId":"enb2m12iamratherapprehensive"},"lessonId":"enb2m12l10","level":"b2"}],
};
